INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "空", "is_correct": true, "explanation": "正确：空与实构成反义，指里面没有东西，与“里面充满”相对。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容词，指没有污物，与“实”不构成反义。"}, {"text": "凉", "is_correct": false, "explanation": "凉：形容词，指温度低，与“实”不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮：形容词，指光线充足，与“实”不构成反义。"}], "correct_answer": "空", "explanations": {"空": "正确：空与实构成反义，指里面没有东西，与“里面充满”相对。", "干净": "干净：形容词，指没有污物，与“实”不构成反义。", "凉": "凉：形容词，指温度低，与“实”不构成反义。", "亮": "亮：形容词，指光线充足，与“实”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "实是里面满满的，不是空的。", "primary_collocate": null, "pronunciation": "shí", "ipa": "ʂʐ̩˧˥", "syllable_count": 1, "sentences": [{"text": "这个球是实的，不是空的。", "target_word": "实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这面墙是实的，敲起来没有声音。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你摸摸，这块木头里面是实的。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子很重，里面是实的。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根铁棍是实的，那根是空的。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块冬瓜是实的，拿在手里很沉。", "target_word": "实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空心的太轻，我想要实的。", "target_word": "实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个门是实的，不是空的，很重。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌腿是实的，所以不容易坏。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "里面是空的还是实的？打开看看。", "target_word": "实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "實", "label": "繁体"}, {"form": "实心", "label": "复合"}], "register": "口语", "sense_fingerprint": "实：里面充满、不是空的（与空相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89977fd-f280-49cb-8f9f-d28e7bd372bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实", "is_correct": true, "explanation": "正确答案：实（shí），形容内部充满、不空。"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是“是”。"}, {"text": "直", "is_correct": false, "explanation": "zh 与 sh 声母不同，意思是“直”。"}, {"text": "迟", "is_correct": false, "explanation": "ch 与 sh 声母不同，意思是“迟”。"}, {"text": "失", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是“失”。"}], "explanations": {"实": "正确答案：实（shí），形容内部充满、不空。", "是": "shì（第四声）与 shí（第二声）声调不同，意思是“是”。", "直": "zh 与 sh 声母不同，意思是“直”。", "迟": "ch 与 sh 声母不同，意思是“迟”。", "失": "shī（第一声）与 shí（第二声）声调不同，意思是“失”。"}, "sentence_index": null, "correct_answer": "实"}, "level_3": {"options": [{"text": "实", "is_correct": true, "explanation": "正确：实表示里面满满的、不空，与“不是空的”相合。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”与后半句“不是空的”直接矛盾。"}, {"text": "方", "is_correct": false, "explanation": "搭配：球通常是圆的，说“方的”不合常理，不能用于球。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”是味道，不能用来形容球的内部状态。"}], "explanations": {"实": "正确：实表示里面满满的、不空，与“不是空的”相合。", "空": "语义：“空”与后半句“不是空的”直接矛盾。", "方": "搭配：球通常是圆的，说“方的”不合常理，不能用于球。", "甜": "搭配：“甜”是味道，不能用来形容球的内部状态。"}, "sentence_index": 0, "correct_answer": "实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块海绵很实，里面全是空隙。", "explanation": "这里应该用〈松软〉。实指里面充满、不空，海绵里满是空隙，与「很实」相矛盾。"}, {"text": "这块泡沫很实，里面全是气泡。", "explanation": "这里应该用〈轻软〉。实指里面充满实物，泡沫里全是气泡，与「很实」相矛盾。"}, {"text": "这个瓶子很实，里面一滴酒也没有。", "explanation": "这里应该用〈空〉。实指里面充满，瓶子里一滴酒也没有，与「很实」相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实", "is_correct": true, "explanation": "正确答案：实（shí），形容内部充满、不空。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是“使用”。"}, {"text": "吃", "is_correct": false, "explanation": "ch 与 sh 声母不同，声调也不同，意思是“吃”。"}, {"text": "池", "is_correct": false, "explanation": "ch 与 sh 声母不同，意思是“池子”。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是“诗”。"}], "explanations": {"实": "正确答案：实（shí），形容内部充满、不空。", "使": "shǐ（第三声）与 shí（第二声）声调不同，意思是“使用”。", "吃": "ch 与 sh 声母不同，声调也不同，意思是“吃”。", "池": "ch 与 sh 声母不同，意思是“池子”。", "诗": "shī（第一声）与 shí（第二声）声调不同，意思是“诗”。"}, "sentence_index": null, "correct_answer": "实"}, "level_3": {"options": [{"text": "实", "is_correct": true, "explanation": "正确：实表示里面充满、不空，与“空心的太轻”形成对比，与“想要”的内容相合。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”与前半句“空心的太轻”同义重复且矛盾，不能说想要轻的。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”指不干净，不是人想要的物体性质，搭配不当。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”指温度高，不能作为想要的物体的性质，这样说不合常理。"}], "explanations": {"实": "正确：实表示里面充满、不空，与“空心的太轻”形成对比，与“想要”的内容相合。", "轻": "语义：“轻”与前半句“空心的太轻”同义重复且矛盾，不能说想要轻的。", "脏": "搭配：“脏”指不干净，不是人想要的物体性质，搭配不当。", "烫": "搭配：“烫”指温度高，不能作为想要的物体的性质，这样说不合常理。"}, "sentence_index": 6, "correct_answer": "实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个纸箱很实，里面一个东西都没有。", "explanation": "这里应该用〈空〉。实指里面充满，纸箱里却一个东西都没有，与「很实」相矛盾。"}, {"text": "这间屋子很实，里面一件家具也没有。", "explanation": "这里应该用〈空荡〉。实指里面充满，屋子里一件家具也没有，与「很实」相矛盾。"}, {"text": "这个罐子很实，打开一看，里面是空的。", "explanation": "这里应该用〈空〉。实指里面充满，罐子里是空的，与「很实」相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个球是实很的，不是空的。", "corrected_sentence": "这个球是很实的，不是空的。", "error_description": "错误：“实很”。正确：“很”要紧贴形容词放在前面，说“很实的”。“很”表示程度，放在“实”后面语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木头是实了的，不是空心的。", "corrected_sentence": "这块木头是实的，不是空心的。", "error_description": "错误：“实了的”。正确：“是……的”结构中不加“了”，应为“这块木头是实的”。“了”表示变化，与这里描述的固有状态不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
