INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "店是卖东西的地方。", "primary_collocate": null, "pronunciation": "diàn", "ipa": "tjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这家店卖的东西很便宜。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店门口放着一些水果。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去店里买牛奶。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸在街上开店。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个店什么都有。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的东西都很新。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个店晚上十点才关门。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常常去街角的店买面包。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店给我们便宜了一块钱。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在店里看了很久，没有买。", "target_word": "店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书店", "label": "复合"}, {"form": "商店", "label": "复合"}], "register": "中性", "sense_fingerprint": "店：卖东西的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "店", "is_correct": true, "explanation": "正确答案。店（diàn）：卖东西的地方。"}, {"text": "点", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点、小点，不是店。"}, {"text": "断", "is_correct": false, "explanation": "duàn 与 diàn 韵母不同（uan 与 ian），意思是断开，不是店。"}, {"text": "变", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），意思是改变，不是店。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 diàn 声母不同（n 与 d），意思是朗读，不是店。"}], "explanations": {"店": "正确答案。店（diàn）：卖东西的地方。", "点": "diǎn（第三声）与 diàn（第四声）声调不同，意思是点、小点，不是店。", "断": "duàn 与 diàn 韵母不同（uan 与 ian），意思是断开，不是店。", "变": "biàn 与 diàn 声母不同（b 与 d），意思是改变，不是店。", "念": "niàn 与 diàn 声母不同（n 与 d），意思是朗读，不是店。"}, "sentence_index": null, "correct_answer": "店"}, "level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行不卖东西，与“卖的东西很便宜”不合。"}, {"text": "店", "is_correct": true, "explanation": "正确答案。“店”是卖东西的地方，与“这家”和“卖的东西很便宜”的语境相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不出售商品，“这家医院卖的东西很便宜”说不通。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：量词“家”不能用于桥，桥要用“座”，不能说“这家桥”。"}], "explanations": {"银行": "语义：银行不卖东西，与“卖的东西很便宜”不合。", "店": "正确答案。“店”是卖东西的地方，与“这家”和“卖的东西很便宜”的语境相符。", "医院": "语义：医院不出售商品，“这家医院卖的东西很便宜”说不通。", "桥": "搭配：量词“家”不能用于桥，桥要用“座”，不能说“这家桥”。"}, "sentence_index": 0, "correct_answer": "店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爸爸在街上吃店。", "explanation": "这里应该用〈饭馆〉，指可以吃饭的地方。〈店〉指售卖商品的场所，不能被“吃”。"}, {"text": "他爸爸在店里教书。", "explanation": "这里应该用〈学校〉，指教书的地方。〈店〉指售卖商品的场所，不能用来教书。"}, {"text": "他在街上做店，每天卖衣服。", "explanation": "这里应该用〈做生意〉。“店”是名词，表示场所，不能直接作“做”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "店", "is_correct": true, "explanation": "正确答案。店（diàn）：卖东西的地方。"}, {"text": "段", "is_correct": false, "explanation": "duàn 与 diàn 韵母不同（uan 与 ian），意思是段落、一段，不是店。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 diàn 声母不同（p 与 d），意思是片子、片儿，不是店。"}, {"text": "典", "is_correct": false, "explanation": "diǎn 与 diàn 声调不同，意思是典范、典礼，属于书面词，不是店。"}], "explanations": {"店": "正确答案。店（diàn）：卖东西的地方。", "段": "duàn 与 diàn 韵母不同（uan 与 ian），意思是段落、一段，不是店。", "片": "piàn 与 diàn 声母不同（p 与 d），意思是片子、片儿，不是店。", "典": "diǎn 与 diàn 声调不同，意思是典范、典礼，属于书面词，不是店。"}, "sentence_index": null, "correct_answer": "店"}, "level_3": {"options": [{"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园晚上十点不营业，不会这样才关门。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不会关门，“关门”的对象应是店铺等场所。"}, {"text": "店", "is_correct": true, "explanation": "正确答案。“店”是卖东西的地方，能够营业和关门，与“晚上十点才关门”的语境相符。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“关门”只能用于店铺等场所，不能和“花”搭配。"}], "explanations": {"幼儿园": "语义：幼儿园晚上十点不营业，不会这样才关门。", "河": "语义：河不会关门，“关门”的对象应是店铺等场所。", "店": "正确答案。“店”是卖东西的地方，能够营业和关门，与“晚上十点才关门”的语境相符。", "花": "搭配：“关门”只能用于店铺等场所，不能和“花”搭配。"}, "sentence_index": 6, "correct_answer": "店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店是我的老师，每天都教我们很多。", "explanation": "这里应该用〈老师〉，指教书的人。〈店〉指售卖商品的场所，不能指人。"}, {"text": "他在店里踢足球，同学们都在看。", "explanation": "这里应该用〈球场〉，指踢球的地方。〈店〉指售卖商品的场所，不能用来踢球。"}, {"text": "他是这家店的店，每天都很忙。", "explanation": "这里应该用〈店长〉，指管理店铺的人。〈店〉指场所，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角那位店每天早上七点开门。", "corrected_sentence": "街角那家店每天早上七点开门。", "error_description": "错误形式是“那位店”，正确形式是“那家店”。量词错误：“位”用于人，店应用“家”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他妈妈在学校门口开一条店，生意很好。", "corrected_sentence": "他妈妈在学校门口开一家店，生意很好。", "error_description": "错误形式是“一条店”，正确形式是“一家店”。量词错误：“条”用于长条形的东西，店应用“家”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
