INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "忘是以前记得，现在想不起来了。", "primary_collocate": null, "pronunciation": "wàng", "ipa": "wɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这个字我以前会写，现在忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的名字我忘了，想不起来。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十年没见，我差点忘了她的样子。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那首歌的歌词，我都忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候学的英语，早就忘了。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了他住在哪儿，只记得是一条小街。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把过去的事都忘了。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次旅行很美，我一直没忘。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路我走过，现在忘了怎么走了。", "target_word": "忘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了自己的电话号码。", "target_word": "忘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘了", "label": "体标"}, {"form": "忘过", "label": "体标"}, {"form": "忘记", "label": "复合"}], "register": "口语", "sense_fingerprint": "忘：以前记得的事现在想不起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd89977fd-f280-49cb-8f9f-d28e7bd372bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示以前记得的事现在想不起来。"}, {"text": "万", "is_correct": false, "explanation": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。"}, {"text": "网", "is_correct": false, "explanation": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。"}, {"text": "王", "is_correct": false, "explanation": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示以前记得的事现在想不起来。", "万": "万（wàn）与忘（wàng）只差韵尾 ng 和 n，意思是「一万」。", "网": "网（wǎng）与忘（wàng）声调不同：网是第三声，忘是第四声，意思是「网」。", "放": "放（fàng）与忘（wàng）声母不同：f 与 w，意思是「放置」。", "王": "王（wáng）与忘（wàng）声调不同：王是第二声，意思是「国王」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「以前会写，现在忘了」表示以前记得，现在想不起来。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指用水清洗，与「以前会写」的记忆无关。"}, {"text": "放", "is_correct": false, "explanation": "配价：「放」要求处所宾语，「放了」不能用来说明字的记忆状态。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」要接饮料，不能说「字……喝了」。"}], "explanations": {"忘": "正确。「以前会写，现在忘了」表示以前记得，现在想不起来。", "洗": "语义：「洗」指用水清洗，与「以前会写」的记忆无关。", "放": "配价：「放」要求处所宾语，「放了」不能用来说明字的记忆状态。", "喝": "搭配：「喝」要接饮料，不能说「字……喝了」。"}, "sentence_index": 0, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都认真忘那首歌的歌词。", "explanation": "这里应该用〈学〉。「忘」表示想不起来，不表示学习的过程。"}, {"text": "老师让我们明天忘好这篇课文。", "explanation": "这里应该用〈背〉。「忘」表示想不起来，不能表示努力记住课文。"}, {"text": "我很想家，每天晚上都忘妈妈。", "explanation": "这里应该用〈想〉。「忘」表示想不起来，思念某人要说「想」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86603, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确答案。忘（wàng）表示以前记得的事现在想不起来。"}, {"text": "往", "is_correct": false, "explanation": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。"}, {"text": "汪", "is_correct": false, "explanation": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。"}, {"text": "亡", "is_correct": false, "explanation": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}], "explanations": {"忘": "正确答案。忘（wàng）表示以前记得的事现在想不起来。", "往": "往（wǎng）与忘（wàng）声调不同：往是第三声，意思是「朝、向」。", "汪": "汪（wāng）与忘（wàng）声调不同：汪是第一声，常见于「汪汪」。", "亡": "亡（wáng）与忘（wàng）声调不同：亡是第二声，意思是「死亡」。"}, "sentence_index": null, "correct_answer": "忘"}, "level_3": {"options": [{"text": "忘", "is_correct": true, "explanation": "正确。「老人把过去的事都忘了」表示过去记得的事现在想不起来。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」要接食物，「把过去的事都吃了」不成搭配。"}, {"text": "跑", "is_correct": false, "explanation": "配价：「跑」是不及物动词，不能带「过去的事」作宾语。"}, {"text": "卖", "is_correct": false, "explanation": "语义：「卖」指出售，与「过去的事」的记忆无关。"}], "explanations": {"忘": "正确。「老人把过去的事都忘了」表示过去记得的事现在想不起来。", "吃": "搭配：「吃」要接食物，「把过去的事都吃了」不成搭配。", "跑": "配价：「跑」是不及物动词，不能带「过去的事」作宾语。", "卖": "语义：「卖」指出售，与「过去的事」的记忆无关。"}, "sentence_index": 6, "correct_answer": "忘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天认真忘生词，所以学得很快。", "explanation": "这里应该用〈记〉。「忘」表示想不起来，不能用来表示记忆的努力。"}, {"text": "我每天都忘你，好想你。", "explanation": "这里应该用〈想〉。「忘」表示以前记得、现在想不起来，思念某人要说「想」，「忘你」与句意矛盾。"}, {"text": "这个故事很有意思，我要把它忘在心里。", "explanation": "这里应该用〈记〉。「忘」表示想不起来，「记在心里」才是记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed7a68b-116f-45a1-a7a5-a72c0a5e2ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
