INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86606, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "使人非常害怕的。", "primary_collocate": null, "pronunciation": "kǒng bù", "ipa": "kʰʊŋ˨˩˦ pu˥˩", "syllable_count": 2, "sentences": [{"text": "他给我们看了一张恐怖的照片。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一次恐怖的经历，我永远忘不了。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上走在黑黑的路上，真有点儿恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥喜欢恐怖的电影，我却不敢看。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的晚上安静得有点恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里传来恐怖的叫声，大家都停下了脚步。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只大蜘蛛长得真恐怖。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个恐怖的黑影从窗外走过。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的鬼故事恐怖极了。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场车祸的画面太恐怖了，我不敢再看。", "target_word": "恐怖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐怖片", "label": "复合词"}, {"form": "恐怖故事", "label": "复合词"}, {"form": "恐怖电影", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使人非常害怕的，常作定语修饰名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447d43e2-a23d-48e8-8047-2c5e16313adc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐怖", "is_correct": true, "explanation": "正确：「恐怖的照片」指让人害怕的照片，与句意相符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：「聪明」形容人的智力，照片不能用聪明来形容。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：「辣」指味道，照片不能说辣。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：「吵闹」指声音大，照片没有声音，句子意思不通。"}], "explanations": {"恐怖": "正确：「恐怖的照片」指让人害怕的照片，与句意相符。", "聪明": "搭配：「聪明」形容人的智力，照片不能用聪明来形容。", "辣": "搭配：「辣」指味道，照片不能说辣。", "吵闹": "语义：「吵闹」指声音大，照片没有声音，句子意思不通。"}, "sentence_index": 0, "correct_answer": "恐怖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做了一道恐怖的菜。", "explanation": "这里应该用〈美味〉。恐怖表示让人害怕，形容好吃的菜要用美味。"}, {"text": "那个人经常恐怖邻居。", "explanation": "这里应该用〈恐吓〉。恐吓是动词，可以带宾语「邻居」；恐怖是形容词，不能直接带人作宾语。"}, {"text": "宿舍里有一张恐怖的书桌。", "explanation": "这里应该用〈整洁〉。恐怖形容让人害怕的事物，书桌整齐干净时不能用恐怖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐怖", "is_correct": true, "explanation": "正确：「长得真恐怖」描述大蜘蛛的样子让人害怕，与句意相符。"}, {"text": "温柔", "is_correct": false, "explanation": "体貌：「温柔」形容性情态度，不用来描述蜘蛛的长相。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：「清秀」形容人的相貌清雅，不能用来形容大蜘蛛。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：「严肃」形容人的神情态度，蜘蛛不能用来形容。"}], "explanations": {"恐怖": "正确：「长得真恐怖」描述大蜘蛛的样子让人害怕，与句意相符。", "温柔": "体貌：「温柔」形容性情态度，不用来描述蜘蛛的长相。", "清秀": "体貌：「清秀」形容人的相貌清雅，不能用来形容大蜘蛛。", "严肃": "搭配：「严肃」形容人的神情态度，蜘蛛不能用来形容。"}, "sentence_index": 6, "correct_answer": "恐怖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她戴着一条恐怖的项链。", "explanation": "这里应该用〈精致〉。恐怖表示让人害怕，形容做工细巧的项链要用精致。"}, {"text": "树枝上有一只恐怖的小鸟。", "explanation": "这里应该用〈活泼〉。恐怖指让人害怕，形容蹦蹦跳跳的小鸟要用活泼。"}, {"text": "妈妈给了我一个恐怖的拥抱。", "explanation": "这里应该用〈温暖〉。恐怖表示让人害怕，形容亲人的拥抱要用温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座老房子里有一个很恐怖声音。", "corrected_sentence": "那座老房子里有一个很恐怖的声音。", "error_description": "错误形式是「很恐怖声音」，正确形式是「很恐怖的声音」。「很恐怖」修饰名词时，后面要加「的」，省略后结构不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那部电影太恐怖的，我晚上不敢看。", "corrected_sentence": "那部电影太恐怖了，我晚上不敢看。", "error_description": "错误形式是「太恐怖的」，「太」修饰形容词作谓语时句末应用「了」表示感叹，不用「的」；应说「太恐怖了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
