INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86607, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "播放是把声音或画面放出来给人听、给人看。", "primary_collocate": null, "pronunciation": "bō fàng", "ipa": "pwo˥ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "电视台晚上八点播放新闻。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给大家播放了一个短片。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里一直播放着轻音乐。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院今天不播放这部电影。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里正在播放天气预报。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每天中午播放英语歌曲。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目已经播放过三次了。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，大屏幕上播放着公司的照片。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站里播放着提醒大家排队的广播。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上他们播放了孩子们的视频。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "播放了", "label": "体标"}, {"form": "播放着", "label": "体标"}, {"form": "播放过", "label": "体标"}, {"form": "播放器", "label": "复合"}], "register": "中性", "sense_fingerprint": "把声音或画面放出来给大家听或看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f0846f6-3efb-40f5-acd6-084c548b4338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86607, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播放", "is_correct": true, "explanation": "“播放”指把新闻的声音或画面放出来，符合句意。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”是做菜，不能用来指播出新闻。"}, {"text": "擦洗", "is_correct": false, "explanation": "搭配：“擦洗”接表面或污垢，不接“新闻”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语要是食物，不能接“新闻”。"}], "explanations": {"播放": "“播放”指把新闻的声音或画面放出来，符合句意。", "烹饪": "语义：“烹饪”是做菜，不能用来指播出新闻。", "擦洗": "搭配：“擦洗”接表面或污垢，不接“新闻”。", "吃": "配价：“吃”的宾语要是食物，不能接“新闻”。"}, "sentence_index": 0, "correct_answer": "播放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在门口播放了一个摊位。", "explanation": "这里应该用〈摆〉。播放只用于声音或画面，摊位是物体，要用摆。"}, {"text": "博物馆正在播放古代的瓷器。", "explanation": "这里应该用〈展示〉。播放只用于声音或画面，展示实物要用展示。"}, {"text": "我把书播放在桌子上。", "explanation": "这里应该用〈放〉。播放只用于声音和画面，不能表示把物品放在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播放", "is_correct": true, "explanation": "“播放”指把节目放出来，与“已经……过三次了”搭配，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补损坏的东西，不能用来指节目的播出次数。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊、报纸等，不用于节目。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”指把东西放在阳光下干燥，与节目无关。"}], "explanations": {"播放": "“播放”指把节目放出来，与“已经……过三次了”搭配，符合句意。", "修理": "语义：“修理”指修补损坏的东西，不能用来指节目的播出次数。", "出版": "搭配：“出版”用于书刊、报纸等，不用于节目。", "晾晒": "语义：“晾晒”指把东西放在阳光下干燥，与节目无关。"}, "sentence_index": 6, "correct_answer": "播放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈播放了一个西瓜。", "explanation": "这里应该用〈切〉。播放只用于声音或画面，西瓜是食物，要用切。"}, {"text": "他把包裹播放给朋友了。", "explanation": "这里应该用〈寄〉。播放用于声音或画面，邮寄包裹要用寄。"}, {"text": "小明在厨房里播放面包。", "explanation": "这里应该用〈烤〉。播放只用于声音或画面，面包要用烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台明晚播放了一部电影。", "corrected_sentence": "电视台明晚播放一部电影。", "error_description": "体标错误：“了”表示已完成的动作，不能与表示将来的时间“明晚”同用，应去掉“了”。正确说法：电视台明晚播放一部电影。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视里正在播放过一场足球比赛。", "corrected_sentence": "电视里正在播放一场足球比赛。", "error_description": "体标错误：“正在”表示动作进行中，“过”表示经历，两者不能同用，应去掉“过”。正确说法：电视里正在播放一场足球比赛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
