INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86608, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过设备放出声音或影像。", "primary_collocate": null, "pronunciation": "bō fàng", "ipa": "pwo˥ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我用手机播放了一首老歌。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑不能播放这个视频。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用音响播放这首歌。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把耳机插好，开始播放音乐。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视坏了，不能播放节目了。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机播放视频很慢。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点一下这个键，就可以播放录音。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器可以播放四种格式的视频。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正用平板电脑播放动画片。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音箱连上手机后，会自动播放歌曲。", "target_word": "播放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "播放了", "label": "体标"}, {"form": "播放着", "label": "体标"}, {"form": "播放过", "label": "体标"}, {"form": "播放器", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手机、电脑等设备放出音乐或视频", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f0846f6-3efb-40f5-acd6-084c548b4338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播放", "is_correct": true, "explanation": "“播放”指通过手机放出音乐，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水清洁东西，不能用于歌曲。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”接可以切开的东西，不接歌曲。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语要是食物，不能接“老歌”。"}], "explanations": {"播放": "“播放”指通过手机放出音乐，符合句意。", "洗": "语义：“洗”是用水清洁东西，不能用于歌曲。", "切": "搭配：“切”接可以切开的东西，不接歌曲。", "吃": "配价：“吃”的宾语要是食物，不能接“老歌”。"}, "sentence_index": 0, "correct_answer": "播放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把信播放到邮箱里。", "explanation": "这里应该用〈投递〉。播放只用于声音或画面，信件要用投递。"}, {"text": "妈妈在厨房里播放水。", "explanation": "这里应该用〈烧〉。播放只用于声音或画面，水要用烧。"}, {"text": "他用力播放门。", "explanation": "这里应该用〈推〉。播放不能接具体物体作宾语，推门要用推。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播放", "is_correct": true, "explanation": "“播放”指放出录音，符合“就可以……录音”的句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，不能用于录音。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”接表面或污渍，不接“录音”。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语要是衣物，不能接“录音”。"}], "explanations": {"播放": "“播放”指放出录音，符合“就可以……录音”的句意。", "煮": "语义：“煮”是加热食物，不能用于录音。", "擦": "搭配：“擦”接表面或污渍，不接“录音”。", "穿": "配价：“穿”的宾语要是衣物，不能接“录音”。"}, "sentence_index": 6, "correct_answer": "播放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他播放了一个苹果。", "explanation": "这里应该用〈削〉。播放只用于声音或画面，削苹果要用削。"}, {"text": "他把扣子播放在衣服上。", "explanation": "这里应该用〈缝〉。播放不能表示把物体固定在某处，缝扣子要用缝。"}, {"text": "他用笔播放信。", "explanation": "这里应该用〈写〉。播放用于声音或画面，写信要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用电脑播放器这部电影。", "corrected_sentence": "他用电脑播放这部电影。", "error_description": "词性错误：“播放器”是名词，指设备；这里是动词，应说“播放”，不能说“播放器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
