INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过努力而得到（成绩、成果、权利、同意等）。", "primary_collocate": null, "pronunciation": "qǔ dé", "ipa": "tɕʰy˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他取得了老师的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先要取得父母的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组取得了重要的研究成果。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她取得了在这里工作的权利。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们取得了休息的权利。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多年研究，他取得了重要成果。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要用这个房间，先取得经理的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店取得了经营许可。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的工作取得了很大的成绩。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没取得大家的同意。", "target_word": "取得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取得了", "label": "完成体"}, {"form": "取得过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "经过努力或手续而得到成果、权利、同意、许可等抽象的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得 qǔdé：经过手续或努力得到许可、权利等，是正确答案。"}, {"text": "去得", "is_correct": false, "explanation": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到许可」无关。"}, {"text": "举得", "is_correct": false, "explanation": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。"}, {"text": "处得", "is_correct": false, "explanation": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}], "explanations": {"取得": "取得 qǔdé：经过手续或努力得到许可、权利等，是正确答案。", "去得": "qù（第四声）与 qǔ（第三声）声调不同，去得是「能去、去得了」的意思，与「得到许可」无关。", "举得": "jǔ 与 qǔ 声母不同（j 与 q），都是第三声，举得是「能举起」的意思。", "处得": "chǔ 与 qǔ 声母不同（ch 与 q），处得意思是「相处」，如「处得来」。"}, "sentence_index": null, "correct_answer": "取得"}, "level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：得到老师的同意，同意是可以取得的东西，与语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能和「同意」搭配，不能说吃同意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉老师的同意说不通，与「同意」的含义相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」与「同意」意思相反，拒绝同意说不通。"}], "explanations": {"取得": "取得：得到老师的同意，同意是可以取得的东西，与语境相符。", "吃": "搭配：「吃」不能和「同意」搭配，不能说吃同意。", "扔": "语义：扔掉老师的同意说不通，与「同意」的含义相反。", "拒绝": "语义：「拒绝」与「同意」意思相反，拒绝同意说不通。"}, "sentence_index": 0, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取得了一份礼物。", "explanation": "这里应该用〈收到〉。取得用于权利、许可等抽象事物，收到礼物要用〈收到〉。"}, {"text": "他取得了很多眼泪。", "explanation": "这里应该用〈流〉。取得只用于得到，眼泪是自然流出的，要用〈流〉。"}, {"text": "夏天到了，天上取得了一场大雨。", "explanation": "这里应该用〈下〉。取得用于成绩、成果、权利等，天气现象要用〈下〉，取得不指天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va