INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取得", "is_correct": true, "explanation": "取得：先得到经理的同意，才能使用房间，与语境相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：「撕」不能和「同意」搭配，撕同意说不通。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：「摔」的对象是具体的东西，不能和「同意」搭配。"}, {"text": "踩", "is_correct": false, "explanation": "语义：「踩」与「使用房间」的语境无关，踩同意说不通。"}], "explanations": {"取得": "取得：先得到经理的同意，才能使用房间，与语境相符。", "撕": "搭配：「撕」不能和「同意」搭配，撕同意说不通。", "摔": "搭配：「摔」的对象是具体的东西，不能和「同意」搭配。", "踩": "语义：「踩」与「使用房间」的语境无关，踩同意说不通。"}, "sentence_index": 6, "correct_answer": "取得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为迟到，取得了老板的批评。", "explanation": "这里应该用〈受到〉。取得用于正面的成果、资格，受到批评要用〈受到〉。"}, {"text": "我在超市取得了新鲜的水果。", "explanation": "这里应该用〈买到〉。取得不用于买来的商品，买到水果要用〈买到〉。"}, {"text": "他取得了一个错误。", "explanation": "这里应该用〈犯〉。取得只用于正面的结果，犯错误要用〈犯〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把取得了律师的执业资格。", "corrected_sentence": "他终于取得了律师的执业资格。", "error_description": "「把取得了」应为「取得了」。“取得”没有处置义，不能用“把”；这里的“把”多余，宾语应放在“取得了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于取得着老板的批准。", "corrected_sentence": "他终于取得了老板的批准。", "error_description": "「取得着」应为「取得了」。已完成的结果要用“了”，“着”表示持续状态，与“终于取得”的完成义矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
