INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "武装是拿着武器的人，或者武器本身。", "primary_collocate": null, "pronunciation": "wǔ zhuāng", "ipa": "u˨˩˦ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "山里有一支武装。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支武装只有几十个人。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加入了一支地方武装。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武装离开了这个小镇。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现了一支不明武装。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的武装比我们强得多。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口来了一队武装。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的武装很少。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支武装守着桥。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家收回了他们所有的武装。", "target_word": "武装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "武裝", "label": "繁体"}, {"form": "武装力量", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：带武器的队伍，或武器装备本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86611, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武装", "is_correct": true, "explanation": "wǔ zhuāng，指拿着武器的队伍或武器装备，正确答案。"}, {"text": "组装", "is_correct": false, "explanation": "zǔ 与 wǔ 声母不同，意思是把零件拼装起来。"}, {"text": "古装", "is_correct": false, "explanation": "gǔ 与 wǔ 声母不同，意思是古代的服装。"}, {"text": "补妆", "is_correct": false, "explanation": "bǔ 与 wǔ 声母不同，意思是补上化妆。"}], "explanations": {"武装": "wǔ zhuāng，指拿着武器的队伍或武器装备，正确答案。", "组装": "zǔ 与 wǔ 声母不同，意思是把零件拼装起来。", "古装": "gǔ 与 wǔ 声母不同，意思是古代的服装。", "补妆": "bǔ 与 wǔ 声母不同，意思是补上化妆。"}, "sentence_index": null, "correct_answer": "武装"}, "level_3": {"options": [{"text": "武装", "is_correct": true, "explanation": "指一队拿着武器的人，填入后符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "量词：「房子」用「间」「座」计数，不说「一支房子」，句意不成立。"}, {"text": "老师", "is_correct": false, "explanation": "量词与语义：「老师」指人，不用「支」计数，「一支老师」不成立。"}, {"text": "米饭", "is_correct": false, "explanation": "量词：「米饭」用「碗」「顿」计数，不说「一支米饭」，句意不成立。"}], "explanations": {"武装": "指一队拿着武器的人，填入后符合句意。", "房子": "量词：「房子」用「间」「座」计数，不说「一支房子」，句意不成立。", "老师": "量词与语义：「老师」指人，不用「支」计数，「一支老师」不成立。", "米饭": "量词：「米饭」用「碗」「顿」计数，不说「一支米饭」，句意不成立。"}, "sentence_index": 0, "correct_answer": "武装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的武装很漂亮。", "explanation": "这里应该用〈装饰〉。「武装」指武器或拿武器的人，不能用来说屋子的装饰和美观。"}, {"text": "这辆自行车需要武装。", "explanation": "这里应该用〈修理〉。「武装」指武器或拿武器的人，不能用来说自行车的维修。"}, {"text": "这场音乐会的武装很精彩。", "explanation": "这里应该用〈表演〉。「武装」指武器或拿武器的人，不能用来评价音乐会的演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86611, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武装", "is_correct": true, "explanation": "wǔ zhuāng，指拿着武器的队伍或武器装备，正确答案。"}, {"text": "雾状", "is_correct": false, "explanation": "wù zhuàng 与 wǔ zhuāng 声调不同，意思是像雾一样的形状。"}, {"text": "五张", "is_correct": false, "explanation": "zhāng 与 zhuāng 只差介音 u，意思是五张，是数量词组。"}, {"text": "五双", "is_correct": false, "explanation": "shuāng 与 zhuāng 声母不同（sh 与 zh），意思是五双，是数量词组。"}], "explanations": {"武装": "wǔ zhuāng，指拿着武器的队伍或武器装备，正确答案。", "雾状": "wù zhuàng 与 wǔ zhuāng 声调不同，意思是像雾一样的形状。", "五张": "zhāng 与 zhuāng 只差介音 u，意思是五张，是数量词组。", "五双": "shuāng 与 zhuāng 声母不同（sh 与 zh），意思是五双，是数量词组。"}, "sentence_index": null, "correct_answer": "武装"}, "level_3": {"options": [{"text": "武装", "is_correct": true, "explanation": "指一队拿着武器的人，填入后符合句意。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：量词「队」一般用于人、车或成群的动物，不用于行李。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能成队来到村口，句意说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能成队地来到村口，句意说不通。"}], "explanations": {"武装": "指一队拿着武器的人，填入后符合句意。", "行李": "搭配：量词「队」一般用于人、车或成群的动物，不用于行李。", "天气": "语义：天气不能成队来到村口，句意说不通。", "石头": "语义：石头不能成队地来到村口，句意说不通。"}, "sentence_index": 6, "correct_answer": "武装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份武装很快就要烹饪。", "explanation": "这里应该用〈食材〉。「武装」指武器或拿武器的人，不能作为被烹饪的对象。"}, {"text": "这首歌的武装很好听。", "explanation": "这里应该用〈旋律〉。「武装」指武器或拿武器的人，不能用来评价歌曲。"}, {"text": "他的武装写得很好。", "explanation": "这里应该用〈作文〉。「武装」指武器或拿武器的人，不能用来评价写作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山下驻扎着一只武装。", "corrected_sentence": "山下驻扎着一支武装。", "error_description": "量词错误：「武装」指一队人时要用「支」，写成「只」不对，「只」多用于动物或成对物件中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那几支武装们已经撤走了。", "corrected_sentence": "那几支武装已经撤走了。", "error_description": "多加了「们」。「武装」本身可以用量词「支」计数，不能再加「们」表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
