INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手是我们身体上用来拿东西的部分。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他的手里拿着一杯热茶。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手举起来。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以前，要先洗手。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手受伤了，不能写字。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子伸出小手，想拿桌上的苹果。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用两只手捧着一碗汤。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很冷，我的手冻红了。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手拿起书，放进包里。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把手放在桌子上。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拉着我的手过马路。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手指", "label": "复合"}, {"form": "左手", "label": "复合"}, {"form": "右手", "label": "复合"}], "register": "中性", "sense_fingerprint": "手|名词|身体上用来拿东西的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86613, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手", "is_correct": true, "explanation": "手：人体上肢末端，用来拿东西，读作 shǒu（第三声），是本题答案。"}, {"text": "受", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受。"}, {"text": "瘦", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是身上肉少，即瘦。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收起、收到。"}, {"text": "寿", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是寿命。"}, {"text": "兽", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是野生动物。"}], "explanations": {"手": "手：人体上肢末端，用来拿东西，读作 shǒu（第三声），是本题答案。", "受": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受。", "瘦": "shòu（第四声）与 shǒu（第三声）声调不同，意思是身上肉少，即瘦。", "收": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收起、收到。", "寿": "shòu（第四声）与 shǒu（第三声）声调不同，意思是寿命。", "兽": "shòu（第四声）与 shǒu（第三声）声调不同，意思是野生动物。"}, "sentence_index": null, "correct_answer": "手"}, "level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "手里：“手里拿着”指手中拿着东西，与“拿着一杯热茶”相符。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚不能拿东西，“拿着一杯热茶”只能用手。"}, {"text": "眼", "is_correct": false, "explanation": "语义：眼睛不能拿着杯子，句子说的是用手拿东西。"}, {"text": "脑", "is_correct": false, "explanation": "搭配：表示“在…里面”时说“脑子里”，不说“脑里”。"}], "explanations": {"手": "手里：“手里拿着”指手中拿着东西，与“拿着一杯热茶”相符。", "脚": "语义：脚不能拿东西，“拿着一杯热茶”只能用手。", "眼": "语义：眼睛不能拿着杯子，句子说的是用手拿东西。", "脑": "搭配：表示“在…里面”时说“脑子里”，不说“脑里”。"}, "sentence_index": 0, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手起了水泡，穿鞋很疼。", "explanation": "这里应该用〈脚〉。穿鞋要靠脚，手不穿鞋，“手”在这里用错了。"}, {"text": "我的手近视了，要戴眼镜。", "explanation": "这里应该用〈眼睛〉。近视只能说眼睛，手不会近视。"}, {"text": "我的手掉了一颗牙，说话漏风。", "explanation": "这里应该用〈牙齿〉。掉牙、说话漏风只与牙齿有关，手不会掉牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86613, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手", "is_correct": true, "explanation": "手：人体上肢末端，用来拿东西，读作 shǒu（第三声），是本题答案。"}, {"text": "售", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是卖。"}, {"text": "授", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是授予。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 shǒu 的声母 zh 与 sh 不同，意思是胳膊的肘部。"}], "explanations": {"手": "手：人体上肢末端，用来拿东西，读作 shǒu（第三声），是本题答案。", "售": "shòu（第四声）与 shǒu（第三声）声调不同，意思是卖。", "授": "shòu（第四声）与 shǒu（第三声）声调不同，意思是授予。", "肘": "zhǒu（第三声）与 shǒu 的声母 zh 与 sh 不同，意思是胳膊的肘部。"}, "sentence_index": null, "correct_answer": "手"}, "level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "手冻红了：身体部位受冷后发红，符合“冬天很冷”的语境。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会因为天冷而冻红，句子说的是人的身体。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不会被冻红，“冻红”只用于人的身体部位。"}, {"text": "脑", "is_correct": false, "explanation": "搭配：“冻红”用于皮肤，不说脑子冻红，这个搭配不成立。"}], "explanations": {"手": "手冻红了：身体部位受冷后发红，符合“冬天很冷”的语境。", "书": "语义：书不会因为天冷而冻红，句子说的是人的身体。", "车": "语义：车不会被冻红，“冻红”只用于人的身体部位。", "脑": "搭配：“冻红”用于皮肤，不说脑子冻红，这个搭配不成立。"}, "sentence_index": 6, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子举起一块手，想叫老师。", "explanation": "这里应该用〈只〉。手按个数计，说“一只手”；“块”用于块状的东西，不用于手。"}, {"text": "她拉着我的一根手，走进教室。", "explanation": "这里应该用〈只〉。手按个数计，说“一只手”；“根”用于细长的东西，不用于手。"}, {"text": "我的一条手受伤了，不能写字。", "explanation": "这里应该用〈只〉。手按个数计，说“一只手”，“条”用于细长的东西，不用于手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一个手拿起了筷子。", "corrected_sentence": "他用一只手拿起了筷子。", "error_description": "错误形式：一个手；正确形式：一只手。“手”作为身体部位，计量时用“只”，不用“个”，这里错的是量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请手把洗干净。", "corrected_sentence": "请把手洗干净。", "error_description": "错误形式：请手把洗干净；正确形式：请把手洗干净。“把”字句中，“把”要放在动词前，宾语“手”放在“把”后，应说“请把手洗干净”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
