INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体上肢末端能拿东西、能做各种动作的部分。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他一边说话，一边用手比画。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手很灵巧，会做各种小玩具。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳到我的手上睡着了。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的手很轻，一点也不疼。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手伸进口袋里找钥匙。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双手干过很多活儿。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手剥了一个橘子。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手太脏了，要先洗一洗。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她双手抱着一只小狗。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学钢琴的时候，手要放松。", "target_word": "手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手指", "label": "复合"}, {"form": "左手", "label": "复合"}, {"form": "右手", "label": "复合"}], "register": "中性", "sense_fingerprint": "手|名词|上肢末端能做各种动作的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手", "is_correct": true, "explanation": "手：人体上肢末端，能做各种动作，读作 shǒu（第三声），是本题答案。"}, {"text": "受", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受。"}, {"text": "瘦", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是身上肉少，即瘦。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收起、收到。"}, {"text": "寿", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是寿命。"}, {"text": "兽", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是野生动物。"}], "explanations": {"手": "手：人体上肢末端，能做各种动作，读作 shǒu（第三声），是本题答案。", "受": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受。", "瘦": "shòu（第四声）与 shǒu（第三声）声调不同，意思是身上肉少，即瘦。", "收": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收起、收到。", "寿": "shòu（第四声）与 shǒu（第三声）声调不同，意思是寿命。", "兽": "shòu（第四声）与 shǒu（第三声）声调不同，意思是野生动物。"}, "sentence_index": null, "correct_answer": "手"}, "level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "用手：比画是用手做动作，“用手比画”是正确搭配。"}, {"text": "脚", "is_correct": false, "explanation": "语义：比画靠手做动作，脚不能做比画的动作。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：前面已经用嘴说话，嘴不能再用来“比画”。"}, {"text": "腿", "is_correct": false, "explanation": "语义：比画要靠手或上肢做动作，腿不能用来比画。"}], "explanations": {"手": "用手：比画是用手做动作，“用手比画”是正确搭配。", "脚": "语义：比画靠手做动作，脚不能做比画的动作。", "嘴": "语义：前面已经用嘴说话，嘴不能再用来“比画”。", "腿": "语义：比画要靠手或上肢做动作，腿不能用来比画。"}, "sentence_index": 0, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手很有力，能跑得很快。", "explanation": "这里应该用〈腿〉。跑步靠腿，手不能用来跑，“手”在这里用错了。"}, {"text": "她的手很甜，会说好听的话。", "explanation": "这里应该用〈嘴〉。“甜”和“说好听的话”都与嘴有关，手不说甜。"}, {"text": "他的手很灵，能闻到很远的味道。", "explanation": "这里应该用〈鼻子〉。闻味道要靠鼻子，手不能闻味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86614, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手", "is_correct": true, "explanation": "手：人体上肢末端，能做各种动作，读作 shǒu（第三声），是本题答案。"}, {"text": "售", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是卖。"}, {"text": "授", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是授予。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 shǒu 的声母 zh 与 sh 不同，意思是胳膊的肘部。"}], "explanations": {"手": "手：人体上肢末端，能做各种动作，读作 shǒu（第三声），是本题答案。", "售": "shòu（第四声）与 shǒu（第三声）声调不同，意思是卖。", "授": "shòu（第四声）与 shǒu（第三声）声调不同，意思是授予。", "肘": "zhǒu（第三声）与 shǒu 的声母 zh 与 sh 不同，意思是胳膊的肘部。"}, "sentence_index": null, "correct_answer": "手"}, "level_3": {"options": [{"text": "手", "is_correct": true, "explanation": "用手剥橘子：剥橘子皮要靠手指做动作，句意通顺。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚不能做剥橘子这样细小的动作。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛只能看，不能用来剥橘子。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵只能听，不能用来剥橘子。"}], "explanations": {"手": "用手剥橘子：剥橘子皮要靠手指做动作，句意通顺。", "脚": "语义：脚不能做剥橘子这样细小的动作。", "眼睛": "语义：眼睛只能看，不能用来剥橘子。", "耳朵": "语义：耳朵只能听，不能用来剥橘子。"}, "sentence_index": 6, "correct_answer": "手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈握着我的一根手，过马路很安全。", "explanation": "这里应该用〈只〉。手按个数计，说“一只手”；“根”用于细长的东西，不用于手。"}, {"text": "他伸出一块手，想和我握手。", "explanation": "这里应该用〈只〉。手按个数计，说“一只手”；“块”用于块状的东西，不用于手。"}, {"text": "他有两条手，拿着东西很方便。", "explanation": "这里应该用〈只〉。手按个数计，说“两只手”，“条”用于细长的东西，不用于手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCL