INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用两个手推开了那扇门。", "corrected_sentence": "他用两只手推开了那扇门。", "error_description": "错误形式：两个手；正确形式：两只手。“手”计量时用“只”，不用“个”，这里错的是量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈手把擦干净了。", "corrected_sentence": "妈妈把手擦干净了。", "error_description": "错误形式：妈妈手把擦干净了；正确形式：妈妈把手擦干净了。“把”字句中，“把”要放在动词前，宾语“手”放在“把”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
