INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86617, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旅游是离开家，去别的地方玩，看风景。", "primary_collocate": null, "pronunciation": "lǚ yóu", "ipa": "ly˨˩˦ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "暑假我想和家人去海边旅游。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她最喜欢一个人去国外旅游。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去过云南旅游，那里风景很美。", "target_word": "旅游", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月放假，朋友们打算去北京旅游。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他存了很多钱，准备明年去旅游。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游的时候，我喜欢拍很多照片。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷奶奶退休后常常去各地旅游。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年春节，我们一家人去三亚旅游了。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了去旅游，他请了一个星期假。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐火车去西安旅游，路上很开心。", "target_word": "旅游", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "旅游了", "label": "体标"}, {"form": "旅游过", "label": "体标"}, {"form": "旅游团", "label": "复合"}, {"form": "旅游业", "label": "复合"}, {"form": "旅遊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "离开家去外地玩、看风景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅游", "is_correct": true, "explanation": "“旅游”指离开家去别处玩，与“暑假和家人去海边”的出游语境相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”指上班做事，与“暑假和家人去海边”的休假语境不合。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”是学习活动，与暑假出游的语境不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是学校的测验活动，与暑假和家人去海边玩的语境不合。"}], "explanations": {"旅游": "“旅游”指离开家去别处玩，与“暑假和家人去海边”的出游语境相符。", "工作": "语义：“工作”指上班做事，与“暑假和家人去海边”的休假语境不合。", "上课": "语义：“上课”是学习活动，与暑假出游的语境不合。", "考试": "语义：“考试”是学校的测验活动，与暑假和家人去海边玩的语境不合。"}, "sentence_index": 0, "correct_answer": "旅游"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去商场旅游，买了很多东西。", "explanation": "〈旅游〉指离开居住地去外地或名胜地游览，在本地商场买东西不叫旅游。这里应该用〈逛街〉。"}, {"text": "我去医院旅游，看望生病的奶奶。", "explanation": "〈旅游〉指离开居住地去风景名胜游览，去医院探望病人不是游览，这里应该用〈探病〉。"}, {"text": "我每天去公司旅游，负责写报告。", "explanation": "〈旅游〉指游览玩乐，去公司写报告是工作，不能用旅游。这里应该用〈上班〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅游", "is_correct": true, "explanation": "“旅游”指到各地游览，与“退休后常常去各地”的休闲语境相符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”是因公事外出，与退休后的休闲出行不合。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，与“退休后”的语境矛盾。"}, {"text": "值班", "is_correct": false, "explanation": "语义：“值班”指轮流在岗守候，与退休后外出游览的语境不合。"}], "explanations": {"旅游": "“旅游”指到各地游览，与“退休后常常去各地”的休闲语境相符。", "出差": "语义：“出差”是因公事外出，与退休后的休闲出行不合。", "上班": "语义：“上班”指去单位工作，与“退休后”的语境矛盾。", "值班": "语义：“值班”指轮流在岗守候，与退休后外出游览的语境不合。"}, "sentence_index": 6, "correct_answer": "旅游"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上在小区里旅游，锻炼身体。", "explanation": "〈旅游〉指到别处游览，在小区里锻炼不叫旅游。这里应该用〈跑步〉。"}, {"text": "我大学在北京旅游，学习法律专业。", "explanation": "〈旅游〉指游览玩乐，而在北京读大学属于求学，这里应该用〈读书〉或〈上学〉。"}, {"text": "妈妈在厨房里旅游，做了一顿饭。", "explanation": "〈旅游〉指到别处游览，在厨房做饭属于家务，这里应该用〈下厨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们周末去郊外旅游了过。", "corrected_sentence": "我们周末去郊外旅游。", "error_description": "错误：“旅游了过”，“了”与“过”不能同时用在同一个动词后；正确：“我们周末去郊外旅游”。“了”表示动作已完成，“过”表示曾经有过的经历，二者不能并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们去旅游了过。", "corrected_sentence": "他们去旅游了。", "error_description": "错误：“旅游了过”，“了”和“过”不能同时用在同一个动词后；正确：“去旅游了”。“了”表示动作已经完成，“过”表示曾经有过的经历，二者不能并用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
