INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体突然破裂，并发出巨响。", "primary_collocate": null, "pronunciation": "bào zhà", "ipa": "pau̯˥˩ ʈʂa˥˩", "syllable_count": 2, "sentences": [{"text": "鸡蛋放进微波炉里会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煤气罐在厨房突然爆炸，声音很响。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个锅炉太旧，用的时候容易爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓶子里的气太多，就会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听见砰的一声，原来是电池爆炸了。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个旧油罐爆炸过，现在没人敢靠近。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把罐头放在火上烤，罐头会爆炸。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油站的油罐如果着火，就会爆炸。", "target_word": "爆炸", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "手机电池太热时可能会爆炸。", "target_word": "爆炸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的玻璃瓶爆炸了，老师赶快关门。", "target_word": "爆炸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爆炸了", "label": "体标"}, {"form": "爆炸过", "label": "体标"}, {"form": "爆炸声", "label": "复合"}], "register": "中性", "sense_fingerprint": "煤气罐、电池等容器因压力或受热突然破裂并发出巨响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指鸡蛋放进微波炉后容器内压力增大而炸开，与“微波炉”相合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”要求能行走的生物，鸡蛋不会走路。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指温度降低，与微波炉加热的情境相反。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物的成长，不能用于放进微波炉的鸡蛋。"}], "explanations": {"爆炸": "正确。“爆炸”指鸡蛋放进微波炉后容器内压力增大而炸开，与“微波炉”相合。", "散步": "语义：“散步”要求能行走的生物，鸡蛋不会走路。", "结冰": "语义：“结冰”指温度降低，与微波炉加热的情境相反。", "生长": "搭配：“生长”用于生物的成长，不能用于放进微波炉的鸡蛋。"}, "sentence_index": 0, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子从桌上掉下来，突然爆炸了。", "explanation": "这里应该用〈破裂〉。玻璃杯摔碎不需要压力或受热，应说“破裂”；“爆炸”要求容器因压力或受热突然炸开并发出巨响。"}, {"text": "这支铅笔我一按，突然爆炸了。", "explanation": "这里应该用〈折断〉。铅笔被按断要用“折断”，不会炸开并发出巨响，不能说“爆炸”。"}, {"text": "这座桥因为洪水突然爆炸了。", "explanation": "这里应该用〈倒塌〉。桥被洪水冲毁应说“倒塌”，不是因压力或受热而炸开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爆炸", "is_correct": true, "explanation": "正确。“爆炸”指罐头受热后突然炸开，与“放在火上烤”相合。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体冷却变成固体，与“火上烤”的加热情境相反。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于种子或植物，罐头不能发芽。"}, {"text": "散架", "is_correct": false, "explanation": "搭配：“散架”指器物结构松散，不能用于形容罐头。"}], "explanations": {"爆炸": "正确。“爆炸”指罐头受热后突然炸开，与“放在火上烤”相合。", "凝固": "语义：“凝固”指液体冷却变成固体，与“火上烤”的加热情境相反。", "发芽": "搭配：“发芽”只用于种子或植物，罐头不能发芽。", "散架": "搭配：“散架”指器物结构松散，不能用于形容罐头。"}, "sentence_index": 6, "correct_answer": "爆炸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的哮喘突然爆炸了，赶快去医院。", "explanation": "这里应该用〈发作〉。疾病的突然加重要用“发作”，“爆炸”只用于物体。"}, {"text": "烧开的牛奶突然爆炸了，溅了一地。", "explanation": "这里应该用〈沸腾〉。牛奶受热冒泡要用“沸腾”，不会突然炸开并发出巨响。"}, {"text": "这块饼干放久了，突然爆炸了。", "explanation": "这里应该用〈变软〉。饼干受潮后会变软，不会炸开并发出巨响，不能说“爆炸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个罐子装得太满，加热时会被爆炸。", "corrected_sentence": "这个罐子装得太满，加热时会爆炸。", "error_description": "错误：“爆炸”是不及物动词，不能用“被”字句。正确：应说“加热时会爆炸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天晚上，厨房里的煤气罐爆炸着，屋子里全是烟。", "corrected_sentence": "昨天晚上，厨房里的煤气罐爆炸了，屋子里全是烟。", "error_description": "错误：“爆炸”是瞬间完成的动作，不能用表示持续的“着”。正确：应说“煤气罐爆炸了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "随便", "is_correct": true, "explanation": "与「正式」相对，符合「不随便」的释义，「做事很正式」与「做事很随便」构成反义。"}, {"text": "快速", "is_correct": false, "explanation": "与「正式」没有反义关系，指速度快。"}, {"text": "明亮", "is_correct": false, "explanation": "与「正式」没有反义关系，指光线充足。"}, {"text": "安静", "is_correct": false, "explanation": "与「正式」没有反义关系，指没有声音。"}], "correct_answer": "随便", "explanations": {"随便": "与「正式」相对，符合「不随便」的释义，「做事很正式」与「做事很随便」构成反义。", "快速": "与「正式」没有反义关系，指速度快。", "明亮": "与「正式」没有反义关系，指光线充足。", "安静": "与「正式」没有反义关系，指没有声音。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
