INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正式是认真的、大家都承认的，不是随便的。", "primary_collocate": null, "pronunciation": "zhèng shì", "ipa": "tʂəŋ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛是正式的，不是练习。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿得很正式，像要去开会。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话的方式很正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很正式，每件事都认真准备。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友聚会不用这么正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次正式的比赛，大家都很紧张。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次见客人，说话特别正式。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会议很正式，请不要迟到。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回答问题很正式，一句玩笑都没有。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你正式地向大家介绍自己。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非正式", "label": "否定"}, {"form": "正式工", "label": "复合"}], "register": "中性", "sense_fingerprint": "认真的、大家都承认的、不随便的，如正式比赛、说话很正式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。"}, {"text": "证实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是证实。"}, {"text": "正史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}], "explanations": {"正式": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。", "证实": "shí（第二声）与 shì（第四声）声调不同，意思是证实。", "正史": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。", "政治": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「比赛」，表示正式的比赛，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来形容比赛。"}, {"text": "湿", "is_correct": false, "explanation": "语义：「湿」形容含水的状态，不能用来形容比赛。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：「厚」描写物体的厚度，比赛不能是厚的。"}], "explanations": {"正式": "修饰「比赛」，表示正式的比赛，符合句意。", "甜": "语义：「甜」形容味道，不能用来形容比赛。", "湿": "语义：「湿」形容含水的状态，不能用来形容比赛。", "厚": "体貌：「厚」描写物体的厚度，比赛不能是厚的。"}, "sentence_index": 0, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正式迟到。", "explanation": "这里应该用〈经常〉。「正式」指认真、大家承认的，不用于表示次数或频率。"}, {"text": "她用很正式的声音哄孩子睡觉。", "explanation": "这里应该用〈温柔〉。「正式」不用于形容声音的柔和。"}, {"text": "孩子们正式地在操场上玩耍。", "explanation": "这里应该用〈快乐〉。「正式」不用于描写玩耍时的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。"}, {"text": "整式", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。"}, {"text": "仗势", "is_correct": false, "explanation": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。"}, {"text": "阵式", "is_correct": false, "explanation": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}], "explanations": {"正式": "zhèng shì，指认真的、大家承认的、不随便的，正确答案。", "整式": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。", "仗势": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。", "阵式": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「说话」，表示说话郑重、讲究礼节，符合句意。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：「蓝」形容颜色，不能用来形容说话的方式，句意荒谬。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」描写人或物的体型，不能用来形容说话。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：「柔软」形容质地，不能用来形容说话的方式。"}], "explanations": {"正式": "修饰「说话」，表示说话郑重、讲究礼节，符合句意。", "蓝": "语义：「蓝」形容颜色，不能用来形容说话的方式，句意荒谬。", "高大": "体貌：「高大」描写人或物的体型，不能用来形容说话。", "柔软": "语义：「柔软」形容质地，不能用来形容说话的方式。"}, "sentence_index": 6, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我最正式的朋友。", "explanation": "这里应该用〈好〉。「正式」指认真、不随便，不用于形容人际关系。"}, {"text": "这杯咖啡太正式了，我喝不下。", "explanation": "这里应该用〈苦〉。「正式」指认真、不随便，不用于形容味道。"}, {"text": "运动员跑得很正式，第一个到了终点。", "explanation": "这里应该用〈快〉。「正式」不用于描写速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一场正式地会议，请大家准时到场。", "corrected_sentence": "这是一场正式的会议，请大家准时到场。", "error_description": "错误形式是「正式地会议」，正确形式是「正式的会议」。「正式」修饰名词「会议」时要用「的」，「地」用于修饰动词，不能用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
