INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合乎一定手续或规格的；郑重的，不随便的。", "primary_collocate": null, "pronunciation": "zhèng shì", "ipa": "tʂəŋ˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "公司下周正式发布新产品。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一份正式的合同，请你签字。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨天正式结婚了。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加面试要穿正式的衣服。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校明年正式开始招生。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要写成正式的通知。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经收到了正式的录取通知。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人进行了正式会谈。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天正式成为这家公司的经理。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用正式的名字填写这张表。", "target_word": "正式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "非正式", "label": "否定"}, {"form": "正式工", "label": "复合"}], "register": "中性", "sense_fingerprint": "合乎手续或规格的、郑重的，如正式合同、正式发布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指合乎手续或规格、郑重的，正确答案。"}, {"text": "证实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是证实。"}, {"text": "正史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。"}, {"text": "政治", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}], "explanations": {"正式": "zhèng shì，指合乎手续或规格、郑重的，正确答案。", "证实": "shí（第二声）与 shì（第四声）声调不同，意思是证实。", "正史": "shǐ（第三声）与 shì（第四声）声调不同，意思是正式的史书。", "政治": "zhì 与 shì 声母不同（zh 与 sh），意思是政治。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「发布」，表示按正式程序公开发布，符合句意。"}, {"text": "哭着", "is_correct": false, "explanation": "语义：「哭着」描写情绪，不能修饰「发布新产品」，句意荒谬。"}, {"text": "唱着", "is_correct": false, "explanation": "语义：「唱着」描写动作方式，不能修饰「发布新产品」，句意荒谬。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能修饰「发布」。"}], "explanations": {"正式": "修饰「发布」，表示按正式程序公开发布，符合句意。", "哭着": "语义：「哭着」描写情绪，不能修饰「发布新产品」，句意荒谬。", "唱着": "语义：「唱着」描写动作方式，不能修饰「发布新产品」，句意荒谬。", "甜": "语义：「甜」形容味道，不能修饰「发布」。"}, "sentence_index": 0, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的温度很正式。", "explanation": "这里应该用〈高〉。「正式」形容手续或规格，不用于形容温度的高低。"}, {"text": "这条河的水很正式。", "explanation": "这里应该用〈清〉。「正式」形容手续或规格，不用于形容河水。"}, {"text": "这块蛋糕很正式。", "explanation": "这里应该用〈新鲜〉。「正式」指合乎手续规格或郑重，不用于形容食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正式", "is_correct": true, "explanation": "zhèng shì，指合乎手续或规格、郑重的，正确答案。"}, {"text": "整式", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。"}, {"text": "仗势", "is_correct": false, "explanation": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。"}, {"text": "阵式", "is_correct": false, "explanation": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}], "explanations": {"正式": "zhèng shì，指合乎手续或规格、郑重的，正确答案。", "整式": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是数学中的整式。", "仗势": "zhàng 与 zhèng 韵母不同（ang 与 eng），意思是依仗权势。", "阵式": "zhèn 与 zhèng 韵母不同（n 与 ng），意思是阵形。"}, "sentence_index": null, "correct_answer": "正式"}, "level_3": {"options": [{"text": "正式", "is_correct": true, "explanation": "修饰「录取通知」，表示正式的通知，符合句意。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：通知不能是悲伤的，句意不通。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：「粗糙」多用于质地、表面，不说粗糙的录取通知。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」指形状，不能用来形容通知。"}], "explanations": {"正式": "修饰「录取通知」，表示正式的通知，符合句意。", "悲伤": "语义：通知不能是悲伤的，句意不通。", "粗糙": "搭配：「粗糙」多用于质地、表面，不说粗糙的录取通知。", "圆": "语义：「圆」指形状，不能用来形容通知。"}, "sentence_index": 6, "correct_answer": "正式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果很正式。", "explanation": "这里应该用〈新鲜〉。「正式」指合乎手续规格或郑重，不用于形容水果。"}, {"text": "今天天气很正式。", "explanation": "这里应该用〈好〉。「正式」形容手续或规格，不用于形容天气。"}, {"text": "孩子们正式地抢着吃糖。", "explanation": "这里应该去掉〈正式〉，直接说「抢着吃糖」。「正式」形容手续或规格，不用于形容吃东西的抢夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次通知的语气很正式地。", "corrected_sentence": "这次通知的语气很正式。", "error_description": "错误形式是「很正式地」，正确形式是「很正式」。形容词作谓语时后面不加「地」，「地」用于修饰动词，这里「正式」是谓语，不能加「地」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正式得宣布了这个消息。", "corrected_sentence": "他正式地宣布了这个消息。", "error_description": "错误形式是「正式得宣布」，正确形式是「正式地宣布」。修饰动词要用「地」，「得」用于动词或形容词之后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
