INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86623, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于计量台阶、地震、风力等的层级。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "这个楼梯一共有二十级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一级一级往上走。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的地震有五级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的风有六级，很大。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔分九级，我们爬到了第五级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连跳三级台阶跑下去了。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯很高，我们一级一级地走上去。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次台风登陆时最强达到十二级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一级一级地爬上了山顶。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的石头路有三百多级。", "target_word": "级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一级", "label": "量词结构"}, {"form": "高级", "label": "复合词"}, {"form": "級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "台阶、地震、风力等一层一层的计量单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447d43e2-a23d-48e8-8047-2c5e16313adc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86623, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "级", "is_correct": true, "explanation": "正确答案：级（jí），量词，用于台阶、地震、风力等的层次或级别。"}, {"text": "机", "is_correct": false, "explanation": "机（jī）与 jí 声调不同（第一声），意思是机器。"}, {"text": "几", "is_correct": false, "explanation": "几（jǐ）与 jí 声调不同（第三声），意思是“多少”。"}, {"text": "季", "is_correct": false, "explanation": "季（jì）与 jí 声调不同（第四声），意思是季节。"}, {"text": "齐", "is_correct": false, "explanation": "齐（qí）与 jí 声母不同（q 与 j），意思是整齐。"}, {"text": "席", "is_correct": false, "explanation": "席（xí）与 jí 声母不同（x 与 j），意思是座位。"}], "explanations": {"级": "正确答案：级（jí），量词，用于台阶、地震、风力等的层次或级别。", "机": "机（jī）与 jí 声调不同（第一声），意思是机器。", "几": "几（jǐ）与 jí 声调不同（第三声），意思是“多少”。", "季": "季（jì）与 jí 声调不同（第四声），意思是季节。", "齐": "齐（qí）与 jí 声母不同（q 与 j），意思是整齐。", "席": "席（xí）与 jí 声母不同（x 与 j），意思是座位。"}, "sentence_index": null, "correct_answer": "级"}, "level_3": {"options": [{"text": "级", "is_correct": true, "explanation": "正确：「这个楼梯一共有二十级」用级计量楼梯的台阶，与句意相符。"}, {"text": "扇", "is_correct": false, "explanation": "搭配：「扇」用于门窗，不用来量楼梯的台阶。"}, {"text": "盏", "is_correct": false, "explanation": "搭配：「盏」用于灯，不用来量楼梯。"}, {"text": "次", "is_correct": false, "explanation": "语义：「次」指次数，楼梯的台阶不能按次数计算。"}], "explanations": {"级": "正确：「这个楼梯一共有二十级」用级计量楼梯的台阶，与句意相符。", "扇": "搭配：「扇」用于门窗，不用来量楼梯的台阶。", "盏": "搭配：「盏」用于灯，不用来量楼梯。", "次": "语义：「次」指次数，楼梯的台阶不能按次数计算。"}, "sentence_index": 0, "correct_answer": "级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温是三十级。", "explanation": "这里应该用〈度〉。气温用度来计量，级用于台阶、地震、风力等。"}, {"text": "这条河的深度有五级。", "explanation": "这里应该用〈米〉。级只表示台阶、地震、风力等的等级，不能用来计量河的深度。"}, {"text": "这次考试他考了九十级。", "explanation": "这里应该用〈分〉。考试成绩用分计算，级不用来计量分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86623, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "级", "is_correct": true, "explanation": "正确答案：级（jí），量词，用于台阶、地震、风力等的层次或级别。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī）与 jí 声调不同（第一声），意思是家禽。"}, {"text": "寄", "is_correct": false, "explanation": "寄（jì）与 jí 声调不同（第四声），意思是邮寄。"}, {"text": "挤", "is_correct": false, "explanation": "挤（jǐ）与 jí 声调不同（第三声），意思是拥挤。"}, {"text": "棋", "is_correct": false, "explanation": "棋（qí）与 jí 声母不同（q 与 j），意思是棋类。"}, {"text": "习", "is_correct": false, "explanation": "习（xí）与 jí 声母不同（x 与 j），意思是学习、练习。"}], "explanations": {"级": "正确答案：级（jí），量词，用于台阶、地震、风力等的层次或级别。", "鸡": "鸡（jī）与 jí 声调不同（第一声），意思是家禽。", "寄": "寄（jì）与 jí 声调不同（第四声），意思是邮寄。", "挤": "挤（jǐ）与 jí 声调不同（第三声），意思是拥挤。", "棋": "棋（qí）与 jí 声母不同（q 与 j），意思是棋类。", "习": "习（xí）与 jí 声母不同（x 与 j），意思是学习、练习。"}, "sentence_index": null, "correct_answer": "级"}, "level_3": {"options": [{"text": "级", "is_correct": true, "explanation": "正确：「一级一级地走上去」指一层一层地走上台阶，与句意相符。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：「颗」用于粒状的东西，不能用来量楼梯的台阶。"}, {"text": "座", "is_correct": false, "explanation": "搭配：「座」用于山、楼等大型建筑，不用来量台阶。"}, {"text": "度", "is_correct": false, "explanation": "语义：「度」用于温度、角度，不能用来量台阶。"}], "explanations": {"级": "正确：「一级一级地走上去」指一层一层地走上台阶，与句意相符。", "颗": "搭配：「颗」用于粒状的东西，不能用来量楼梯的台阶。", "座": "搭配：「座」用于山、楼等大型建筑，不用来量台阶。", "度": "语义：「度」用于温度、角度，不能用来量台阶。"}, "sentence_index": 6, "correct_answer": "级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了三级书。", "explanation": "这里应该用〈本〉。级是计量台阶、地震、风力等的量词，不能用来计量书。"}, {"text": "他唱了一级很好听的歌。", "explanation": "这里应该用〈首〉。级不用来计量歌曲，歌要用首。"}, {"text": "这袋大米重五十级。", "explanation": "这里应该用〈斤〉。重量用斤计算，级不能用来计量重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座塔一共有九十个级台阶。", "corrected_sentence": "这座塔一共有九十级台阶。", "error_description": "错误形式是「九十个级台阶」，正确形式是「九十级台阶」。作量词的「级」前面不加「个」，应直接说数词加「级」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一口气爬了级台阶，有点累。", "corrected_sentence": "他一口气爬了三级台阶，有点累。", "error_description": "错误形式是「爬了级台阶」，正确形式是「爬了三级台阶」。作量词的「级」前面要加数词，省略后说法不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
