INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86627, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "类是把差不多的东西放在一起的一堆。", "primary_collocate": null, "pronunciation": "lèi", "ipa": "leɪ˥˩", "syllable_count": 1, "sentences": [{"text": "这类书很适合小学生看。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把水果分成三类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢哪一类电影？", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫和狗不是一类动物。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书不属于同一类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类问题我以前遇到过。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服太多，我按颜色分成了两类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的苹果是一类，绿色的是另一类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱看的是那一类故事。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里把这类杂志放在门口。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把相近的东西归在一起的一组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86627, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "类", "is_correct": true, "explanation": "类 lèi，意思是把相近的东西归在一起的一组，是正确答案。"}, {"text": "乐", "is_correct": false, "explanation": "乐 lè 与 lèi 韵母不同（e 与 ei），意思是快乐。"}, {"text": "雷", "is_correct": false, "explanation": "雷 léi（第二声）与 lèi（第四声）声调不同，意思是雷。"}, {"text": "内", "is_correct": false, "explanation": "内 nèi 与 lèi 声母不同（n 与 l），意思是里面。"}, {"text": "蕾", "is_correct": false, "explanation": "蕾 lěi（第三声）与 lèi（第四声）声调不同，意思是花蕾。"}], "explanations": {"类": "类 lèi，意思是把相近的东西归在一起的一组，是正确答案。", "乐": "乐 lè 与 lèi 韵母不同（e 与 ei），意思是快乐。", "雷": "雷 léi（第二声）与 lèi（第四声）声调不同，意思是雷。", "内": "内 nèi 与 lèi 声母不同（n 与 l），意思是里面。", "蕾": "蕾 lěi（第三声）与 lèi（第四声）声调不同，意思是花蕾。"}, "sentence_index": null, "correct_answer": "类"}, "level_3": {"options": [{"text": "类", "is_correct": true, "explanation": "类 是正确答案。“这类书”指这一类的书，与“很适合小学生看”相合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”多用于动物或成对的单个事物，书不属于这类事物。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于颗粒状的东西，不能用来计量书。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用来计量书。"}], "explanations": {"类": "类 是正确答案。“这类书”指这一类的书，与“很适合小学生看”相合。", "只": "语义：“只”多用于动物或成对的单个事物，书不属于这类事物。", "颗": "搭配：“颗”用于颗粒状的东西，不能用来计量书。", "辆": "搭配：“辆”用于车辆，不能用来计量书。"}, "sentence_index": 0, "correct_answer": "类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了一类步，累得不行。", "explanation": "这里应该用〈圈〉。“类”指一组同类事物，不能用来计量跑步的圈数。"}, {"text": "这两个孩子长得很类。", "explanation": "这里的“类”作动词表示“像”，是文言用法，现代汉语应说“很像”。"}, {"text": "天上挂着一类圆月，只有一轮。", "explanation": "这里应该用〈轮〉。“类”指一组同类事物，与“只有一轮”矛盾；月亮按“轮”计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86627, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "类", "is_correct": true, "explanation": "类 lèi，意思是把相近的东西归在一起的一组，是正确答案。"}, {"text": "镭", "is_correct": false, "explanation": "镭 léi（第二声）与 lèi（第四声）声调不同，意思是一种放射性元素。"}, {"text": "垒", "is_correct": false, "explanation": "垒 lěi（第三声）与 lèi（第四声）声调不同，意思是堆砌，如“垒球”。"}, {"text": "勒", "is_correct": false, "explanation": "勒 lè 与 lèi 韵母不同（e 与 ei），意思是勒住，如“勒马”。"}], "explanations": {"类": "类 lèi，意思是把相近的东西归在一起的一组，是正确答案。", "镭": "镭 léi（第二声）与 lèi（第四声）声调不同，意思是一种放射性元素。", "垒": "垒 lěi（第三声）与 lèi（第四声）声调不同，意思是堆砌，如“垒球”。", "勒": "勒 lè 与 lèi 韵母不同（e 与 ei），意思是勒住，如“勒马”。"}, "sentence_index": null, "correct_answer": "类"}, "level_3": {"options": [{"text": "类", "is_correct": true, "explanation": "类 是正确答案。“分成了两类”表示分成两个类别，与句意相合。"}, {"text": "朵", "is_correct": false, "explanation": "搭配：“朵”用于花朵，不能用来计量衣服。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型事物，不能用来计量衣服。"}, {"text": "匹", "is_correct": false, "explanation": "语义：“匹”用于马等牲畜，衣服不是牲畜。"}], "explanations": {"类": "类 是正确答案。“分成了两类”表示分成两个类别，与句意相合。", "朵": "搭配：“朵”用于花朵，不能用来计量衣服。", "座": "搭配：“座”用于山、建筑等大型事物，不能用来计量衣服。", "匹": "语义：“匹”用于马等牲畜，衣服不是牲畜。"}, "sentence_index": 6, "correct_answer": "类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天吃了一类饭，只吃了一顿，很饱。", "explanation": "这里应该用〈顿〉。“类”指一组同类事物，不能用来计量吃饭的次数，与“只吃了一顿”矛盾。"}, {"text": "这对双胞胎的样子很类。", "explanation": "这里的“类”作动词表示“像”，是文言用法，口语应说“很像”。"}, {"text": "我们爬过一类大山，只有一座。", "explanation": "这里应该用〈座〉。“类”指一组同类事物，与“只有一座”矛盾；山按“座”计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个类衣服很适合夏天穿。", "corrected_sentence": "这类衣服很适合夏天穿。", "error_description": "“类”本身已表示一类，不能再与“个”并用。应说“这类衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的抽屉里装着两个类文具。", "corrected_sentence": "他的抽屉里装着两类文具。", "error_description": "“类”前面不能再加量词“个”，“两”后面直接接“类”即可，应说“两类文具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
