INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86628, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "许多相似事物的综合；种类。", "primary_collocate": null, "pronunciation": "lèi", "ipa": "leɪ˥˩", "syllable_count": 1, "sentences": [{"text": "超市里有很多类商品。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖三类蔬菜。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物可以分成很多类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一类花只在春天开。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这类词要多读几遍。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的书有哪几类？", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书按内容分成几大类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类药饭后吃，那类药饭前吃。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员把垃圾分成了四类。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类运动最适合在春天做。", "target_word": "类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相似事物的总称，种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
