INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86630, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，与指示代词“这”“那”或疑问代词“哪”连用，表示所指的若干人或事物（复数）。", "primary_collocate": null, "pronunciation": "xiē", "ipa": "ɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "这些书是我的。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那些人是谁？", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你喜欢哪些颜色？", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些苹果很甜，你尝一尝。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那些花是妈妈昨天买的。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哪些菜是你做的？", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上这些东西都不要动。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些事我都记得。", "target_word": "些", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那些旧衣服我已经送给朋友了。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们哪些词还不懂。", "target_word": "些", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "这些", "label": "复合"}, {"form": "那些", "label": "复合"}, {"form": "哪些", "label": "复合"}], "register": "中性", "sense_fingerprint": "这些、那些、哪些：跟指示词或疑问词连用的复数量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a68a0c0-0cc4-46cf-be05-5ccf26b00493') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86630, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "些", "is_correct": true, "explanation": "些 xiē（第一声）是量词，与指示词连用表示复数。"}, {"text": "写", "is_correct": false, "explanation": "写 xiě（第三声）与 xiē 声调不同，意思是书写。"}, {"text": "鞋", "is_correct": false, "explanation": "鞋 xié（第二声）与 xiē 声调不同，意思是鞋子。"}, {"text": "谢", "is_correct": false, "explanation": "谢 xiè（第四声）与 xiē 声调不同，意思是感谢。"}, {"text": "虾", "is_correct": false, "explanation": "虾 xiā 的韵母是 ia，与 xiē 的 ie 不同，意思是虾。"}, {"text": "接", "is_correct": false, "explanation": "接 jiē 的声母是 j，与 xiē 的 x 不同，意思是接住、接收。"}], "explanations": {"些": "些 xiē（第一声）是量词，与指示词连用表示复数。", "写": "写 xiě（第三声）与 xiē 声调不同，意思是书写。", "鞋": "鞋 xié（第二声）与 xiē 声调不同，意思是鞋子。", "谢": "谢 xiè（第四声）与 xiē 声调不同，意思是感谢。", "虾": "虾 xiā 的韵母是 ia，与 xiē 的 ie 不同，意思是虾。", "接": "接 jiē 的声母是 j，与 xiē 的 x 不同，意思是接住、接收。"}, "sentence_index": null, "correct_answer": "些"}, "level_3": {"options": [{"text": "些", "is_correct": true, "explanation": "些表示复数，与“这”连用，正合“这些书”。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”多用于衣物、事情，不说“这件书”。"}, {"text": "页", "is_correct": false, "explanation": "语义：“页”只指一张纸的一面，不指整本书，“这页书是我的”不符句意。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”用于块状物，不用于书籍。"}], "explanations": {"些": "些表示复数，与“这”连用，正合“这些书”。", "件": "搭配：“件”多用于衣物、事情，不说“这件书”。", "页": "语义：“页”只指一张纸的一面，不指整本书，“这页书是我的”不符句意。", "块": "搭配：“块”用于块状物，不用于书籍。"}, "sentence_index": 0, "correct_answer": "些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些人是我的爸爸。", "explanation": "这里应该用〈这个〉。“这些”指多个，只说一个人要用“这个人”，“我的爸爸”只有一位。"}, {"text": "那些车是我的新车。", "explanation": "这里应该用〈那辆〉。“那些”指多个，“我的新车”只有一辆，应说“那辆新车”。"}, {"text": "这些老师是我的校长。", "explanation": "这里应该用〈这位〉。“这些”指多个，“我的校长”只有一位，应说“这位校长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86630, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "些", "is_correct": true, "explanation": "些 xiē（第一声）是量词，与疑问词连用表示不定的复数。"}, {"text": "蟹", "is_correct": false, "explanation": "蟹 xiè（第四声）与 xiē 声调不同，意思是螃蟹。"}, {"text": "斜", "is_correct": false, "explanation": "斜 xié（第二声）与 xiē 声调不同，意思是倾斜。"}, {"text": "切", "is_correct": false, "explanation": "切 qiē 的声母是 q，与 xiē 的 x 不同，意思是切割。"}], "explanations": {"些": "些 xiē（第一声）是量词，与疑问词连用表示不定的复数。", "蟹": "蟹 xiè（第四声）与 xiē 声调不同，意思是螃蟹。", "斜": "斜 xié（第二声）与 xiē 声调不同，意思是倾斜。", "切": "切 qiē 的声母是 q，与 xiē 的 x 不同，意思是切割。"}, "sentence_index": null, "correct_answer": "些"}, "level_3": {"options": [{"text": "些", "is_correct": true, "explanation": "些表示复数，与“都”一致，正合“这些东西”。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗词、歌曲，不用于东西。"}, {"text": "场", "is_correct": false, "explanation": "搭配：“场”用于场次或事件，如“一场雨”，不用于东西。"}, {"text": "位", "is_correct": false, "explanation": "搭配：“位”只用于人，不用于东西。"}], "explanations": {"些": "些表示复数，与“都”一致，正合“这些东西”。", "首": "搭配：“首”用于诗词、歌曲，不用于东西。", "场": "搭配：“场”用于场次或事件，如“一场雨”，不用于东西。", "位": "搭配：“位”只用于人，不用于东西。"}, "sentence_index": 6, "correct_answer": "些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那些人是我的一位朋友。", "explanation": "这里应该用〈那位〉。“那些”指多个，“一位朋友”只指一人，应说“那位朋友”。"}, {"text": "这些是我的一个玩具。", "explanation": "这里应该用〈这个〉。“这些”指多个，“一个玩具”只指一件，应说“这个玩具”。"}, {"text": "那些是我的一本书。", "explanation": "这里应该用〈那本〉。“那些”指多个，“一本书”只指一本，应说“那本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这个些朋友都很喜欢唱歌。", "corrected_sentence": "我们这些朋友都很喜欢唱歌。", "error_description": "“这些”表示复数，“这个”与“些”不能连用，应说“这些朋友”，不说“这个些朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你想看哪个些电影？", "corrected_sentence": "你想看哪些电影？", "error_description": "“哪些”表示复数，“哪个”与“些”不能连用，应说“哪些电影”，不说“哪个些电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9308a-b031-46a6-9843-931f0d6fff7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
