INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保证是说话算数，一定会做到。", "primary_collocate": null, "pronunciation": "bǎo zhèng", "ipa": "paʊ̯˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我保证明天一定来。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你放心，我保证不告诉别人。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他保证以后不再迟到。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈，我保证认真写作业。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我保证把这本书还给你。", "target_word": "保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我保证下次不会忘。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他保证过每天都给家里打电话。", "target_word": "保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟保证不吃太多糖。", "target_word": "保证", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你保证准时到，我才相信你。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我保证了，明天一定早起。", "target_word": "保证", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "保证了", "label": "体标"}, {"form": "保证过", "label": "体标"}, {"form": "保證", "label": "繁体"}, {"form": "保证书", "label": "复合"}], "register": "中性", "sense_fingerprint": "保证：动词，说话算数，答应一定做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86633, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确答案：保证（bǎo zhèng），表示说话算数、答应一定做到。"}, {"text": "暴政", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，暴政指残暴的统治，与“说话算数”无关。"}, {"text": "保重", "is_correct": false, "explanation": "zhòng 与 zhèng 韵母不同（ong 与 eng），保重指注意身体，不是承诺做到。"}, {"text": "保真", "is_correct": false, "explanation": "zhēn 与 zhèng 韵母和声调都不同（en 与 eng），保真指保持真实，不是承诺做到。"}], "explanations": {"保证": "正确答案：保证（bǎo zhèng），表示说话算数、答应一定做到。", "暴政": "bào（第四声）与 bǎo（第三声）声调不同，暴政指残暴的统治，与“说话算数”无关。", "保重": "zhòng 与 zhèng 韵母不同（ong 与 eng），保重指注意身体，不是承诺做到。", "保真": "zhēn 与 zhèng 韵母和声调都不同（en 与 eng），保真指保持真实，不是承诺做到。"}, "sentence_index": null, "correct_answer": "保证"}, "level_3": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确：保证表示答应一定做到，与“明天一定来”相符。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”表示不确定，与“一定来”矛盾。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”要带受话的人，如“通知他”，这里没有受话对象，句子不成立。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”要接被挑选的人或物，不能接“明天一定来”这样的动作句。"}], "explanations": {"保证": "正确：保证表示答应一定做到，与“明天一定来”相符。", "怀疑": "语义：“怀疑”表示不确定，与“一定来”矛盾。", "通知": "配价：“通知”要带受话的人，如“通知他”，这里没有受话对象，句子不成立。", "挑选": "搭配：“挑选”要接被挑选的人或物，不能接“明天一定来”这样的动作句。"}, "sentence_index": 0, "correct_answer": "保证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用这张照片来保证他去过北京。", "explanation": "这里应该用〈证明〉。用照片这类证据说明事实要说“证明”；“保证”是以个人名义作出担保或承诺，不是凭证据来论证事实。"}, {"text": "他保证自己错了。", "explanation": "这里应该用〈承认〉。保证是担保将来一定做到，不能用来承认过去的错误，承认错误要说“承认”。"}, {"text": "专家保证明天会下雨。", "explanation": "这里应该用〈预计〉。保证表示说话人担保一定做到或一定不出问题，天气等未来情况只能用“预计”来估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保证", "is_correct": true, "explanation": "正确：保证过表示曾经答应，与“每天都给家里打电话”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或环境，不能接“每天都给家里打电话”这样的动作短语。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”要带受批评的人，如“批评他”，这里接的是动作短语，没有合适的受事，句子不成立。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能接一个动作短语作宾语。"}], "explanations": {"保证": "正确：保证过表示曾经答应，与“每天都给家里打电话”相符。", "打扫": "搭配：“打扫”的对象是场所或环境，不能接“每天都给家里打电话”这样的动作短语。", "批评": "配价：“批评”要带受批评的人，如“批评他”，这里接的是动作短语，没有合适的受事，句子不成立。", "修理": "搭配：“修理”的对象是器物，不能接一个动作短语作宾语。"}, "sentence_index": 6, "correct_answer": "保证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我保证他明天会迟到，不过也说不准。", "explanation": "这里应该用〈猜〉。保证表示有把握、一定做到，后面又说“也说不准”，前后矛盾；对没把握的事只能说“猜”。"}, {"text": "他保证也许明天会来。", "explanation": "这里应该用〈推测〉。保证表示说定一定做到，对不确定的将来只能用“推测”来表示可能性。"}, {"text": "我保证他可能已经到家了。", "explanation": "这里应该用〈估计〉。保证表示说定、一定做到，与“可能”的不确定相矛盾；对没有把握的事只能说“估计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我保证着把钱还给他。", "corrected_sentence": "我保证把钱还给他。", "error_description": "“保证”后面不能直接加“着”，应说成“我保证把钱还给他”。“着”表示持续的状态，这里说的是将来的承诺，错在“保证”的体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他保证得以后每天早起。", "corrected_sentence": "他保证以后每天早起。", "error_description": "“保证”后面不能直接加“得”，应说成“他保证以后每天早起”。“得”是多余的，错在“保证”的搭配形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
