INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示事情达到某种程度，常用否定形式「不至于」，即还不到某种地步。", "primary_collocate": null, "pronunciation": "zhì yú", "ipa": "tʂʅ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "他说话有点急，还不至于吵架。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是感冒，不至于住院。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试有点难，不至于不及格。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很累，但还不至于哭。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块蛋糕而已，至于吵成这样吗？", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事，不至于生气吧。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下点小雨，不至于取消比赛。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只是迟到，老师不至于批评你。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你至于这么着急吗？", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然失败了，但不至于绝望。", "target_word": "至于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不至于", "label": "否定"}], "register": "中性", "sense_fingerprint": "事情还没到某种地步（常说不至于），或反问是否至于如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86636, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于 zhì yú 表示达到某种程度，常说「不至于」。"}, {"text": "治愈", "is_correct": false, "explanation": "治愈 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是治好病。"}, {"text": "智育", "is_correct": false, "explanation": "智育 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是智力教育。"}, {"text": "制约", "is_correct": false, "explanation": "制约 zhìyuē 第一音节相同，第二音节韵母 ü 与 üe 不同，声调也不同（yuē 第一声），意思是限制。"}], "explanations": {"至于": "正确：至于 zhì yú 表示达到某种程度，常说「不至于」。", "治愈": "治愈 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是治好病。", "智育": "智育 zhìyù 与至于 zhì yú 第一音节相同，第二音节 yù（第四声）与 yú（第二声）声调不同，意思是智力教育。", "制约": "制约 zhìyuē 第一音节相同，第二音节韵母 ü 与 üe 不同，声调也不同（yuē 第一声），意思是限制。"}, "sentence_index": null, "correct_answer": "至于"}, "level_3": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：「不至于」表示还没到吵架的地步，「至于」在这里表示事情的程度。"}, {"text": "从", "is_correct": false, "explanation": "语义：从表示起点，句中不是说从某时开始，「还不从吵架」说不通。"}, {"text": "按", "is_correct": false, "explanation": "语义：按表示依照某种标准，「还不按吵架」说不通，句中没有依据的意思。"}, {"text": "比", "is_correct": false, "explanation": "配价：比要求两项相比，此处没有比较的对象，无法构成比较结构。"}], "explanations": {"至于": "正确：「不至于」表示还没到吵架的地步，「至于」在这里表示事情的程度。", "从": "语义：从表示起点，句中不是说从某时开始，「还不从吵架」说不通。", "按": "语义：按表示依照某种标准，「还不按吵架」说不通，句中没有依据的意思。", "比": "配价：比要求两项相比，此处没有比较的对象，无法构成比较结构。"}, "sentence_index": 0, "correct_answer": "至于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "至于下雨，比赛推迟了。", "explanation": "这里应该用〈由于〉。〈至于〉表示程度，不引出原因，说明原因要用「由于」。"}, {"text": "他很努力，至于成绩很好。", "explanation": "这里应该用〈所以〉。〈至于〉表示程度，不引出结果，说明结果要用「所以」。"}, {"text": "他工作很认真，至于效率很高。", "explanation": "这里应该用〈而且〉。〈至于〉表示程度，不表示并列增加，说并列要用「而且」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86636, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：至于 zhì yú 表示达到某种程度，常说「不至于」。"}, {"text": "止于", "is_correct": false, "explanation": "止于 zhǐ yú 与至于 zhì yú 第二音节相同，第一音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是停在某处、到某处为止。"}, {"text": "志愿", "is_correct": false, "explanation": "志愿 zhìyuàn 第一音节相同，第二音节韵母由 ü 变为 üan，声调也不同（yuàn 第四声），意思是自愿或愿望。"}, {"text": "知遇", "is_correct": false, "explanation": "知遇 zhī yù 与至于 zhì yú 声母韵母相同，两个音节声调都不同（第一声、第四声），意思是得到赏识和重用。"}], "explanations": {"至于": "正确：至于 zhì yú 表示达到某种程度，常说「不至于」。", "止于": "止于 zhǐ yú 与至于 zhì yú 第二音节相同，第一音节 zhǐ（第三声）与 zhì（第四声）声调不同，意思是停在某处、到某处为止。", "志愿": "志愿 zhìyuàn 第一音节相同，第二音节韵母由 ü 变为 üan，声调也不同（yuàn 第四声），意思是自愿或愿望。", "知遇": "知遇 zhī yù 与至于 zhì yú 声母韵母相同，两个音节声调都不同（第一声、第四声），意思是得到赏识和重用。"}, "sentence_index": null, "correct_answer": "至于"}, "level_3": {"options": [{"text": "至于", "is_correct": true, "explanation": "正确：「不至于」表示小雨还不到取消比赛的程度，「至于」在这里表示程度。"}, {"text": "替", "is_correct": false, "explanation": "语义：替表示代替别人行动，「不替取消比赛」说不通。"}, {"text": "凭", "is_correct": false, "explanation": "语义：凭表示依据，「不凭取消比赛」说不通，句中没有依据的意思。"}, {"text": "在", "is_correct": false, "explanation": "配价：在后接地点，「取消比赛」不是地点，无法与「在」构成介词短语。"}], "explanations": {"至于": "正确：「不至于」表示小雨还不到取消比赛的程度，「至于」在这里表示程度。", "替": "语义：替表示代替别人行动，「不替取消比赛」说不通。", "凭": "语义：凭表示依据，「不凭取消比赛」说不通，句中没有依据的意思。", "在": "配价：在后接地点，「取消比赛」不是地点，无法与「在」构成介词短语。"}, "sentence_index": 6, "correct_answer": "至于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天早起，至于身体很好。", "explanation": "这里应该用〈因此〉。〈至于〉表示程度，不引出结果，说明结果要用「因此」。"}, {"text": "他学习很刻苦，至于考了第一名。", "explanation": "这里应该用〈所以〉。〈至于〉表示程度，不引出结果，说明结果要用「所以」。"}, {"text": "他很聪明，至于很努力。", "explanation": "这里应该用〈而且〉。〈至于〉表示程度，不表示并列增加，说并列要用「而且」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事，不至于了闹大。", "corrected_sentence": "这件事，不至于闹大。", "error_description": "「不至于」后面不能加「了」：「了」不能插在「不至于」和后面的动词或补语之间，应说「不至于闹大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只是擦伤，至于去医院。", "corrected_sentence": "他只是擦伤，不至于去医院。", "error_description": "缺少否定词「不」：「不至于」表示不到某种程度，去掉「不」意思相反，而且陈述句中一般不这么说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
