INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86637, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "场是数一件事有几回的词，比如一场雨、一场球。", "primary_collocate": null, "pronunciation": "cháng", "ipa": "ʈʂʰɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "昨天夜里下了一场大雨。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的冬天常常有一场大雪。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场雨过后，空气变得很清新。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生了一场病，在家休息了一周。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我做了一场很长的梦。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雪下了一整夜。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大火把房子烧光了。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雨来得很突然，我没带伞。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了一场，心里好多了。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的第一场雨下得很细。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场|量词|雨雪病梦等事情的回数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于雨雪病梦等事情的次数，读作 cháng（第二声），是本题答案。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。"}, {"text": "唱", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。"}, {"text": "馋", "is_correct": false, "explanation": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是贪吃。"}, {"text": "城", "is_correct": false, "explanation": "chéng（第二声）与 cháng 的韵母 -ang 与 -eng 不同，意思是城市。"}, {"text": "蝉", "is_correct": false, "explanation": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是蝉。"}], "explanations": {"场": "场：量词，用于雨雪病梦等事情的次数，读作 cháng（第二声），是本题答案。", "厂": "chǎng（第三声）与 cháng（第二声）声调不同，意思是工厂。", "唱": "chàng（第四声）与 cháng（第二声）声调不同，意思是唱歌。", "馋": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是贪吃。", "城": "chéng（第二声）与 cháng 的韵母 -ang 与 -eng 不同，意思是城市。", "蝉": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是蝉。"}, "sentence_index": null, "correct_answer": "场"}, "level_3": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于雨的次数，符合“下了一场大雨”。"}, {"text": "把", "is_correct": false, "explanation": "搭配：把用于有柄或可握的物件，雨不说“一把大雨”。"}, {"text": "座", "is_correct": false, "explanation": "搭配：座用于山、建筑等大物体，不说“一座大雨”。"}, {"text": "条", "is_correct": false, "explanation": "搭配：条用于细长的东西，雨不用“条”计数。"}], "explanations": {"场": "场：量词，用于雨的次数，符合“下了一场大雨”。", "把": "搭配：把用于有柄或可握的物件，雨不说“一把大雨”。", "座": "搭配：座用于山、建筑等大物体，不说“一座大雨”。", "条": "搭配：条用于细长的东西，雨不用“条”计数。"}, "sentence_index": 0, "correct_answer": "场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上个月我去过两场医院。", "explanation": "这里应该用〈次〉。去医院按次数计，“场”不用于去某地的次数。"}, {"text": "他坐了一场车，很快就到了。", "explanation": "这里应该用〈趟〉。坐车按趟计，“场”不用于乘车。"}, {"text": "他吃了一场饭，非常饱。", "explanation": "这里应该用〈顿〉。吃饭按顿计，不说“一场饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86637, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于雨雪病梦等事情的次数，读作 cháng（第二声），是本题答案。"}, {"text": "畅", "is_correct": false, "explanation": "chàng（第四声）与 cháng（第二声）声调不同，意思是畅快。"}, {"text": "程", "is_correct": false, "explanation": "chéng（第二声）与 cháng 的韵母 -ang 与 -eng 不同，意思是过程。"}, {"text": "缠", "is_correct": false, "explanation": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是缠绕。"}], "explanations": {"场": "场：量词，用于雨雪病梦等事情的次数，读作 cháng（第二声），是本题答案。", "畅": "chàng（第四声）与 cháng（第二声）声调不同，意思是畅快。", "程": "chéng（第二声）与 cháng 的韵母 -ang 与 -eng 不同，意思是过程。", "缠": "chán（第二声）与 cháng 的韵母 -n 与 -ng 不同，意思是缠绕。"}, "sentence_index": null, "correct_answer": "场"}, "level_3": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于火灾这类事件，符合“一场大火”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张用于平面物，不说“一张大火”。"}, {"text": "口", "is_correct": false, "explanation": "语义：口用于井、钟等物体，火不用“口”计数。"}, {"text": "块", "is_correct": false, "explanation": "语义：块指块状物，火不是块状物，不用“块”计数。"}], "explanations": {"场": "场：量词，用于火灾这类事件，符合“一场大火”。", "张": "搭配：张用于平面物，不说“一张大火”。", "口": "语义：口用于井、钟等物体，火不用“口”计数。", "块": "语义：块指块状物，火不是块状物，不用“块”计数。"}, "sentence_index": 6, "correct_answer": "场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一场衣服，很便宜。", "explanation": "这里应该用〈件〉或〈套〉。衣服按件计，“场”不用于衣物。"}, {"text": "这一场书很厚，我看了很久。", "explanation": "这里应该用〈本〉。书按本计，“场”不用于书籍。"}, {"text": "我们租了一场房子，住了三年。", "explanation": "这里应该用〈套〉或〈间〉。房子按套、间计，“场”不用于房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚下了大雪一场，路上很滑。", "corrected_sentence": "昨晚下了一场大雪，路上很滑。", "error_description": "错误形式：大雪一场；正确形式：一场大雪。数量词“一场”要放在名词“大雪”前面，不能放在名词后面。这里只错了“一场”的位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "场大雨来得很突然。", "corrected_sentence": "这场大雨来得很突然。", "error_description": "错误形式：场大雨来得很突然；正确形式：这场大雨来得很突然。量词“场”前漏掉指示代词“这”，名词短语不完整，这里错的是量词前的修饰成分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
