INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86638, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于文娱体育活动的次数。", "primary_collocate": null, "pronunciation": "chǎng", "ipa": "ʈʂʰɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "昨天晚上我们看了一场电影。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午有一场足球比赛。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这场比赛中进了两个球。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末学校有一场音乐会。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场球赛很精彩，大家都很高兴。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看明天的那场演出。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打了一场篮球，累坏了。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场舞会持续了三个小时。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月城里有一场演唱会。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们踢了一场球，最后赢了。", "target_word": "场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场|量词|文娱体育活动的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于文娱体育活动的次数，读作 chǎng（第三声），是本题答案。"}, {"text": "唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，意思是唱歌。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是长短的长。"}, {"text": "尝", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是品尝。"}, {"text": "产", "is_correct": false, "explanation": "chǎn（第三声）与 chǎng 的韵母 -n 与 -ng 不同，意思是生产。"}], "explanations": {"场": "场：量词，用于文娱体育活动的次数，读作 chǎng（第三声），是本题答案。", "唱": "chàng（第四声）与 chǎng（第三声）声调不同，意思是唱歌。", "长": "cháng（第二声）与 chǎng（第三声）声调不同，意思是长短的长。", "尝": "cháng（第二声）与 chǎng（第三声）声调不同，意思是品尝。", "产": "chǎn（第三声）与 chǎng 的韵母 -n 与 -ng 不同，意思是生产。"}, "sentence_index": null, "correct_answer": "场"}, "level_3": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于文娱活动，符合“看了一场电影”。"}, {"text": "座", "is_correct": false, "explanation": "搭配：座用于山、建筑等大物体，不说“一座电影”。"}, {"text": "把", "is_correct": false, "explanation": "语义：把用于有柄的东西，电影不用“把”计数。"}, {"text": "条", "is_correct": false, "explanation": "搭配：条用于细长的东西，电影不用“条”计数。"}], "explanations": {"场": "场：量词，用于文娱活动，符合“看了一场电影”。", "座": "搭配：座用于山、建筑等大物体，不说“一座电影”。", "把": "语义：把用于有柄的东西，电影不用“把”计数。", "条": "搭配：条用于细长的东西，电影不用“条”计数。"}, "sentence_index": 0, "correct_answer": "场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周去一场健身房。", "explanation": "这里应该用〈次〉。去健身房按次数计，“场”只用于文娱体育活动。"}, {"text": "我们去过一场博物馆。", "explanation": "这里应该用〈回〉。去博物馆按回数计，不用“场”。"}, {"text": "我们吃了一场苹果，很甜。", "explanation": "这里应该用〈个〉。苹果按“个”计，“场”不用于苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86638, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于文娱体育活动的次数，读作 chǎng（第三声），是本题答案。"}, {"text": "畅", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，意思是畅快。"}, {"text": "肠", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是肠子。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 chǎng 的声母 zh 与 ch 不同，意思是水位上涨。"}], "explanations": {"场": "场：量词，用于文娱体育活动的次数，读作 chǎng（第三声），是本题答案。", "畅": "chàng（第四声）与 chǎng（第三声）声调不同，意思是畅快。", "肠": "cháng（第二声）与 chǎng（第三声）声调不同，意思是肠子。", "涨": "zhǎng（第三声）与 chǎng 的声母 zh 与 ch 不同，意思是水位上涨。"}, "sentence_index": null, "correct_answer": "场"}, "level_3": {"options": [{"text": "场", "is_correct": true, "explanation": "场：量词，用于篮球比赛这类活动，符合“打了一场篮球”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张用于平面物，不说“一张篮球”。"}, {"text": "束", "is_correct": false, "explanation": "语义：束用于花、光等成束的东西，篮球比赛不能用“束”计数。"}, {"text": "块", "is_correct": false, "explanation": "语义：块指块状物，篮球比赛不是块状物，不能用“块”计数。"}], "explanations": {"场": "场：量词，用于篮球比赛这类活动，符合“打了一场篮球”。", "张": "搭配：张用于平面物，不说“一张篮球”。", "束": "语义：束用于花、光等成束的东西，篮球比赛不能用“束”计数。", "块": "语义：块指块状物，篮球比赛不是块状物，不能用“块”计数。"}, "sentence_index": 6, "correct_answer": "场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家里养了一场猪，有五头。", "explanation": "这里应该用〈头〉。猪按“头”计，“场”不用于计量猪。"}, {"text": "他戴了一场帽子，很好看。", "explanation": "这里应该用〈顶〉。帽子按“顶”计，“场”不用于帽子。"}, {"text": "他拿了一场笔，写完了作业。", "explanation": "这里应该用〈支〉。笔按“支”计，“场”不用于笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, va