INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在体育场打了一个篮球赛。", "corrected_sentence": "他们在体育场打了一场篮球赛。", "error_description": "错误形式：一个篮球赛；正确形式：一场篮球赛。篮球比赛计次要用量词“场”，不用“个”，这里错的是量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
