INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调是把东西弄得刚刚好。", "primary_collocate": null, "pronunciation": "tiáo", "ipa": "tʰiɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "水太热了，你调一下温度。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把电视的颜色调好了。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太凉了，加点热水，把水温调一下。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子调高了一点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太暗，请把相机的光线调亮一点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把空调调到二十六度。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把汤的味道调得刚好。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吉他的弦要先调好再弹。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把自行车座调低了。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机屏幕调暗了。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调了", "label": "体标"}, {"form": "调过", "label": "体标"}, {"form": "调节", "label": "复合"}], "register": "中性", "sense_fingerprint": "把温度、亮度、高低、味道等弄到刚好合适的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调 tiáo 表示把温度、亮度等调到合适的程度。"}, {"text": "跳", "is_correct": false, "explanation": "跳 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是跳跃。"}, {"text": "挑", "is_correct": false, "explanation": "挑 tiāo 与调 tiáo 声母和韵母相同，只有声调不同（第一声），意思是挑选。"}, {"text": "桃", "is_correct": false, "explanation": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}], "explanations": {"调": "正确：调 tiáo 表示把温度、亮度等调到合适的程度。", "跳": "跳 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是跳跃。", "挑": "挑 tiāo 与调 tiáo 声母和韵母相同，只有声调不同（第一声），意思是挑选。", "桃": "桃 táo 与调 tiáo 声调相同，只是少了介音 i，意思是桃子。"}, "sentence_index": null, "correct_answer": "调"}, "level_3": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调是动词，表示把温度调到合适，这里水太热，要调低。"}, {"text": "增", "is_correct": false, "explanation": "语义：增表示增加，句中水太热，应该调低，不能用「增」。"}, {"text": "放", "is_correct": false, "explanation": "搭配：放不能与「温度」搭配表示调节，「放一下温度」说不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧表示加热，句中要的是降低温度，不能用「烧」。"}], "explanations": {"调": "正确：调是动词，表示把温度调到合适，这里水太热，要调低。", "增": "语义：增表示增加，句中水太热，应该调低，不能用「增」。", "放": "搭配：放不能与「温度」搭配表示调节，「放一下温度」说不通。", "烧": "语义：烧表示加热，句中要的是降低温度，不能用「烧」。"}, "sentence_index": 0, "correct_answer": "调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把衣服调干净了。", "explanation": "这里应该用〈洗〉。〈调〉指调节到合适，不表示清洗，要说「洗干净了」。"}, {"text": "他把饭调熟了。", "explanation": "这里应该用〈煮〉。〈调〉指调节，不表示加热使食物变熟，要说「煮熟了」。"}, {"text": "她把鞋调干净了。", "explanation": "这里应该用〈刷〉。〈调〉指调节，不表示刷洗，要说「刷干净了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86639, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调 tiáo 表示把温度、亮度等调到合适的程度。"}, {"text": "掉", "is_correct": false, "explanation": "掉 diào 与调 tiáo 的声母不同（d 与 t），声调也不同，意思是落下。"}, {"text": "眺", "is_correct": false, "explanation": "眺 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是往远处看。"}, {"text": "套", "is_correct": false, "explanation": "套 tào 与调 tiáo 相比少了介音 i，声调也不同（第四声），意思是罩在外面的东西。"}], "explanations": {"调": "正确：调 tiáo 表示把温度、亮度等调到合适的程度。", "掉": "掉 diào 与调 tiáo 的声母不同（d 与 t），声调也不同，意思是落下。", "眺": "眺 tiào 与调 tiáo 声母和韵母相同，只有声调不同（第四声），意思是往远处看。", "套": "套 tào 与调 tiáo 相比少了介音 i，声调也不同（第四声），意思是罩在外面的东西。"}, "sentence_index": null, "correct_answer": "调"}, "level_3": {"options": [{"text": "调", "is_correct": true, "explanation": "正确：调是动词，表示把味道调到刚好，这里说汤的味道。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪表示用剪刀断开，句中说的是味道，「把味道剪得刚好」说不通。"}, {"text": "削", "is_correct": false, "explanation": "语义：削表示去掉表皮，与调味道无关，句意说不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：切表示分割，句中说的是味道，不是切开。"}], "explanations": {"调": "正确：调是动词，表示把味道调到刚好，这里说汤的味道。", "剪": "语义：剪表示用剪刀断开，句中说的是味道，「把味道剪得刚好」说不通。", "削": "语义：削表示去掉表皮，与调味道无关，句意说不通。", "切": "语义：切表示分割，句中说的是味道，不是切开。"}, "sentence_index": 6, "correct_answer": "调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给电脑调了新的硬盘。", "explanation": "这里应该用〈装〉。〈调〉指调节，不指安装硬件。"}, {"text": "她给自己调了一件新衣服。", "explanation": "这里应该用〈买〉。〈调〉指调节或配制，不表示购买衣物，要说「买了一件新衣服」。"}, {"text": "她把伞调进了包里。", "explanation": "这里应该用〈放〉。〈调〉指调整，不表示把东西放入某处，要说「放进了包里」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把灯光调了亮一些。", "corrected_sentence": "我把灯光调亮了一些。", "error_description": "「了」位置错误：应说「调亮了一些」，「了」不能插在「调」和「亮」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b4b349-44e8-4cc3-a8af-5d02fb58b96d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
