INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调整；配制。", "primary_collocate": null, "pronunciation": "tiáo", "ipa": "tʰiɑʊ˧˥", "syllable_count": 1, "sentences": [{"text": "请把闹钟调早一点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把座位调到前面。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用糖和水调了一杯糖水。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用水调了一碗面糊。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给孩子调了一杯蜂蜜水。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家在盘子里调颜色。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太大了，把音量调小点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把开会时间调到下午三点。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在碗里调蘸料，准备吃饺子。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把工作时间调了一下。", "target_word": "调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调了", "label": "体标"}, {"form": "调过", "label": "体标"}, {"form": "调整", "label": "复合"}], "register": "中性", "sense_fingerprint": "调整（时间、座位、音量）或把几种东西混合配制（调糖水、调颜色）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b75bf49-c43f-4514-936d-2f7a6e455359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED