INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "议会是国家里讨论大事、定规矩的地方。", "primary_collocate": null, "pronunciation": "yì huì", "ipa": "i˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的议会在首都。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会里的人在讨论新规定。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天议会开了一整天的会。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会通过了这个新办法。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷在议会工作过。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会门口站着很多记者。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参观了那个国家的议会。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会决定下个月再讨论这件事。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会的大楼又高又漂亮。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓希望议会多听大家的意见。", "target_word": "议会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "议会制", "label": "复合"}, {"form": "議會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家里讨论大事、定规矩的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "议会", "is_correct": true, "explanation": "议会是国家讨论大事的地方，设在首都，符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是大片水域，不会设在某国的首都。"}, {"text": "水稻", "is_correct": false, "explanation": "搭配：“在首都”要求机构或地点，水稻是作物，不能说“水稻在首都”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不属于某个国家，不会位于首都。"}], "explanations": {"议会": "议会是国家讨论大事的地方，设在首都，符合句意。", "海洋": "语义：海洋是大片水域，不会设在某国的首都。", "水稻": "搭配：“在首都”要求机构或地点，水稻是作物，不能说“水稻在首都”。", "太阳": "语义：太阳是天体，不属于某个国家，不会位于首都。"}, "sentence_index": 0, "correct_answer": "议会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家有一只议会，负责制定法律。", "explanation": "量词错误：议会是机构，应该用〈个〉。〈只〉多用于动物或成对物品中的一个，不能用于议会。"}, {"text": "这家公司的议会决定每个季度给员工发奖金。", "explanation": "这里应该用〈董事会〉。议会指国家的立法机关，公司的决策机构叫董事会，不说“公司议会”。"}, {"text": "议会判决了这起案件。", "explanation": "这里应该用〈法院〉。议会负责立法，判决案件是法院的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议会", "is_correct": true, "explanation": "议会是国家里讨论大事、定规矩的地方，可以去参观，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“参观”的对象是具体的场所或设施，空气不能被参观。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉上的感受，不能被参观。"}, {"text": "冬天", "is_correct": false, "explanation": "搭配：“参观”要求具体的地点或机构，冬天是时间，不能说“参观冬天”。"}], "explanations": {"议会": "议会是国家里讨论大事、定规矩的地方，可以去参观，符合句意。", "空气": "语义：“参观”的对象是具体的场所或设施，空气不能被参观。", "声音": "语义：声音是听觉上的感受，不能被参观。", "冬天": "搭配：“参观”要求具体的地点或机构，冬天是时间，不能说“参观冬天”。"}, "sentence_index": 6, "correct_answer": "议会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "议会负责执行法律。", "explanation": "这里应该用〈政府〉。议会负责制定法律，执行法律是政府的工作。"}, {"text": "我以后想当议会。", "explanation": "这里应该用〈议员〉。议会是机构，指个人时要说〈议员〉，不能说“当议会”。"}, {"text": "这个议会赢得了大多数选票。", "explanation": "这里应该用〈政党〉。议会是由选举产生的机构，不参加竞选，也不会“赢得选票”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家只有一只议会。", "corrected_sentence": "这个国家只有一个议会。", "error_description": "量词错误：议会是机构，应说“一个议会”，不能说“一只议会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民要把议会提出建议。", "corrected_sentence": "市民要向议会提出建议。", "error_description": "介词错误：“提出建议”的对象是议会，应用“向”引出，不能用“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
