INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "权力是可以让别人听自己的话、照自己的意思做事的力量。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰyɛn˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他是老板，有权力让我们加班。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸有权力决定家里的事。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长没有权力决定你什么时候回家。", "target_word": "权力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了权力，他就想让大家都听他的。", "target_word": "权力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想要权力，只想自由。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理用手里的权力帮了朋友。", "target_word": "权力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没有权力这样对我说话。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "权力大的人，说话别人都会听。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他得到权力以后，变得很骄傲。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师有权力让学生安静下来。", "target_word": "权力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种权力", "label": "量词"}, {"form": "权力机关", "label": "复合"}, {"form": "權力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能让别人听从自己、照自己意思做事的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cfcb1-6d77-42d7-8839-f55207ff99d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权力", "is_correct": true, "explanation": "正确：指能让别人听从的支配力，与“让我们加班”的语义相合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不能让人去加班，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能作为让别人加班的依据。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不能让人加班，填入后句子语义荒谬。"}], "explanations": {"权力": "正确：指能让别人听从的支配力，与“让我们加班”的语义相合。", "工资": "语义：工资是报酬，不能让人去加班，句意不通。", "身高": "体貌：身高是外形特征，不能作为让别人加班的依据。", "脾气": "语义：脾气不能让人加班，填入后句子语义荒谬。"}, "sentence_index": 0, "correct_answer": "权力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药物有很大的权力。", "explanation": "这里应该用“力量”。权力指可以让别人听从的支配力，药物的作用要用力量。"}, {"text": "他的数学权力很强。", "explanation": "这里应该用“能力”。权力是支配他人的力量，数学水平要用能力。"}, {"text": "学生承受着很大的权力。", "explanation": "这里应该用“压力”。“承受”的对象是压力，不能说承受权力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权力", "is_correct": true, "explanation": "正确：指能让别人听从、支配别人的力量，“没有权力这样对我说话”即无权支配对方，句意通顺。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的物件，不是支配别人的力量，填入后句意不通。"}, {"text": "鼻子", "is_correct": false, "explanation": "体貌：鼻子是身体的部位，不能用来表示说话的资格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能表示对他人的支配力，填入后句意不通。"}], "explanations": {"权力": "正确：指能让别人听从、支配别人的力量，“没有权力这样对我说话”即无权支配对方，句意通顺。", "钥匙": "语义：钥匙是开锁的物件，不是支配别人的力量，填入后句意不通。", "鼻子": "体貌：鼻子是身体的部位，不能用来表示说话的资格。", "颜色": "语义：颜色不能表示对他人的支配力，填入后句意不通。"}, "sentence_index": 6, "correct_answer": "权力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种炸弹的权力很大。", "explanation": "这里应该用“威力”。权力指支配他人的力量，炸弹的破坏力要用威力。"}, {"text": "他的足球权力很强。", "explanation": "这里应该用“实力”。权力指支配他人的力量，足球比赛中的水平要用实力。"}, {"text": "这台电脑的权力很强。", "explanation": "这里应该用“性能”。权力指支配他人的力量，电脑的运算能力要用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是老板，有一个权力决定大家的工作。", "corrected_sentence": "他是老板，有权力决定大家的工作。", "error_description": "量词错误：“权力”前不应加“一个”，“个”不能修饰抽象的权力；直接说“有权力”或“有一种权力”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长手里握有一把权力，能管理全班。", "corrected_sentence": "班长手里握有一种权力，能管理全班。", "error_description": "量词错误：“把”用于有柄的器具，不能修饰抽象的权力；应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
