INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86648, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合适；恰当。", "primary_collocate": null, "pronunciation": "shì dàng", "ipa": "ʂʐ̩˥˩ taŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们要找一个适当的时间谈谈。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法很适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词在这里用得不适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了他适当的帮助。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你选择适当的答案。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样批评他，不太适当。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找适当的人来做这件事。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在适当的时候，我会告诉你。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加面试，他的穿着很适当。", "target_word": "适当", "complexity_tier": "T3", "furigana": "cān jiā miàn shì, tā de chuān zhuo hěn shì dàng.", "sentence_source": "generated"}, {"text": "我们要想一个适当的办法。", "target_word": "适当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适当地", "label": "状语形式"}, {"form": "適當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做法、措辞、人选、时机等合适、恰当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适当", "is_correct": true, "explanation": "适当：时间合宜，适合谈话，与「我们要找一个」相符。"}, {"text": "红", "is_correct": false, "explanation": "语义：「红」指颜色，不能用来形容时间。"}, {"text": "黑", "is_correct": false, "explanation": "语义：「黑」指颜色，时间不能说黑。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」不用于形容时间。"}], "explanations": {"适当": "适当：时间合宜，适合谈话，与「我们要找一个」相符。", "红": "语义：「红」指颜色，不能用来形容时间。", "黑": "语义：「黑」指颜色，时间不能说黑。", "硬": "搭配：「硬」不用于形容时间。"}, "sentence_index": 0, "correct_answer": "适当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的性格很适当。", "explanation": "这里应该用〈温和〉或〈好〉。适当说做法、措辞、人选是否恰当，不用来评价人的性格。"}, {"text": "他的字写得很适当，很工整。", "explanation": "这里应该用〈工整〉。适当说做法、措辞、人选是否恰当，不用来评价字迹，字迹整齐要用〈工整〉。"}, {"text": "这碗汤的盐放得很适当，不咸不淡。", "explanation": "这里的「适当」是「不多不少」的意思，指调味分量恰好，与「合适恰当」的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适当", "is_correct": true, "explanation": "适当：人选合适，能胜任这件事，与「找」相符。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」指形状，不用于形容人选。"}, {"text": "绿", "is_correct": false, "explanation": "语义：「绿」指颜色，不用于形容人选。"}, {"text": "方", "is_correct": false, "explanation": "语义：「方」指形状，不用于形容人选。"}], "explanations": {"适当": "适当：人选合适，能胜任这件事，与「找」相符。", "圆": "语义：「圆」指形状，不用于形容人选。", "绿": "语义：「绿」指颜色，不用于形容人选。", "方": "语义：「方」指形状，不用于形容人选。"}, "sentence_index": 6, "correct_answer": "适当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很适当，看得很清楚。", "explanation": "这里应该用〈明亮〉。眼睛的状态要用〈明亮〉，适当不用来形容器官。"}, {"text": "我们家的猫很适当，每天都很可爱。", "explanation": "这里应该用〈可爱〉。适当说做法、人选是否恰当，不用来评价宠物，猫讨人喜欢要用〈可爱〉。"}, {"text": "这张桌子的颜色很适当。", "explanation": "这里应该用〈好看〉或〈雅致〉。适当说做法、措辞、人选是否恰当，不用来评价颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要选一个适当得地点开会。", "corrected_sentence": "我们要选一个适当的地点开会。", "error_description": "「适当得地点」应为「适当的地点」。“得”用于动词或形容词之后作补语，不用来修饰名词；修饰名词的“适当”要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案很适当地，大家都同意。", "corrected_sentence": "这个方案很适当，大家都同意。", "error_description": "「很适当地」应为「很适当」。“适当地”是状语形式，只修饰动词；作谓语的形容词后面不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
