INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86649, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "体验是自己亲身去试一试、感受一下。", "primary_collocate": null, "pronunciation": "tǐ yàn", "ipa": "tʰi˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "周末我想去农村体验一下生活。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种快乐，只有自己去体验才知道。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在工厂体验了一天工人的工作。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来北京，一定要体验一下坐地铁。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想体验一次滑雪，听说很好玩。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在农场体验过喂牛，非常开心。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里可以免费体验新手机的功能。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去山区当老师，想体验不同的生活。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客可以穿上汉服，体验古代人的生活。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次坐飞机，想好好体验一下。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "体验了", "label": "体标"}, {"form": "体验过", "label": "体标"}, {"form": "体验着", "label": "体标"}, {"form": "体验馆", "label": "复合"}, {"form": "體驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲自去试一试，感受一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86649, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体验", "is_correct": true, "explanation": "「体验」指亲自去经历、感受，与「去农村」「生活」搭配。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：「参加」接活动、比赛，不能说「参加一下生活」。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」接场所或展品，不接「生活」这样的抽象对象。"}, {"text": "结束", "is_correct": false, "explanation": "语义：「结束生活」意思是生命或日子终结，与周末去农村的语境相反。"}], "explanations": {"体验": "「体验」指亲自去经历、感受，与「去农村」「生活」搭配。", "参加": "搭配：「参加」接活动、比赛，不能说「参加一下生活」。", "参观": "搭配：「参观」接场所或展品，不接「生活」这样的抽象对象。", "结束": "语义：「结束生活」意思是生命或日子终结，与周末去农村的语境相反。"}, "sentence_index": 0, "correct_answer": "体验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在电视前体验比赛。", "explanation": "这里应该用〈收看〉。「体验」要求亲身参与、感受，坐在电视前看比赛只能说〈收看〉。"}, {"text": "工程师体验了机器的零件。", "explanation": "这里应该用〈检查〉。「体验」是亲身感受，不能用来表示对机器零件的检查。"}, {"text": "学生们在课堂上体验历史年表。", "explanation": "这里应该用〈记忆〉。「体验」强调亲身感受，不能用来表示死记硬背历史年表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体验", "is_correct": true, "explanation": "「体验」指亲自试用、感受功能，与「免费」「新手机」的语境吻合。"}, {"text": "删除", "is_correct": false, "explanation": "语义：「删除」是去掉已有的内容，店里提供的是让人试用，不是删去功能。"}, {"text": "购买", "is_correct": false, "explanation": "语义：「购买」的对象是商品，句中是试用，不是买下功能。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」针对损坏的东西，新手机的功能不需要修理。"}], "explanations": {"体验": "「体验」指亲自试用、感受功能，与「免费」「新手机」的语境吻合。", "删除": "语义：「删除」是去掉已有的内容，店里提供的是让人试用，不是删去功能。", "购买": "语义：「购买」的对象是商品，句中是试用，不是买下功能。", "修理": "语义：「修理」针对损坏的东西，新手机的功能不需要修理。"}, "sentence_index": 6, "correct_answer": "体验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去体验爷爷。", "explanation": "这里应该用〈拜访〉。「体验」指亲身经历某种生活或活动，不能用来指去看望人。"}, {"text": "我从朋友那里体验了这件事。", "explanation": "这里应该用〈听说〉。「体验」要求亲身经历，从别人那里得知的事情不能说「体验」。"}, {"text": "他每天体验报纸。", "explanation": "这里应该用〈阅读〉。「体验」的对象是生活、活动，不能用来指读报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去农村体验着一下生活。", "corrected_sentence": "我想去农村体验一下生活。", "error_description": "错误：“体验着一下”，“着”不能加在“体验”后面，“体验一下”是完整的短语；正确：“体验一下生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她第一次坐飞机，很想体验得一下。", "corrected_sentence": "她第一次坐飞机，很想体验一下。", "error_description": "「得」不能插在动词「体验」和「一下」之间，应说「体验一下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
