INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲身经历；通过实践来认识。", "primary_collocate": null, "pronunciation": "tǐ yàn", "ipa": "tʰi˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "只有亲身体验，才能明白工作的辛苦。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他到农村住了一年，体验到了农民的生活。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们通过实验体验科学的快乐。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在国外体验过很多不同的文化。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了妈妈以后，她才体验到妈妈的辛苦。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要多体验生活，不能只看书。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在西藏体验着另一种生活。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次志愿活动让我体验到了帮助别人的快乐。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有亲自体验，就很难写出真实的感受。", "target_word": "体验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每年都去不同的国家，体验当地人的日子。", "target_word": "体验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体验了", "label": "体标"}, {"form": "体验过", "label": "体标"}, {"form": "体验着", "label": "体标"}, {"form": "体验课", "label": "复合"}, {"form": "體驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲身经历后真正认识、明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体验", "is_correct": true, "explanation": "「体验」即亲身经历，与「亲身」和「才能明白」相符。"}, {"text": "猜想", "is_correct": false, "explanation": "语义：「亲身」与「猜想」相矛盾，靠猜想不能真正明白工作的辛苦。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与「明白」意思相反，句意不通。"}, {"text": "查阅", "is_correct": false, "explanation": "配价：「查阅」需要资料之类的宾语，句中没有可以查阅的对象，与「亲身」也不合。"}], "explanations": {"体验": "「体验」即亲身经历，与「亲身」和「才能明白」相符。", "猜想": "语义：「亲身」与「猜想」相矛盾，靠猜想不能真正明白工作的辛苦。", "忘记": "语义：「忘记」与「明白」意思相反，句意不通。", "查阅": "配价：「查阅」需要资料之类的宾语，句中没有可以查阅的对象，与「亲身」也不合。"}, "sentence_index": 0, "correct_answer": "体验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天体验天气预报。", "explanation": "这里应该用〈收听〉。「体验」要求亲身感受，不能用来指听天气预报。"}, {"text": "我从窗口体验一只鸟飞过。", "explanation": "这里应该用〈看见〉。「体验」要求亲身感受，不能用来表示从远处看到一只鸟飞过。"}, {"text": "科学家在实验室体验细胞的变化。", "explanation": "这里应该用〈观察〉。「体验」强调自己的感受和经历，不能用来指研究者观察细胞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体验", "is_correct": true, "explanation": "「体验」表示亲身过一种生活，与「另一种生活」搭配。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：「修改」接计划、文章等，不能说「修改另一种生活」。"}, {"text": "猜测", "is_correct": false, "explanation": "语义：「猜测」用于不确定的事，句中说的是他实际在西藏的生活，不能猜测。"}, {"text": "拆散", "is_correct": false, "explanation": "搭配：「拆散」接家庭、组合等，不能用于「另一种生活」这样的生活方式。"}], "explanations": {"体验": "「体验」表示亲身过一种生活，与「另一种生活」搭配。", "修改": "搭配：「修改」接计划、文章等，不能说「修改另一种生活」。", "猜测": "语义：「猜测」用于不确定的事，句中说的是他实际在西藏的生活，不能猜测。", "拆散": "搭配：「拆散」接家庭、组合等，不能用于「另一种生活」这样的生活方式。"}, "sentence_index": 6, "correct_answer": "体验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从报纸上体验了这个消息。", "explanation": "这里应该用〈得知〉。「体验」要求亲身经历，从报纸上获得的消息不能说「体验」。"}, {"text": "他体验了三年的古代文字。", "explanation": "这里应该用〈研究〉。「体验」指亲身感受，不能用来表示做学术研究。"}, {"text": "老人向我们体验战争的故事。", "explanation": "这里应该用〈讲述〉。「体验」是亲身感受，不是把经历讲给别人听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天在西部体验过牧民的生活。", "corrected_sentence": "他明天在西部体验牧民的生活。", "error_description": "错误：“体验过”表示已经发生的经历，而“明天”指将来，不能用“过”；应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次志愿活动让我体验了过帮助别人的快乐。", "corrected_sentence": "这次志愿活动让我体验过帮助别人的快乐。", "error_description": "错误：“了”和“过”不能同时用在动词“体验”之后，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "永远是一直这样，不会结束。", "primary_collocate": null, "pronunciation": "yǒng yuǎn", "ipa": "jʊŋ˨˩ ɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "世界上没有永远不变的东西。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事永远不会结束。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他永远留在了这座小城。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望春天永远不走。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笑容永远在我心里。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人能永远年轻。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路好像永远走不完。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们永远住在海边的小房子里。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子永远是父母的宝贝。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌我永远听不够。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "永永远远", "label": "重叠"}], "register": "中性", "sense_fingerprint": "副词；状态一直这样、不会结束或改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示状态一直不变、不会结束，与“永远不变的东西”相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“不变”的持久状态无关，句子不通。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示立即，不能说明事物持续不变。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”表示刚发生，不能修饰“不变的东西”这种长期状态。"}], "explanations": {"永远": "正确。“永远”表示状态一直不变、不会结束，与“永远不变的东西”相符。", "马上": "语义：“马上”表示很快发生，与“不变”的持久状态无关，句子不通。", "立刻": "语义：“立刻”表示立即，不能说明事物持续不变。", "刚刚": "搭配：“刚刚”表示刚发生，不能修饰“不变的东西”这种长期状态。"}, "sentence_index": 0, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨永远下了三天。", "explanation": "这里误把“永远”当成了“一连”（连续不断地持续若干时间）。“永远”没有终点，不能限定为“三天”。"}, {"text": "我永远去过那家店一次。", "explanation": "这里误把“永远”当成了“从来”（用于否定，表示一直没有过）。“永远”表示没有终点，不能与“去过一次”这样有限的次数搭配。"}, {"text": "他永远在下午五点吃完了饭。", "explanation": "这里误把“永远”当成了“正好”（恰好在某一时刻）。“永远”不能修饰在确定时间点完成的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示状态一直持续、没有终点，与“走不完”相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上发生，与“走不完”所描述的长久状态不符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与描述现在状态的“好像……走不完”时态不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，改变了“走不完”的持续含义，与“好像……永远走不完”的描述不符。"}], "explanations": {"永远": "正确。“永远”表示状态一直持续、没有终点，与“走不完”相符。", "立即": "语义：“立即”表示马上发生，与“走不完”所描述的长久状态不符。", "曾经": "语义：“曾经”指过去，与描述现在状态的“好像……走不完”时态不符。", "偶尔": "语义：“偶尔”表示有时，改变了“走不完”的持续含义，与“好像……永远走不完”的描述不符。"}, "sentence_index": 6, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他永远找到了工作。", "explanation": "这里误把“永远”当成了“终于”（经过努力后最终达到）。“永远”表示没有终点，不能表示“最后找到”。"}, {"text": "这次考试他永远考了满分。", "explanation": "这里误把“永远”当成了“竟然”（出乎意料）。“永远”表示没有终点，不能表示“竟然考了满分”的意外。"}, {"text": "你永远马上过来吧。", "explanation": "这里误把“永远”当成了表示“立即、很快”的词。“永远”没有时间终点，不能表示即刻过来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他永远了爱着这座小城。", "corrected_sentence": "他永远爱着这座小城。", "error_description": "助词位置错误：“了”不能插在副词“永远”与动词之间，须删去。正确的说法是“他永远爱着这座小城。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他永远记得了这件事。", "corrected_sentence": "他永远记得这件事。", "error_description": "错误在“了”。“永远”表示状态一直持续、没有终点，后面的“记得”不能再加表示完成的“了”，须删去。正确的说法是“他永远记得这件事。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
