INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86652, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "时间上没有终点；总是，始终。", "primary_collocate": null, "pronunciation": "yǒng yuǎn", "ipa": "jʊŋ˨˩ ɥɛn˨˩", "syllable_count": 2, "sentences": [{"text": "我永远不会忘记这个夏天。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她永远是我最好的朋友。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我永远记着。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他永远都那么忙，没有时间休息。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们永远在一起，好不好？", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈永远爱着我们。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个秘密我会永远放在心里。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "永远不要放弃你的梦想。", "target_word": "永远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说的话，我永远不会忘。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷永远那么高兴，从不生气。", "target_word": "永远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "永永远远", "label": "重叠"}], "register": "中性", "sense_fingerprint": "副词；时间上没有终点，总是、始终如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示时间上没有终点，与“永远不会忘记”相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快发生，与“永远不会忘记”的长久含义相冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“不会忘记”的持续含义相反。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”指刚过去的时间，不能与表示将来的“不会忘记”搭配。"}], "explanations": {"永远": "正确。“永远”表示时间上没有终点，与“永远不会忘记”相符。", "马上": "语义：“马上”表示很快发生，与“永远不会忘记”的长久含义相冲突。", "偶尔": "语义：“偶尔”表示有时，与“不会忘记”的持续含义相反。", "刚才": "搭配：“刚才”指刚过去的时间，不能与表示将来的“不会忘记”搭配。"}, "sentence_index": 0, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我永远在昨天下午三点完成了作业。", "explanation": "这里误把“永远”当成了“已经”（表示动作在某个时刻已经完成）。“永远”表示时间没有终点，不能用来限定在昨天下午三点完成的动作。"}, {"text": "他永远来过北京一次。", "explanation": "这里误把“永远”当成了“从来”（用于否定，表示一直没有过）。“永远”表示没有终点，不能与“来过一次”这样有限的次数搭配。"}, {"text": "我的电脑永远坏了三天。", "explanation": "这里误把“永远”当成了“整整”（强调时间足足有多长）。“永远”没有终点，不能限定在“三天”之内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永远", "is_correct": true, "explanation": "正确。“永远”表示时间上没有终点，与“永远放在心里”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“放在心里”所表达的长久保存相冲突。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的事，与表示将来的“我会”时态不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”表示刚发生，不能与表示将来的“会”搭配。"}], "explanations": {"永远": "正确。“永远”表示时间上没有终点，与“永远放在心里”相符。", "立刻": "语义：“立刻”表示马上发生，与“放在心里”所表达的长久保存相冲突。", "曾经": "语义：“曾经”指过去的事，与表示将来的“我会”时态不符。", "刚刚": "搭配：“刚刚”表示刚发生，不能与表示将来的“会”搭配。"}, "sentence_index": 6, "correct_answer": "永远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我永远考上了大学。", "explanation": "这里误把“永远”当成了“终于”（经过努力后最终达到）。“永远”表示时间没有终点，不能表示“最后考上”。"}, {"text": "今天的天气永远好。", "explanation": "这里误把“永远”当成了“一直”（持续到某个时段）。“今天”只限定在一天之内，与“永远”没有终点的含义矛盾。"}, {"text": "你永远马上回来吧。", "explanation": "这里误把“永远”当成了表示“立即、很快”的词。“永远”没有时间终点，不能表示即刻回来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我永远了记着这件事。", "corrected_sentence": "我永远记着这件事。", "error_description": "助词位置错误：“了”不能插在副词“永远”与动词之间，须删去。正确的说法是“我永远记着这件事。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他永远的爱着妈妈。", "corrected_sentence": "他永远地爱着妈妈。", "error_description": "助词错误：“永远”修饰动词“爱”时应用“地”，写成“的”把它当成了定语，句子不通。正确的说法是“他永远地爱着妈妈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
