INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86653, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "不才是古时候的人说自己时用的客气话。", "primary_collocate": null, "pronunciation": "bù cái", "ipa": "pu˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "不才愿先敬各位一杯。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就请交给不才吧。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才才疏学浅，请多指教。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "承蒙厚爱，不才感激不尽。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生过奖了，不才不敢当。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才今天来，是想向您请教。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位请坐，不才给大家讲个故事。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拱手说道：“不才姓李，名明。”", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗是不才随手写的，让您见笑了。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您若不嫌弃，不才愿陪您走一趟。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古雅", "sense_fingerprint": "古人谦称自己的客气话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86653, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。不才（bù cái）是古人谦称自己的客气话。"}, {"text": "布菜", "is_correct": false, "explanation": "cài（第四声）与 cái（第二声）声调不同，“布菜”意思是给客人夹菜，与谦称无关。"}, {"text": "不睬", "is_correct": false, "explanation": "cǎi（第三声）与 cái（第二声）声调不同，“不睬”意思是不理会。"}, {"text": "不踩", "is_correct": false, "explanation": "cǎi（第三声）与 cái（第二声）声调不同，“不踩”意思是脚不踏上去。"}, {"text": "不藏", "is_correct": false, "explanation": "cáng 与 cái 韵母不同（ang 与 ai），“不藏”意思是不隐藏。"}], "explanations": {"不才": "正确。不才（bù cái）是古人谦称自己的客气话。", "布菜": "cài（第四声）与 cái（第二声）声调不同，“布菜”意思是给客人夹菜，与谦称无关。", "不睬": "cǎi（第三声）与 cái（第二声）声调不同，“不睬”意思是不理会。", "不踩": "cǎi（第三声）与 cái（第二声）声调不同，“不踩”意思是脚不踏上去。", "不藏": "cáng 与 cái 韵母不同（ang 与 ai），“不藏”意思是不隐藏。"}, "sentence_index": null, "correct_answer": "不才"}, "level_3": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。说话人敬酒时用古雅的自谦说法指自己。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”是对听话人的敬称，不能用来指正在敬酒的说话人自己。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”把说话人和对方都包括在内，与“敬各位”的敬酒关系矛盾。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指的就是“各位”，敬酒的一方不能是被敬的对象。"}], "explanations": {"不才": "正确。说话人敬酒时用古雅的自谦说法指自己。", "您": "语义：“您”是对听话人的敬称，不能用来指正在敬酒的说话人自己。", "大家": "语义：“大家”把说话人和对方都包括在内，与“敬各位”的敬酒关系矛盾。", "你们": "语义：“你们”指的就是“各位”，敬酒的一方不能是被敬的对象。"}, "sentence_index": 0, "correct_answer": "不才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "您不才先请坐吧。", "explanation": "“不才”只用于说话人自称，这里指听话人，不能用“不才”来称呼对方。"}, {"text": "他叫不才，是我的老同学。", "explanation": "“不才”是自谦代词，不是人名，不能当作名字使用。"}, {"text": "这本书不才很厚。", "explanation": "“不才”只能指说话人，不能用来指事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。说话人自己要帮大家讲故事，用古雅的自谦说法指自己。"}, {"text": "敌方", "is_correct": false, "explanation": "语义：“敌方”是对立的一方，不会出现在请各位坐下、给大家讲故事的待客场景中。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”是口语说法，与这里客气的自谦语气不协调。"}, {"text": "各自", "is_correct": false, "explanation": "语法：“各自”需要复数的先行主语，“各位请坐，各自给大家讲个故事”说不通。"}], "explanations": {"不才": "正确。说话人自己要帮大家讲故事，用古雅的自谦说法指自己。", "敌方": "语义：“敌方”是对立的一方，不会出现在请各位坐下、给大家讲故事的待客场景中。", "人家": "语域：“人家”是口语说法，与这里客气的自谦语气不协调。", "各自": "语法：“各自”需要复数的先行主语，“各位请坐，各自给大家讲个故事”说不通。"}, "sentence_index": 6, "correct_answer": "不才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不才到，请大家先坐。", "explanation": "“不才”是自谦代词，不能表示“刚”的意思。这里应表示刚到，但“不才”没有这个用法。"}, {"text": "我们不才都愿意帮忙。", "explanation": "“不才”只用于说话人单独自称，不能加在“我们”上表示复数。"}, {"text": "他不才地跑进了屋子。", "explanation": "“不才”是自谦用语，不能用来形容动作笨拙。这里应表示笨拙的意思，但“不才”没有这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不才的愿意请大家喝一杯。", "corrected_sentence": "不才愿意请大家喝一杯。", "error_description": "错误形式是“不才的愿意”，在“不才”后多加了“的”。正确形式是“不才愿意”。“的”后面不能直接接动词，作主语的“不才”后也不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不才们愿来帮大家的忙。", "corrected_sentence": "不才愿来帮大家的忙。", "error_description": "错误形式是“不才们”，给“不才”加了复数词尾“们”。正确形式是“不才愿来”。“不才”是单数的自称，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
