INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86654, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "旧时谦称自己。", "primary_collocate": null, "pronunciation": "bù cái", "ipa": "pu˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "老先生请放心，不才一定尽力。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才这就告辞，改日再来拜访。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事不才早已知道。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才不会喝酒，请见谅。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公子谬赞，不才惭愧。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能为您效劳，是不才的荣幸。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才愿拜您为师。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不才住在城西，欢迎您来做客。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店简陋，让您见笑，不才失礼了。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事，不才来办就好。", "target_word": "不才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古雅", "sense_fingerprint": "旧时对别人谦称自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。不才（bù cái）是旧时对别人谦称自己。"}, {"text": "布菜", "is_correct": false, "explanation": "cài（第四声）与 cái（第二声）声调不同，“布菜”意思是给客人夹菜，与谦称无关。"}, {"text": "不睬", "is_correct": false, "explanation": "cǎi（第三声）与 cái（第二声）声调不同，“不睬”意思是不理会。"}, {"text": "不踩", "is_correct": false, "explanation": "cǎi（第三声）与 cái（第二声）声调不同，“不踩”意思是脚不踏上去。"}, {"text": "不藏", "is_correct": false, "explanation": "cáng 与 cái 韵母不同（ang 与 ai），“不藏”意思是不隐藏。"}], "explanations": {"不才": "正确。不才（bù cái）是旧时对别人谦称自己。", "布菜": "cài（第四声）与 cái（第二声）声调不同，“布菜”意思是给客人夹菜，与谦称无关。", "不睬": "cǎi（第三声）与 cái（第二声）声调不同，“不睬”意思是不理会。", "不踩": "cǎi（第三声）与 cái（第二声）声调不同，“不踩”意思是脚不踏上去。", "不藏": "cáng 与 cái 韵母不同（ang 与 ai），“不藏”意思是不隐藏。"}, "sentence_index": null, "correct_answer": "不才"}, "level_3": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。说话人向对方保证自己会尽力，用旧时的自谦说法指自己。"}, {"text": "敌方", "is_correct": false, "explanation": "语义：“敌方”是对立的一方，不会替说话人向老先生保证尽力。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”是口语说法，与这里客气的保证语气不协调。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指听话人，让对方去尽力，与“请放心”的承诺者不符。"}], "explanations": {"不才": "正确。说话人向对方保证自己会尽力，用旧时的自谦说法指自己。", "敌方": "语义：“敌方”是对立的一方，不会替说话人向老先生保证尽力。", "人家": "语域：“人家”是口语说法，与这里客气的保证语气不协调。", "您": "语义：“您”指听话人，让对方去尽力，与“请放心”的承诺者不符。"}, "sentence_index": 0, "correct_answer": "不才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试成绩很不才。", "explanation": "“不才”是自谦用语，不能用来说别人或事物的成绩差，这里应表示“差”的意思，但“不才”没有这个用法。"}, {"text": "这间屋子不才很大。", "explanation": "“不才”只指说话人自己，不能用来形容房子。"}, {"text": "不才是我的名字。", "explanation": "“不才”是自谦用语，不是名字，不能当作名字使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不才", "is_correct": true, "explanation": "正确。说话人愿意拜对方为师，用旧时的自谦说法指自己。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人和听话人，而拜师的对象正是听话人，两者矛盾。"}, {"text": "双方", "is_correct": false, "explanation": "语义：“双方”指事情中对立或相互交涉的两方，与拜师的关系不符。"}, {"text": "敌方", "is_correct": false, "explanation": "语义：“敌方”是对立的一方，不可能愿意拜对方为师。"}], "explanations": {"不才": "正确。说话人愿意拜对方为师，用旧时的自谦说法指自己。", "咱们": "语义：“咱们”包括说话人和听话人，而拜师的对象正是听话人，两者矛盾。", "双方": "语义：“双方”指事情中对立或相互交涉的两方，与拜师的关系不符。", "敌方": "语义：“敌方”是对立的一方，不可能愿意拜对方为师。"}, "sentence_index": 6, "correct_answer": "不才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不才吃完饭，就出去了。", "explanation": "“不才”是自谦用语，不能表示“刚”的意思。这里应表示刚吃完饭，但“不才”没有这个用法。"}, {"text": "这位不才先生是我的老师。", "explanation": "“不才”只用于说话人自称，不能用来指第三人。这里是介绍别人，应去掉“不才”。"}, {"text": "我们几个不才都想去帮忙。", "explanation": "“不才”只用于说话人单独自称，不能加在“我们几个”上表示群体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请您放心，不才的一定尽力办好。", "corrected_sentence": "请您放心，不才一定尽力办好。", "error_description": "错误形式是“不才的一定”，在“不才”后多加了“的”。正确形式是“不才一定”。作主语的“不才”后面不加“的”，直接接副词和动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件小事，不才们去办就好。", "corrected_sentence": "这件小事，不才去办就好。", "error_description": "错误形式是“不才们”，给“不才”加了复数词尾“们”。正确形式是“不才去”。“不才”是单数的自称，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
