INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "消息是别人告诉我们的新鲜事。", "primary_collocate": null, "pronunciation": "xiāo xi", "ipa": "ɕjɑʊ˥ ɕi", "syllable_count": 2, "sentences": [{"text": "小王告诉我一个好消息。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有他的消息吗？", "target_word": "消息", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友刚才发来了一个消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听到一个有意思的消息。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她搬家以后，我就没有她的消息了。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有什么新消息，请马上告诉我。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息让大家都很高兴。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友说了个消息：下周放假。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听说了吗？这个消息太让人吃惊了。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟出国一年了，家里没有他的消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "好消息", "label": "复合"}, {"form": "坏消息", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词；别人告知的新鲜事、音信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消息", "is_correct": true, "explanation": "正确。“消息”指别人告诉的新鲜事，与“告诉我一个好消息”相符。"}, {"text": "礼物", "is_correct": false, "explanation": "配价：“告诉”的宾语应是消息或话，不能是礼物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“告诉我”的内容应是信息，石头不能被告知。"}, {"text": "野草", "is_correct": false, "explanation": "语义：野草不能作为“告诉我”的内容，与“好”也不搭配。"}], "explanations": {"消息": "正确。“消息”指别人告诉的新鲜事，与“告诉我一个好消息”相符。", "礼物": "配价：“告诉”的宾语应是消息或话，不能是礼物。", "石头": "语义：“告诉我”的内容应是信息，石头不能被告知。", "野草": "语义：野草不能作为“告诉我”的内容，与“好”也不搭配。"}, "sentence_index": 0, "correct_answer": "消息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他唱起了有意思的消息。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌，消息是别人告诉我们的新鲜事，不能用来唱。"}, {"text": "我听到一只有意思的消息。", "explanation": "这里应该用〈条〉。“消息”的量词是“条”，“只”多用于动物，不能用于消息。"}, {"text": "这首歌的消息很好听。", "explanation": "这里应该用〈音乐〉。“好听”用来形容音乐、声音，消息是别人告诉我们的新鲜事，不能形容它们。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消息", "is_correct": true, "explanation": "正确。“消息”指别人告诉我们的新鲜事，与“让大家都很高兴”相符。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：台阶不是能让大家高兴的事，与语境不符。"}, {"text": "旁边", "is_correct": false, "explanation": "语法：“旁边”是方位词，不能受“这个”修饰，也不能让人高兴。"}, {"text": "以后", "is_correct": false, "explanation": "语法：“以后”是时间词，不能说“这个以后”，句子不通。"}], "explanations": {"消息": "正确。“消息”指别人告诉我们的新鲜事，与“让大家都很高兴”相符。", "台阶": "语义：台阶不是能让大家高兴的事，与语境不符。", "旁边": "语法：“旁边”是方位词，不能受“这个”修饰，也不能让人高兴。", "以后": "语法：“以后”是时间词，不能说“这个以后”，句子不通。"}, "sentence_index": 6, "correct_answer": "消息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚做了一个奇怪的消息。", "explanation": "这里应该用〈梦〉。“做”搭配梦，消息是别人告诉我们的新鲜事，不能用“做”。"}, {"text": "我把弟弟的消息放进了行李箱。", "explanation": "这里应该用〈衣服〉。“放进行李箱”针对可以装箱的实物，消息是别人告诉我们的新鲜事，不能装进箱子。"}, {"text": "他的消息很高，能打篮球。", "explanation": "这里应该用〈个子〉。“高”用来形容人的身高，消息不能用来形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她发来一只消息，说明天不来了。", "corrected_sentence": "她发来一条消息，说明天不来了。", "error_description": "量词错误：“消息”应搭配量词“条”，“只”多用于动物，不能用于消息。正确的说法是“她发来一条消息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没吃消息。", "corrected_sentence": "我还没收到消息。", "error_description": "搭配错误：“消息”不能与“吃”搭配，应说“收到消息”。正确的说法是“我还没收到消息。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
