INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于人或事物情况的报道或通知。", "primary_collocate": null, "pronunciation": "xiāo xi", "ipa": "ɕjɑʊ˥ ɕi", "syllable_count": 2, "sentences": [{"text": "报纸上有一条重要的消息。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视里正在播报一条重要消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息很快传开了。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司发布了新产品的消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有收到面试的消息。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上说比赛取消了，这个消息是真的吗？", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直在等学校的消息。", "target_word": "消息", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的新闻里有地震的消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我带来了好消息。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息是政府今天早上发布的。", "target_word": "消息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "好消息", "label": "复合"}, {"form": "坏消息", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词；报道、通知类的消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消息", "is_correct": true, "explanation": "正确。“消息”指报道或通知，与“重要的消息”相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：报纸上刊登的是报道，不会是河流，与“报纸上”的语境冲突。"}, {"text": "作业", "is_correct": false, "explanation": "语义：报纸上不会刊登作业，与“报纸上”的语境冲突。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：报纸上刊登的是报道或通知，不会是裙子，与“报纸上”的语境冲突。"}], "explanations": {"消息": "正确。“消息”指报道或通知，与“重要的消息”相符。", "河流": "语义：报纸上刊登的是报道，不会是河流，与“报纸上”的语境冲突。", "作业": "语义：报纸上不会刊登作业，与“报纸上”的语境冲突。", "裙子": "语义：报纸上刊登的是报道或通知，不会是裙子，与“报纸上”的语境冲突。"}, "sentence_index": 0, "correct_answer": "消息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在会上提出了一个消息。", "explanation": "这里应该用〈意见〉。“提出”搭配意见、建议等，消息指报道或通知，不能被提出。"}, {"text": "我收到了一只消息。", "explanation": "这里应该用〈条〉。“消息”的量词是“条”，“只”多用于动物等，不能用于消息。"}, {"text": "这首歌的消息很好听。", "explanation": "这里应该用〈音乐〉。“好听”用来形容音乐、声音，消息指报道或通知，不能用来形容它们。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消息", "is_correct": true, "explanation": "正确。“消息”指报道或通知，可以被“他们一直在等”。"}, {"text": "操场", "is_correct": false, "explanation": "语义：“等”的对象应是可以等来的消息或通知，“操场”不是可等待的信息。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以被“等”来的事物，与“等学校的”语境不符。"}, {"text": "笑容", "is_correct": false, "explanation": "配价：“等”的宾语应是可以等来的事，“笑容”不能作为“等”的对象。"}], "explanations": {"消息": "正确。“消息”指报道或通知，可以被“他们一直在等”。", "操场": "语义：“等”的对象应是可以等来的消息或通知，“操场”不是可等待的信息。", "石头": "语义：石头不是可以被“等”来的事物，与“等学校的”语境不符。", "笑容": "配价：“等”的宾语应是可以等来的事，“笑容”不能作为“等”的对象。"}, "sentence_index": 6, "correct_answer": "消息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得了一场消息。", "explanation": "这里应该用〈病〉。“得”后接的是疾病，消息指报道或通知，不能表示患病。"}, {"text": "我把这个消息放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“放进冰箱”针对食物、饮料等实物，消息指报道或通知，不能放进冰箱。"}, {"text": "这个消息很甜，我想吃一口。", "explanation": "这里应该用〈蛋糕〉。“甜”和“吃一口”针对食物，消息指报道或通知，不能用来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的这只消息让全家都很担心。", "corrected_sentence": "今天的这条消息让全家都很担心。", "error_description": "量词错误：“消息”应搭配量词“条”，“只”多用于动物，不能用于消息。正确的说法是“今天的这条消息让全家都很担心。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天一直没吃消息。", "corrected_sentence": "这几天一直没有消息。", "error_description": "搭配错误：“消息”不能与“吃”搭配；此处应说“没有消息”。正确的说法是“这几天一直没有消息。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
