INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86657, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内人是丈夫对别人说自己妻子时用的称呼。", "primary_collocate": null, "pronunciation": "nèi rén", "ipa": "nei˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这位是我的内人，她姓王。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内人今天身体不好，没有来。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生笑着说：“内人做的菜很好吃。”", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和内人在北京住了十年。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内人喜欢花，家里种了很多。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请您放心，这件事我回去和内人说。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向客人介绍说：“这是内人。”", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内人在医院工作，每天很忙。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我陪内人去买了一件新衣服。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内人让我问你好。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "丈夫对外人称自己的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86657, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：内人，丈夫对外人称自己的妻子。"}, {"text": "累人", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），累人意思是令人劳累，不是内人。"}, {"text": "腻人", "is_correct": false, "explanation": "nì 与 nèi 韵母不同（i 与 ei），腻人意思是油腻得让人不舒服。"}, {"text": "媚人", "is_correct": false, "explanation": "mèi 与 nèi 声母不同（m 与 n），媚人意思是讨人喜欢。"}, {"text": "泪人", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），泪人指哭得很厉害的人。"}], "explanations": {"内人": "正确：内人，丈夫对外人称自己的妻子。", "累人": "lèi 与 nèi 声母不同（l 与 n），累人意思是令人劳累，不是内人。", "腻人": "nì 与 nèi 韵母不同（i 与 ei），腻人意思是油腻得让人不舒服。", "媚人": "mèi 与 nèi 声母不同（m 与 n），媚人意思是讨人喜欢。", "泪人": "lèi 与 nèi 声母不同（l 与 n），泪人指哭得很厉害的人。"}, "sentence_index": null, "correct_answer": "内人"}, "level_3": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：“内人”指丈夫称自己的妻子，符合“这位是我的……她姓王”的语境。"}, {"text": "男人", "is_correct": false, "explanation": "语义：男人指男性，与后文用“她”指称对方相矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“这位”用于称人，不能用来指小猫。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“这位”用于称人，公司不能用“这位”指代，且与“她姓王”矛盾。"}], "explanations": {"内人": "正确：“内人”指丈夫称自己的妻子，符合“这位是我的……她姓王”的语境。", "男人": "语义：男人指男性，与后文用“她”指称对方相矛盾。", "小猫": "搭配：“这位”用于称人，不能用来指小猫。", "公司": "搭配：“这位”用于称人，公司不能用“这位”指代，且与“她姓王”矛盾。"}, "sentence_index": 0, "correct_answer": "内人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "内人，请你把门关上。", "explanation": "这里应该用〈老婆〉。内人只用于丈夫向外人提及自己的妻子，当面称呼妻子应用〈老婆〉，不能用“内人”。"}, {"text": "屋里有几个内人在聊天。", "explanation": "这里应该用〈人〉。内人只指丈夫称自己的妻子，不能泛指屋里的人。"}, {"text": "我是他的内人，今天回娘家了。", "explanation": "这里应该用〈妻子〉。内人是丈夫称自己妻子的说法，妻子不能用它称呼自己，应说“我是他的妻子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86657, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：内人，丈夫对外人称自己的妻子。"}, {"text": "雷人", "is_correct": false, "explanation": "léi 与 nèi 声母不同（l 与 n），声调也不同；雷人意思是让人震惊。"}, {"text": "能人", "is_correct": false, "explanation": "néng 与 nèi 韵母不同（eng 与 ei）；能人指有本领的人。"}, {"text": "恼人", "is_correct": false, "explanation": "nǎo 与 nèi 韵母不同（ao 与 ei）；恼人意思是让人烦恼。"}, {"text": "内容", "is_correct": false, "explanation": "róng 与 rén 韵母不同（ong 与 en）；内容指事物里面包含的东西。"}], "explanations": {"内人": "正确：内人，丈夫对外人称自己的妻子。", "雷人": "léi 与 nèi 声母不同（l 与 n），声调也不同；雷人意思是让人震惊。", "能人": "néng 与 nèi 韵母不同（eng 与 ei）；能人指有本领的人。", "恼人": "nǎo 与 nèi 韵母不同（ao 与 ei）；恼人意思是让人烦恼。", "内容": "róng 与 rén 韵母不同（ong 与 en）；内容指事物里面包含的东西。"}, "sentence_index": null, "correct_answer": "内人"}, "level_3": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：“内人”是介绍自己妻子的称呼，符合“这是……”的语境。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是贬义身份，不能在向客人介绍时这样称呼。"}, {"text": "花瓶", "is_correct": false, "explanation": "配价：“介绍”的对象应是人，花瓶不能作为被介绍的人。"}, {"text": "罪犯", "is_correct": false, "explanation": "语义：罪犯是贬义身份，与友好介绍的语境不符。"}], "explanations": {"内人": "正确：“内人”是介绍自己妻子的称呼，符合“这是……”的语境。", "小偷": "语义：小偷是贬义身份，不能在向客人介绍时这样称呼。", "花瓶": "配价：“介绍”的对象应是人，花瓶不能作为被介绍的人。", "罪犯": "语义：罪犯是贬义身份，与友好介绍的语境不符。"}, "sentence_index": 6, "correct_answer": "内人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "张先生的内人让我问你好。", "explanation": "这里应该用〈夫人〉。内人是丈夫对外人称自己妻子的谦称，称别人的妻子应用〈夫人〉。"}, {"text": "这位先生是我的内人，他很会做饭。", "explanation": "这里应该用〈丈夫〉。内人指妻子，只能用于女性，不能指男性；说自己的男性配偶应用〈丈夫〉。"}, {"text": "我的内人刚上小学。", "explanation": "这里应该用〈孩子〉。内人指成年的妻子，不能指小孩子；说自家的小孩应用〈孩子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他和一只内人一起吃饭。", "corrected_sentence": "他和内人一起吃饭。", "error_description": "量词错误：内人指人，不能用量词“只”。应删去“一只”，直接说“他和内人一起吃饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃了内人做菜。", "corrected_sentence": "我吃了内人做的菜。", "error_description": "定语缺少“的”：“内人做的”修饰“菜”，定语与中心语之间要用“的”，应说“内人做的菜”，不能说“内人做菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
