INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时对人称自己的妻子。", "primary_collocate": null, "pronunciation": "nèi rén", "ipa": "nei˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "老先生对客人说，内人在后院做饭。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来访时，他起身说：“内人去买菜了，请稍坐。”", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请朋友来家里，让内人准备了茶。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内人不识字，但是很会过日子。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "掌柜说：“内人已经睡了，请明天再来。”", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教书先生带着内人回了老家。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生对客人说：“请进屋，内人在里面等着。”", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过很多地方，内人一直跟着他。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生说，内人做的点心很有名。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走后，他对内人说了这件事。", "target_word": "内人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "旧时对人自称妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：内人，旧时丈夫对人称自己的妻子。"}, {"text": "累人", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），累人意思是令人劳累，不是内人。"}, {"text": "腻人", "is_correct": false, "explanation": "nì 与 nèi 韵母不同（i 与 ei），腻人意思是油腻得让人不舒服。"}, {"text": "媚人", "is_correct": false, "explanation": "mèi 与 nèi 声母不同（m 与 n），媚人意思是讨人喜欢。"}, {"text": "泪人", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），泪人指哭得很厉害的人。"}], "explanations": {"内人": "正确：内人，旧时丈夫对人称自己的妻子。", "累人": "lèi 与 nèi 声母不同（l 与 n），累人意思是令人劳累，不是内人。", "腻人": "nì 与 nèi 韵母不同（i 与 ei），腻人意思是油腻得让人不舒服。", "媚人": "mèi 与 nèi 声母不同（m 与 n），媚人意思是讨人喜欢。", "泪人": "lèi 与 nèi 声母不同（l 与 n），泪人指哭得很厉害的人。"}, "sentence_index": null, "correct_answer": "内人"}, "level_3": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：“内人”指旧时丈夫称自己的妻子，符合“老先生对客人说”的语境。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会做饭，与“在后院做饭”的施事不符。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不会做饭，此处的施事必须是人。"}, {"text": "大树", "is_correct": false, "explanation": "搭配：“做饭”的主语须是人，大树不能与之搭配。"}], "explanations": {"内人": "正确：“内人”指旧时丈夫称自己的妻子，符合“老先生对客人说”的语境。", "花": "语义：花不会做饭，与“在后院做饭”的施事不符。", "狗": "语义：狗不会做饭，此处的施事必须是人。", "大树": "搭配：“做饭”的主语须是人，大树不能与之搭配。"}, "sentence_index": 0, "correct_answer": "内人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "李老爷的内人在里面等着。", "explanation": "这里应该用〈夫人〉。内人是丈夫称自己妻子的旧式谦称，称别人的妻子应用〈夫人〉。"}, {"text": "内人，你过来坐。", "explanation": "这里应该用〈娘子〉。内人只用于向外人提及自己的妻子，当面称呼妻子应用〈娘子〉，不能用“内人”。"}, {"text": "我是他的内人，今天回娘家了。", "explanation": "这里应该用〈妻子〉。内人是男子称自己妻子的说法，妻子不能用它称呼自己，应说“我是他的妻子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86658, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：内人，旧时丈夫对人称自己的妻子。"}, {"text": "雷人", "is_correct": false, "explanation": "léi 与 nèi 声母不同（l 与 n），声调也不同；雷人意思是让人震惊。"}, {"text": "能人", "is_correct": false, "explanation": "néng 与 nèi 韵母不同（eng 与 ei）；能人指有本领的人。"}, {"text": "恼人", "is_correct": false, "explanation": "nǎo 与 nèi 韵母不同（ao 与 ei）；恼人意思是让人烦恼。"}, {"text": "内容", "is_correct": false, "explanation": "róng 与 rén 韵母不同（ong 与 en）；内容指事物里面包含的东西。"}], "explanations": {"内人": "正确：内人，旧时丈夫对人称自己的妻子。", "雷人": "léi 与 nèi 声母不同（l 与 n），声调也不同；雷人意思是让人震惊。", "能人": "néng 与 nèi 韵母不同（eng 与 ei）；能人指有本领的人。", "恼人": "nǎo 与 nèi 韵母不同（ao 与 ei）；恼人意思是让人烦恼。", "内容": "róng 与 rén 韵母不同（ong 与 en）；内容指事物里面包含的东西。"}, "sentence_index": null, "correct_answer": "内人"}, "level_3": {"options": [{"text": "内人", "is_correct": true, "explanation": "正确：老先生向客人提到自己的妻子，用“内人”，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会等人，此处的主语应是有生命的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意识，不能“等着”。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“等着”要求有生命的主语，窗户不能充当。"}], "explanations": {"内人": "正确：老先生向客人提到自己的妻子，用“内人”，符合语境。", "桌子": "语义：桌子不会等人，此处的主语应是有生命的人。", "石头": "语义：石头没有意识，不能“等着”。", "窗户": "配价：“等着”要求有生命的主语，窗户不能充当。"}, "sentence_index": 6, "correct_answer": "内人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里站着几个内人。", "explanation": "这里应该用〈人〉。内人只指妻子，泛指院子里站着的人要用〈人〉。"}, {"text": "那位老爷是我的内人，常在外头做事。", "explanation": "这里应该用〈丈夫〉。内人指妻子，不能用来指男性老爷；说男性配偶应用〈丈夫〉。"}, {"text": "这本书是我的内人。", "explanation": "这里不这么用。内人指人，专指妻子，不能用来称物品；指物品应用〈物件〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老先生说，一只内人已经做好饭了。", "corrected_sentence": "老先生说，内人已经做好饭了。", "error_description": "量词错误：内人指人，不能用量词“只”。应删去“一只”，直接说“内人已经做好饭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喝了内人泡茶。", "corrected_sentence": "我喝了内人泡的茶。", "error_description": "定语缺少“的”：“内人泡的”修饰“茶”，应说“内人泡的茶”，不能说“内人泡茶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "然而是说，后面的话和前面的不一样。", "primary_collocate": null, "pronunciation": "rán ér", "ipa": "ɻan˧˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他很努力，然而成绩还是不好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，然而他只穿了一件衣服。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了很久，然而他没有来。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不难，然而做好不容易。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想去，然而家里有事。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不远，然而走起来很累。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都以为会下雨，然而天一直很好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很好，然而做得不太好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意了，然而他还是不愿意。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很小，然而客人特别多。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "转折连词，后句与前句意思不同或相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447d43e2-a23d-48e8-8047-2c5e16313adc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折，引出与「很努力」相反的结果：成绩还是不好。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，与后句「还是不好」的转折意思矛盾。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，「很努力」不能作为「成绩不好」的原因。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进补充，与「成绩还是不好」的转折语气不合。"}], "explanations": {"然而": "「然而」表示转折，引出与「很努力」相反的结果：成绩还是不好。", "所以": "语义：「所以」表示因果，与后句「还是不好」的转折意思矛盾。", "因为": "语义：「因为」引出原因，「很努力」不能作为「成绩不好」的原因。", "而且": "语义：「而且」表示递进补充，与「成绩还是不好」的转折语气不合。"}, "sentence_index": 0, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不仅聪明，然而很努力。", "explanation": "这里应该用〈而且〉。「不仅……而且……」表示递进，「然而」表示转折，不能与「不仅」配合。"}, {"text": "他打开门，然而看见了老师。", "explanation": "这里应该用〈于是〉。「然而」表示转折，这里前后是先后相继的动作，应用「于是」。"}, {"text": "天下雨了，然而比赛取消了。", "explanation": "这里应该用〈因此〉。「然而」表示转折，下雨和取消比赛是因果关系，应用「因此」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折：以为会下雨，结果天一直很好，前后正好相反。"}, {"text": "况且", "is_correct": false, "explanation": "语义：「况且」表示递进补充，与「以为会下雨」之后的转折不合。"}, {"text": "故此", "is_correct": false, "explanation": "语域：「故此」偏文言；语义：表示因果，与「以为会下雨」的落空语境不合。"}, {"text": "不然", "is_correct": false, "explanation": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}], "explanations": {"然而": "「然而」表示转折：以为会下雨，结果天一直很好，前后正好相反。", "况且": "语义：「况且」表示递进补充，与「以为会下雨」之后的转折不合。", "故此": "语域：「故此」偏文言；语义：表示因果，与「以为会下雨」的落空语境不合。", "不然": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}, "sentence_index": 6, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说的就是那本书，然而是我昨天买的那本。", "explanation": "这里应该用〈也就是〉。「然而」表示转折，这里是对前面内容的解释说明，应用「也就是」。"}, {"text": "他饿了，然而去厨房做饭。", "explanation": "这里应该用〈于是〉。「然而」表示转折，这里是饿了之后接着去做饭，前后是顺承关系，没有相反的内容，应用「于是」。"}, {"text": "他每天都来图书馆，然而他很努力。", "explanation": "这里应该用〈可见〉。「然而」引出相反的内容，这里是由行为推出结论，应用「可见」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都练习，不然而比赛时还是紧张。", "corrected_sentence": "他每天都练习，然而比赛时还是紧张。", "error_description": "「不」不能加在「然而」前，「然而」是转折连词，前面不能加否定词；「不然」是另一个词，不能与「而」拼接。正确说法是「他每天都练习，然而比赛时还是紧张。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都很累，但是然而大家还在工作。", "corrected_sentence": "我们都很累，然而大家还在工作。", "error_description": "「但是」和「然而」都表示转折，不能叠用，只用其中一个。正确说法是「我们都很累，然而大家还在工作。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d8d709d-8893-4526-ad0d-58ba7440430d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
