INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动力是让东西动起来的力量。", "primary_collocate": null, "pronunciation": "dòng lì", "ipa": "tʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车的动力很大。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电动车用电作为动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风给小船提供了动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的动力来自电。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这艘船用太阳能做动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车没有动力，就走不了。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水车靠水的动力转动。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆卡车动力足，能爬很陡的山。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的动力来自发动机。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机给汽车提供动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "原动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词；让机器、车船等运转的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：让机器、车辆运转的力量，是正确答案。"}, {"text": "冻梨", "is_correct": false, "explanation": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。"}, {"text": "冬梨", "is_correct": false, "explanation": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。"}, {"text": "懂礼", "is_correct": false, "explanation": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}], "explanations": {"动力": "动力（dòng lì）：让机器、车辆运转的力量，是正确答案。", "冻梨": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。", "冬梨": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。", "懂礼": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：车的运转力量，说“动力很大”符合车辆的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不说大小，与“很大”的搭配不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不用“大”来形容，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格通常说“高”或“低”，不说“很大”。"}], "explanations": {"动力": "动力：车的运转力量，说“动力很大”符合车辆的语境。", "颜色": "语义：颜色不说大小，与“很大”的搭配不合。", "名字": "语义：名字不用“大”来形容，句意不通。", "价格": "搭配：价格通常说“高”或“低”，不说“很大”。"}, "sentence_index": 0, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的动力很快，两秒就能加速到一百公里。", "explanation": "这里应该用〈速度〉。动力指使机器运转的力量，不说快慢；快慢要用“速度”。"}, {"text": "这辆车的动力有五米长，停车很不方便。", "explanation": "这里应该用〈车身〉。动力指使机器运转的力量，没有长短；说长度要用“车身”。"}, {"text": "这台机器的动力很香，闻起来很舒服。", "explanation": "这里应该用〈气味〉。动力指使机器运转的力量，没有香与不香之分，“香”描述的是气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：让机器运转的力量，是正确答案。"}, {"text": "重力", "is_correct": false, "explanation": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。"}, {"text": "洞里", "is_correct": false, "explanation": "洞里（dòng lǐ）第一个音节与“动力”相同，第二个音节声调不同，意思是洞的里面。"}, {"text": "通力", "is_correct": false, "explanation": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}], "explanations": {"动力": "动力（dòng lì）：让机器运转的力量，是正确答案。", "重力": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。", "洞里": "洞里（dòng lǐ）第一个音节与“动力”相同，第二个音节声调不同，意思是洞的里面。", "通力": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：水车转动的力量来自水的动力，与句意相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能推动水车转动，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，与水车的转动无关。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“靠……的尺寸”不成立，尺寸不能作为转动的动力来源。"}], "explanations": {"动力": "动力：水车转动的力量来自水的动力，与句意相合。", "味道": "语义：味道不能推动水车转动，句意不通。", "墨水": "语义：墨水是书写用的液体，与水车的转动无关。", "尺寸": "搭配：“靠……的尺寸”不成立，尺寸不能作为转动的动力来源。"}, "sentence_index": 6, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的动力很多，能做很多事。", "explanation": "这里应该用〈功能〉。功能可以多少，动力是运转的力量，不说多少。"}, {"text": "这辆车的动力很漂亮，远看很有气势。", "explanation": "这里应该用〈外观〉。动力指运转的力量，不指外形美观。"}, {"text": "这辆车的动力是鲜艳的红色，远看很醒目。", "explanation": "这里应该用〈颜色〉。动力没有鲜艳与否的属性，颜色才有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款车的动力足很，爬坡很轻松。", "corrected_sentence": "这款车的动力很足，爬坡很轻松。", "error_description": "位置错误：“很”应放在“足”前面，说“很足”，不说“足很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个电池能给电车提供一只动力。", "corrected_sentence": "这个电池能给电车提供一股动力。", "error_description": "量词错误：“动力”是一股股的力，应用量词“股”，不能用“只”。应说“提供一股动力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "阻力：与“动力”构成反义，指阻碍前进的力量，词典中有此对应。"}, {"text": "方向", "is_correct": false, "explanation": "方向：表示朝向，与“动力”的任何义项都没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "时间：表示时段，与“动力”没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色：表示色彩属性，与“动力”没有反义关系。"}], "correct_answer": "阻力", "explanations": {"阻力": "阻力：与“动力”构成反义，指阻碍前进的力量，词典中有此对应。", "方向": "方向：表示朝向，与“动力”的任何义项都没有反义关系。", "时间": "时间：表示时段，与“动力”没有反义关系。", "颜色": "颜色：表示色彩属性，与“动力”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "阻力：与“动力”构成反义，指阻碍前进的力量，词典中有此对应。"}, {"text": "距离", "is_correct": false, "explanation": "距离：表示两点之间的间隔，与“动力”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度：表示冷热程度，与“动力”没有反义关系。"}, {"text": "形状", "is_correct": false, "explanation": "形状：表示外形，与“动力”没有反义关系。"}], "correct_answer": "阻力", "explanations": {"阻力": "阻力：与“动力”构成反义，指阻碍前进的力量，词典中有此对应。", "距离": "距离：表示两点之间的间隔，与“动力”没有反义关系。", "温度": "温度：表示冷热程度，与“动力”没有反义关系。", "形状": "形状：表示外形，与“动力”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "推动人或事物前进、发展的力量。", "primary_collocate": null, "pronunciation": "dòng lì", "ipa": "tʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "学习的动力来自兴趣。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作很有动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话给了我很大的动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有动力，就很难坚持下去。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梦想是他前进的动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家人的支持是我最大的动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛失败以后，他失去了练习的动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好成绩给孩子带来了学习的动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展需要新的动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到自己的进步，是我继续跑步的动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词；推动人或事物前进的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：推动事物前进的力量，是正确答案。"}, {"text": "冻梨", "is_correct": false, "explanation": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。"}, {"text": "冬梨", "is_correct": false, "explanation": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。"}, {"text": "懂礼", "is_correct": false, "explanation": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}], "explanations": {"动力": "动力（dòng lì）：推动事物前进的力量，是正确答案。", "冻梨": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。", "冬梨": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。", "懂礼": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：推动学习前进的力量，与“来自兴趣”的句意相合。"}, {"text": "压力", "is_correct": false, "explanation": "语义：压力是负担，不是来自兴趣的正向力量，与“兴趣”的语境相反。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不会“来自兴趣”，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“来自”不搭配“时间”，兴趣不会产生时间。"}], "explanations": {"动力": "动力：推动学习前进的力量，与“来自兴趣”的句意相合。", "压力": "语义：压力是负担，不是来自兴趣的正向力量，与“兴趣”的语境相反。", "作业": "语义：作业是学习任务，不会“来自兴趣”，句意不通。", "时间": "搭配：“来自”不搭配“时间”，兴趣不会产生时间。"}, "sentence_index": 0, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这样做的动力很纯正。", "explanation": "这里应该用〈动机〉。“纯正”形容出发点，动机才有纯正与否之分；动力指推动前进的力量，不说纯正。"}, {"text": "他的动力很大，一口气扛起了两袋大米。", "explanation": "这里应该用〈力气〉。动力指推动前进的力量，扛东西靠的是力气，不说动力大。"}, {"text": "他对这个女孩的动力很深。", "explanation": "这里应该用〈感情〉。动力指推动力，不指情感，“深”形容的是感情，不说动力深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：推动事物前进的力量，是正确答案。"}, {"text": "重力", "is_correct": false, "explanation": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。"}, {"text": "洞里", "is_correct": false, "explanation": "洞里（dòng lǐ）第一个音节与“动力”相同，第二个音节声调不同，意思是洞的里面。"}, {"text": "通力", "is_correct": false, "explanation": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}], "explanations": {"动力": "动力（dòng lì）：推动事物前进的力量，是正确答案。", "重力": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。", "洞里": "洞里（dòng lǐ）第一个音节与“动力”相同，第二个音节声调不同，意思是洞的里面。", "通力": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：练习的推动力，失去后就没有练习的意愿，与句意相合。"}, {"text": "名次", "is_correct": false, "explanation": "语义：名次是比赛结果，练习不能“失去”名次，句意不通。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是比赛的奖励，失败之后不谈“失去练习的奖杯”。"}, {"text": "战术", "is_correct": false, "explanation": "搭配：“练习的战术”不成立，练习的对象不是战术。"}], "explanations": {"动力": "动力：练习的推动力，失去后就没有练习的意愿，与句意相合。", "名次": "语义：名次是比赛结果，练习不能“失去”名次，句意不通。", "奖杯": "语义：奖杯是比赛的奖励，失败之后不谈“失去练习的奖杯”。", "战术": "搭配：“练习的战术”不成立，练习的对象不是战术。"}, "sentence_index": 6, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天跑步，动力很快。", "explanation": "这里应该用〈速度〉。动力指推动力，跑步的快慢要用“速度”，不能说动力快。"}, {"text": "他做了一个漂亮的动力，把球踢进了球门。", "explanation": "这里应该用〈动作〉。动力指推动力，不指身体的动作。"}, {"text": "他下定动力要戒烟。", "explanation": "这里应该用〈决心〉。“下定”只能搭配“决心”，动力不能被“下定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划让他的动力足很。", "corrected_sentence": "这个计划让他的动力很足。", "error_description": "位置错误：“很”应放在形容词“足”前面，说“很足”，不说“足很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里有一条动力，想把这件事做好。", "corrected_sentence": "他心里有一股动力，想把这件事做好。", "error_description": "量词错误：“动力”应搭配量词“股”，说“一股动力”，不能说“一条动力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
