INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86663, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看看是看一下，不用看很久。", "primary_collocate": null, "pronunciation": "kàn kan", "ipa": "kʰan˥˩ kʰan", "syllable_count": 2, "sentences": [{"text": "你把照片给我，我想看看。", "target_word": "看看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很漂亮，我可以看看吗？", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不买东西，只是在商店里看看。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走进教室，四处看看。", "target_word": "看看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈，你来看看我画的画。", "target_word": "看看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说：“让我看看你的手。”", "target_word": "看看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我去朋友家看看他的新房子。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机多少钱？我先看看。", "target_word": "看看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外有人在叫，我走过去看看。", "target_word": "看看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，你帮我看看我写的字，好吗？", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看一看", "label": "重叠"}, {"form": "看了看", "label": "体标"}], "register": "口语", "sense_fingerprint": "随便看一下，时间很短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看看", "is_correct": true, "explanation": "「看看」表示随便看一下，与「我想」搭配，表示想看一眼照片。"}, {"text": "拿走", "is_correct": false, "explanation": "语义：「拿走」是带离，与前一句「给我」的方向相反。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：「撕掉」会毁掉照片，与「我想」看的愿望相矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「吃掉」是把东西放进嘴里咽下，用在照片上句意荒谬，与「我想」看的意思不合。"}], "explanations": {"看看": "「看看」表示随便看一下，与「我想」搭配，表示想看一眼照片。", "拿走": "语义：「拿走」是带离，与前一句「给我」的方向相反。", "撕掉": "语义：「撕掉」会毁掉照片，与「我想」看的愿望相矛盾。", "吃掉": "语义：「吃掉」是把东西放进嘴里咽下，用在照片上句意荒谬，与「我想」看的意思不合。"}, "sentence_index": 0, "correct_answer": "看看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他花了三年看看这个问题，还是没有结论。", "explanation": "这里应该用〈研究〉。「看看」只表示短时间随便看一下，不能用于持续三年的深入钻研。"}, {"text": "他在诊所里看看病人，一看就是一整天。", "explanation": "这里应该用〈诊治〉。「看看」只表示短暂随便看一下，不能用于持续一整天的诊治。"}, {"text": "这台摄像头二十四小时不停地看看门口的动静。", "explanation": "这里应该用〈监视〉。「看看」只表示短暂随便看一下，不能用于二十四小时持续盯着的情形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看看", "is_correct": true, "explanation": "「看看」表示随便看一下，符合去朋友家串门、顺便看房子的语境。"}, {"text": "买", "is_correct": false, "explanation": "语义：「买」的对象是房子，串门时不能说去买朋友的房子。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」会毁坏房子，与去朋友家做客的语境冲突。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：「瞻仰」是书面语，专指敬仰地看伟人或遗迹，不适合朋友家的口语场合。"}], "explanations": {"看看": "「看看」表示随便看一下，符合去朋友家串门、顺便看房子的语境。", "买": "语义：「买」的对象是房子，串门时不能说去买朋友的房子。", "拆": "语义：「拆」会毁坏房子，与去朋友家做客的语境冲突。", "瞻仰": "语域：「瞻仰」是书面语，专指敬仰地看伟人或遗迹，不适合朋友家的口语场合。"}, "sentence_index": 6, "correct_answer": "看看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两名警察在门口看看犯人，不让他离开。", "explanation": "这里应该用〈看守〉。「看看」只表示短时间随便看一下，不能用于持续盯着、不让人离开的情形。"}, {"text": "他用手看看铁块的温度，判断它烫不烫。", "explanation": "这里应该用〈摸〉。「看看」是用眼睛短暂地看，不能用来表示用手去感受温度。"}, {"text": "我在门外看看隔壁传来的歌声。", "explanation": "这里应该用〈听〉。「看看」是用眼睛短暂地看，不能用来表示听到声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买东西前看看了价格。", "corrected_sentence": "我买东西前看了看价格。", "error_description": "「看看」是重叠式，后面不能再加「了」；应说「看了看」，「了」放在第一个「看」之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服很好，我可以看看一下吗？", "corrected_sentence": "这件衣服很好，我可以看一下吗？", "error_description": "「看看」与「一下」重复，只能说「看看」或「看一下」，二者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
