INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "先试一试，再看结果怎么样。", "primary_collocate": null, "pronunciation": "kàn kan", "ipa": "kʰan˥˩ kʰan", "syllable_count": 2, "sentences": [{"text": "你先试试这个办法，看看有没有用。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们等一下，看看他会不会来。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汤好了吗？我尝一口，看看咸不咸。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路能不能走？我们开车去看看。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，我去问问，看看怎么办。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋我没穿过，穿上看看合不合适。", "target_word": "看看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你按一下这个按钮，看看能不能开。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天天气好不好？我们看看再说。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想看看自己能不能跑完五公里。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们换一个方法做，看看结果怎么样。", "target_word": "看看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看一看", "label": "重叠"}, {"form": "看了看", "label": "体标"}], "register": "口语", "sense_fingerprint": "先试一试，再知道结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 4 words above tier T1 (max 2): 好了吗 (Zipf 3.53), 尝 (Zipf 3.91), 咸 (Zipf 3.83), 咸 (Zipf 3.83)']::text[], '4a744252-944c-4823-975b-653cb7946893') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看看", "is_correct": true, "explanation": "「看看」表示试一试、看结果，与前句「先试试」相连。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：「放弃」需要带宾语，这里后面直接接「有没有用」，缺少宾语。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与前句「先试试」的尝试意思相反，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」表示不接受，与「试一试」的意愿冲突。"}], "explanations": {"看看": "「看看」表示试一试、看结果，与前句「先试试」相连。", "放弃": "配价：「放弃」需要带宾语，这里后面直接接「有没有用」，缺少宾语。", "忘记": "语义：「忘记」与前句「先试试」的尝试意思相反，句意不通。", "拒绝": "语义：「拒绝」表示不接受，与「试一试」的意愿冲突。"}, "sentence_index": 0, "correct_answer": "看看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新药要经过多次看看才能上市。", "explanation": "这里应该用〈检验〉。「看看」只是随便试一下，不能指正式、大规模的药品检验。"}, {"text": "厨师用舌头看看汤的咸淡。", "explanation": "这里应该用〈尝〉。「看看」只表示用眼睛或短暂地看一下，不能指用舌头品尝味道。"}, {"text": "他每天要看看这份文件十个小时。", "explanation": "这里应该用〈研读〉。「看看」只表示短暂地看一下，不能用来表示长时间、深入地钻研文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看看", "is_correct": true, "explanation": "「看看」表示试一试、看结果，前面「按一下」是尝试，后面「能不能开」是要知道的结果。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：「扔掉」后面不能接「能不能开」，句意不通。"}, {"text": "卖掉", "is_correct": false, "explanation": "语义：「卖掉」与试按钮、看结果无关，后面接「能不能开」不通。"}, {"text": "修好", "is_correct": false, "explanation": "语义：「修好」表示结果已经完成，不能再接「能不能开」的疑问。"}], "explanations": {"看看": "「看看」表示试一试、看结果，前面「按一下」是尝试，后面「能不能开」是要知道的结果。", "扔掉": "语义：「扔掉」后面不能接「能不能开」，句意不通。", "卖掉": "语义：「卖掉」与试按钮、看结果无关，后面接「能不能开」不通。", "修好": "语义：「修好」表示结果已经完成，不能再接「能不能开」的疑问。"}, "sentence_index": 6, "correct_answer": "看看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在房间里闻见饭菜的香味，然后看看香味。", "explanation": "这里应该用〈嗅〉。「看看」是用眼睛短暂地看，不能用来表示用鼻子辨别气味。"}, {"text": "他用手看看热水的温度，判断水烫不烫。", "explanation": "这里应该用〈摸〉。「看看」只表示用眼睛短暂地看，不能指用手去感受温度。"}, {"text": "他用脚看看地板平不平。", "explanation": "这里应该用〈踩〉。「看看」指用眼睛短暂地看，不能用脚去感受地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天我们开车去看看了，那条路能走。", "corrected_sentence": "昨天我们开车去看了看，那条路能走。", "error_description": "「看看」是重叠式，后面不能加「了」；应说「看了看」，「了」放在第一个「看」之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想看看一下这个办法有没有用。", "corrected_sentence": "我想看一下这个办法有没有用。", "error_description": "「看看」与「一下」重复，应说「看一下这个办法」或「看看这个办法」，二者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262858ed-f0a0-453e-8984-7e483b83eda9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
