INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南边的地区。", "primary_collocate": null, "pronunciation": "nán bù", "ipa": "nan˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "南部地区这几天下了大雨。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部很冷，南部很暖和。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省的南部种了很多茶。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多游客想去云南南部玩。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部的天气比北部热。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在南部长大，不怕热。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部的路比北部的好走。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在南部有三个工厂。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，南部的雪比北部少。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部一年能种两次水稻。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "南边的地区，常与北部相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”指时间，不能与“地区”组成地点名词短语，“冬天地区”不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能作地区的名称，“椅子地区”不通。"}, {"text": "南部", "is_correct": true, "explanation": "“南部地区”指南边的地区，“南部”修饰“地区”，与句中语境相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是物品，不能作地区的名称。"}], "explanations": {"冬天": "语义：“冬天”指时间，不能与“地区”组成地点名词短语，“冬天地区”不通。", "椅子": "语义：“椅子”是家具，不能作地区的名称，“椅子地区”不通。", "南部": "“南部地区”指南边的地区，“南部”修饰“地区”，与句中语境相符。", "电脑": "语义：“电脑”是物品，不能作地区的名称。"}, "sentence_index": 0, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的南部烂了。", "explanation": "这里应该用〈南边〉。“南部”指地区，不指西瓜的一侧；西瓜的一侧要说“南边”。"}, {"text": "这道数学题的南部很难。", "explanation": "这里应该用〈难点〉。“南部”指地区的方位部分，不能指题目的一部分；题目里难的地方要说“难点”。"}, {"text": "他的南部很疼，所以去了医院。", "explanation": "这里应该用〈肚子〉。“南部”指地区的南面，不指人身上的部位；腹部疼要说“肚子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能指“……的路”的位置。"}, {"text": "西", "is_correct": false, "explanation": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的路”。"}, {"text": "南部", "is_correct": true, "explanation": "“南部”指南边的地区，可以修饰“路”，表示那一带的路。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能作地点修饰语，“手机的路”不通。"}], "explanations": {"香蕉": "语义：“香蕉”是水果，不能指“……的路”的位置。", "西": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的路”。", "南部": "“南部”指南边的地区，可以修饰“路”，表示那一带的路。", "手机": "语义：“手机”是物品，不能作地点修饰语，“手机的路”不通。"}, "sentence_index": 6, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的南部破了，我要买一本新的。", "explanation": "这里应该用〈一边〉。“南部”指地区的方位部分，不指物体的一侧；说书的一侧要用“一边”。"}, {"text": "这道菜的南部很辣，大家都喜欢。", "explanation": "这里应该用〈口味〉。“南部”指地区的方位部分，不用于菜；说菜的味道要用“口味”。"}, {"text": "这次比赛的南部很精彩，大家都很兴奋。", "explanation": "这里应该用〈下半场〉。“南部”指南边的地区，比赛没有方位；说比赛的后一部分要用“下半场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次大雨主要南部地区出现。", "corrected_sentence": "这次大雨主要在南部地区出现。", "error_description": "错误：漏了介词“在”。“南部地区”作处所要用“在”引出，应说“主要在南部地区出现”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他南部长大，所以不怕热。", "corrected_sentence": "他在南部长大，所以不怕热。", "error_description": "错误：漏了介词“在”。“南部”作处所要用“在”引出，应说“他在南部长大，所以不怕热。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
