INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86667, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考虑是在心里想一想，再决定怎么做。", "primary_collocate": null, "pronunciation": "kǎo lǜ", "ipa": "kʰau̯˨˩˦ ly˥˩", "syllable_count": 2, "sentences": [{"text": "这件事我要再考虑一下。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先考虑考虑，明天告诉我。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考虑了很久，还是没有答应。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子以前，要考虑价钱。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在考虑换一份工作。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定时，也要考虑别人的想法。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法我没有考虑过。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一点时间考虑。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的意见我会认真考虑的。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考虑得很周到。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考虑考虑", "label": "重叠"}, {"form": "考虑了", "label": "体标"}, {"form": "考虑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做决定前在心里想一想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清除污物，“这件事”不能被清洗。"}, {"text": "考虑", "is_correct": true, "explanation": "正确：“再考虑一下”表示稍作想一想再决定，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场所，不说“打扫这件事”。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”指花钱买东西，“这件事”不能被购买。"}], "explanations": {"洗": "语义：“洗”指用水清除污物，“这件事”不能被清洗。", "考虑": "正确：“再考虑一下”表示稍作想一想再决定，符合句意。", "打扫": "搭配：“打扫”的对象是房间、场所，不说“打扫这件事”。", "购买": "语义：“购买”指花钱买东西，“这件事”不能被购买。"}, "sentence_index": 0, "correct_answer": "考虑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用望远镜考虑月亮。", "explanation": "这里应该用〈观察〉。考虑表示在心里想一想再决定，不表示借助仪器观看。"}, {"text": "我每天都考虑你。", "explanation": "这里应该用〈想〉。考虑指思考后作决定，不能表示想念某人。"}, {"text": "他用眼睛考虑这幅画。", "explanation": "这里应该用〈欣赏〉。考虑表示想一想再决定，不表示用眼睛观赏作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“办法”作宾语。"}, {"text": "考虑", "is_correct": true, "explanation": "正确：“没有考虑过”表示从未想过这个办法，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服鞋帽，不说“穿办法”。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”指把水倒在物体上，与“办法”无关。"}], "explanations": {"游泳": "配价：“游泳”是不及物动词，不能带“办法”作宾语。", "考虑": "正确：“没有考虑过”表示从未想过这个办法，符合句意。", "穿": "搭配：“穿”的对象是衣服鞋帽，不说“穿办法”。", "浇": "语义：“浇”指把水倒在物体上，与“办法”无关。"}, "sentence_index": 6, "correct_answer": "考虑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把桌子考虑得很干净。", "explanation": "这里应该用〈擦〉。考虑表示想一想再决定，不能表示擦拭物体。"}, {"text": "周末我去医院考虑生病的奶奶。", "explanation": "这里应该用〈看望〉。考虑不能表示去探望人。"}, {"text": "她每天考虑钢琴。", "explanation": "这里应该用〈练习〉。考虑表示想一想，不能表示练习乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我考虑了过这件事。", "corrected_sentence": "我考虑过这件事。", "error_description": "错误在于“考虑”后同时加了“了”和“过”，两个体标不能并用；应改为“考虑过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没考虑了出国。", "corrected_sentence": "我从没考虑过出国。", "error_description": "体标错误：「从没」表示从未有过的经历，应用经历体「过」；「了」表示完成，与「从没」矛盾。应说「我从没考虑过出国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
