INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对事情反复思考，以便作出决定。", "primary_collocate": null, "pronunciation": "kǎo lǜ", "ipa": "kʰau̯˨˩˦ ly˥˩", "syllable_count": 2, "sentences": [{"text": "她反复考虑，最后决定出国学习。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，我考虑了一个晚上。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去不去北京，你考虑好了吗？", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在考虑要不要给我们加工资。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得考虑一下孩子上学的事。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没考虑清楚就走了。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前要考虑天气。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我考虑过很多次，还是想留下来。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以考虑我的建议。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在考虑新的计划。", "target_word": "考虑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考虑考虑", "label": "重叠"}, {"form": "考虑了", "label": "体标"}, {"form": "考虑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "为了决定而反复思考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与“反复……最后决定出国”的语境不合。"}, {"text": "考虑", "is_correct": true, "explanation": "正确：“反复考虑”表示多次想，然后做决定，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中运动，与“反复想一想再决定”的意思无关。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是器物，不说“修决定”。"}], "explanations": {"唱": "语义：“唱”指发声演唱，与“反复……最后决定出国”的语境不合。", "考虑": "正确：“反复考虑”表示多次想，然后做决定，符合句意。", "游泳": "语义：“游泳”指在水中运动，与“反复想一想再决定”的意思无关。", "修": "搭配：“修”的对象是器物，不说“修决定”。"}, "sentence_index": 0, "correct_answer": "考虑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天早上考虑教室。", "explanation": "这里应该用〈打扫〉。考虑不能表示清理场所。"}, {"text": "他在饭馆把饭考虑得很好吃。", "explanation": "这里应该用〈做〉。考虑表示想一想再决定，不表示做出饭菜，所以不能说饭“考虑得”好吃。"}, {"text": "他把这本书考虑成英文。", "explanation": "这里应该用〈翻译〉。考虑表示想一想再决定，不能表示语言转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，“天气”不能被喝。"}, {"text": "考虑", "is_correct": true, "explanation": "正确：“出门前要考虑天气”表示出门前想一想天气情况，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，天气不能修理。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”一般不带“天气”这样的宾语，句子不成立。"}], "explanations": {"喝": "语义：“喝”指饮用液体，“天气”不能被喝。", "考虑": "正确：“出门前要考虑天气”表示出门前想一想天气情况，符合句意。", "修理": "搭配：“修理”的对象是器物，天气不能修理。", "跳": "配价：“跳”一般不带“天气”这样的宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "考虑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在舞台上考虑钢琴。", "explanation": "这里应该用〈弹〉。考虑不能表示弹奏乐器。"}, {"text": "孩子们考虑牛奶。", "explanation": "这里应该用〈喝〉。考虑不能表示饮用。"}, {"text": "他在足球场考虑球。", "explanation": "这里应该用〈踢〉。考虑不能表示踢球的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们认真考虑了过这件事。", "corrected_sentence": "我们认真考虑过这件事。", "error_description": "错误在于“考虑”后同时加了“了”和“过”，两个体标不能并用；应改为“考虑过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我还在了考虑去不去。", "corrected_sentence": "明天我还在考虑去不去。", "error_description": "错误在于“在”后面的“考虑”前不能加“了”，进行态与“了”不能并用；应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身前往，与“与会”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是会上的活动，与“与会”不是反义词。"}, {"text": "结束", "is_correct": false, "explanation": "结束指事情或会议终止，与“与会”不是反义词。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。", "出发": "出发指动身前往，与“与会”没有反义关系。", "讨论": "讨论是会上的活动，与“与会”不是反义词。", "结束": "结束指事情或会议终止，与“与会”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。"}, {"text": "发言", "is_correct": false, "explanation": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。"}, {"text": "主持", "is_correct": false, "explanation": "主持指掌管会议的进行，与“与会”并不相反。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指出外游览，与“与会”没有反义关系。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。", "发言": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。", "主持": "主持指掌管会议的进行，与“与会”并不相反。", "旅行": "旅行指出外游览，与“与会”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "与会是去参加一个会。", "primary_collocate": null, "pronunciation": "yù huì", "ipa": "y˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我明天上午要与会，恐怕无法赴约。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事今天前往北京与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月都要与会，工作很忙。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您下午是否与会？", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会很重要，大家都要与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我与同事一同与会，乘地铁前往。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有时间与会，请别人去了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师正在与会，现在不能接电话。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天与会，会议持续了三个小时。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想与会，请你告诉我时间和地方。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与会者", "label": "复合"}, {"form": "与会人员", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词，指某人去参加某一次会，强调人到会场参加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yù huì）指去参加会。"}, {"text": "语汇", "is_correct": false, "explanation": "yǔ huì 与 yù huì 第一个音节声调不同（第三声与第四声），语汇指词汇，与会议无关。"}, {"text": "渔会", "is_correct": false, "explanation": "yú huì 与 yù huì 第一个音节声调不同（第二声与第四声），渔会指渔民的团体组织。"}, {"text": "余晖", "is_correct": false, "explanation": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}], "explanations": {"与会": "正确答案。与会（yù huì）指去参加会。", "语汇": "yǔ huì 与 yù huì 第一个音节声调不同（第三声与第四声），语汇指词汇，与会议无关。", "渔会": "yú huì 与 yù huì 第一个音节声调不同（第二声与第四声），渔会指渔民的团体组织。", "余晖": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示去参加会，与“明天上午要……”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与“明天上午要”的安排不符，句子不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不知去向，不能作为明天的安排，句子不通。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}], "explanations": {"与会": "正确答案。与会表示去参加会，与“明天上午要……”的语境相符。", "出生": "语义：“出生”指人降生，与“明天上午要”的安排不符，句子不通。", "失踪": "语义：“失踪”指人不知去向，不能作为明天的安排，句子不通。", "融化": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}, "sentence_index": 0, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天在河边与会了。", "explanation": "这里应该用〈散步〉。与会指去参加一个会，沿河走走要用散步。"}, {"text": "他傍晚在篮球场上与会。", "explanation": "这里应该用〈打球〉。与会指去参加一个会，打篮球要用打球。"}, {"text": "我们在教室里与会，听了一节课。", "explanation": "这里应该用〈旁听〉。与会指去参加一个会，听课要用旁听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yù huì）指去参加会。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ huì 与 yù huì 第一个音节读音不同（wǔ 与 yù），舞会指跳舞的聚会。"}, {"text": "误会", "is_correct": false, "explanation": "wù huì 与 yù huì 第一个音节声母不同（w 与 y），误会指理解错了别人的意思，与参加会议无关。"}, {"text": "意会", "is_correct": false, "explanation": "yì huì 与 yù huì 第一个音节韵母不同（i 与 ü），意会指不用明说而领会，与参加会议无关。"}], "explanations": {"与会": "正确答案。与会（yù huì）指去参加会。", "舞会": "wǔ huì 与 yù huì 第一个音节读音不同（wǔ 与 yù），舞会指跳舞的聚会。", "误会": "wù huì 与 yù huì 第一个音节声母不同（w 与 y），误会指理解错了别人的意思，与参加会议无关。", "意会": "yì huì 与 yù huì 第一个音节韵母不同（i 与 ü），意会指不用明说而领会，与参加会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示去参加会，与“没有时间……”的语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，不是能因“没有时间”而安排的事，句子不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指来得晚，与“请别人去了”的安排说不通。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}], "explanations": {"与会": "正确答案。与会表示去参加会，与“没有时间……”的语境相符。", "生病": "语义：“生病”指身体不适，不是能因“没有时间”而安排的事，句子不通。", "迟到": "语义：“迟到”指来得晚，与“请别人去了”的安排说不通。", "融化": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}, "sentence_index": 6, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网球比赛中与会。", "explanation": "这里应该用〈参赛〉。与会指去参加一个会，比赛要用参赛。"}, {"text": "他们中午在饭店玩扑克，都与会了。", "explanation": "这里应该用〈玩牌〉。与会指去参加一个会，玩扑克要用玩牌。"}, {"text": "我在项目组中与会。", "explanation": "这里应该用〈参与〉。与会指去参加一个会，参与项目要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天不与会。", "corrected_sentence": "我昨天没与会。", "error_description": "错误在否定词。叙述过去的事，否定要用“没”，应说“没与会”，不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下周想与会会议，请你提前通知我。", "corrected_sentence": "我下周想与会，请你提前通知我。", "error_description": "错误在“会议”。“与会”已含“参加会”的意思，后面不能再带“会议”作宾语，应说“想与会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。"}, {"text": "发言", "is_correct": false, "explanation": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身前往，与“与会”没有反义关系。"}, {"text": "结束", "is_correct": false, "explanation": "结束指事情或会议终止，与“与会”不是反义词。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。", "发言": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。", "出发": "出发指动身前往，与“与会”没有反义关系。", "结束": "结束指事情或会议终止，与“与会”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是会上的活动，与“与会”不是反义词。"}, {"text": "主持", "is_correct": false, "explanation": "主持指掌管会议的进行，与“与会”并不相反。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指出外游览，与“与会”没有反义关系。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。", "讨论": "讨论是会上的活动，与“与会”不是反义词。", "主持": "主持指掌管会议的进行，与“与会”并不相反。", "旅行": "旅行指出外游览，与“与会”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加会议。", "primary_collocate": null, "pronunciation": "yù huì", "ipa": "y˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天的会议，王经理将与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明天要出差，不能与会了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议有三十多位专家与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您下周三能与会吗？", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们都与会了，会议马上开始。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，没有与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的大部分员工都要与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长也来与会，大家都很高兴。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请与会的同事先在门口签名。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想与会，可是时间太晚了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与会者", "label": "复合"}, {"form": "与会人员", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词，指参加会议，多用于正式场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yù huì）指参加会议。"}, {"text": "语汇", "is_correct": false, "explanation": "yǔ huì 与 yù huì 第一个音节声调不同（第三声与第四声），语汇指词汇，与会议无关。"}, {"text": "渔会", "is_correct": false, "explanation": "yú huì 与 yù huì 第一个音节声调不同（第二声与第四声），渔会指渔民的团体组织。"}, {"text": "余晖", "is_correct": false, "explanation": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}], "explanations": {"与会": "正确答案。与会（yù huì）指参加会议。", "语汇": "yǔ huì 与 yù huì 第一个音节声调不同（第三声与第四声），语汇指词汇，与会议无关。", "渔会": "yú huì 与 yù huì 第一个音节声调不同（第二声与第四声），渔会指渔民的团体组织。", "余晖": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会是不及物动词，表示参加会议，可以直接用在句末。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“明天的会议”的安排相反，句子读来不合常理。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，与“明天的会议”无关，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与会议毫不相干，“明天的会议，王经理将结婚”意思不通。"}], "explanations": {"与会": "正确答案。与会是不及物动词，表示参加会议，可以直接用在句末。", "逃跑": "语义：“逃跑”与“明天的会议”的安排相反，句子读来不合常理。", "融化": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，与“明天的会议”无关，句子不通。", "结婚": "语义：“结婚”与会议毫不相干，“明天的会议，王经理将结婚”意思不通。"}, "sentence_index": 0, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天在婚礼上与会了。", "explanation": "这里应该用〈出席〉。与会指参加会议，婚礼这类仪式要用出席。"}, {"text": "我们在这个项目中与会。", "explanation": "这里应该用〈参与〉。与会指参加会议，参与项目要用参与。"}, {"text": "周末我们在游泳池与会。", "explanation": "这里应该用〈游泳〉。与会指参加会议，去泳池要用游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yù huì）指参加会议。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ huì 与 yù huì 第一个音节读音不同（wǔ 与 yù），舞会指跳舞的聚会。"}, {"text": "误会", "is_correct": false, "explanation": "wù huì 与 yù huì 第一个音节声母不同（w 与 y），误会指理解错了别人的意思，与参加会议无关。"}, {"text": "意会", "is_correct": false, "explanation": "yì huì 与 yù huì 第一个音节韵母不同（i 与 ü），意会指不用明说而领会，与参加会议无关。"}], "explanations": {"与会": "正确答案。与会（yù huì）指参加会议。", "舞会": "wǔ huì 与 yù huì 第一个音节读音不同（wǔ 与 yù），舞会指跳舞的聚会。", "误会": "wù huì 与 yù huì 第一个音节声母不同（w 与 y），误会指理解错了别人的意思，与参加会议无关。", "意会": "yì huì 与 yù huì 第一个音节韵母不同（i 与 ü），意会指不用明说而领会，与参加会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示参加会议，与“公司员工都要……”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与公司员工的工作安排不符，句子不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不知去向，与员工参加会议的要求相矛盾。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里裸用，句子不完整。"}], "explanations": {"与会": "正确答案。与会表示参加会议，与“公司员工都要……”的语境相符。", "出生": "语义：“出生”指人降生，与公司员工的工作安排不符，句子不通。", "失踪": "语义：“失踪”指人不知去向，与员工参加会议的要求相矛盾。", "举办": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里裸用，句子不完整。"}, "sentence_index": 6, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在篮球比赛中与会了。", "explanation": "这里应该用〈参赛〉。与会指参加会议，参加比赛要用参赛。"}, {"text": "他上课时在教室里与会。", "explanation": "这里应该用〈旁听〉。与会指参加会议，听课要用旁听。"}, {"text": "同学们晚上在饭店与会。", "explanation": "这里应该用〈聚会〉。与会指参加会议，同学聚餐要用聚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
