INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说说是说一说，不用说很多。", "primary_collocate": null, "pronunciation": "shuō shuo", "ipa": "ʂwo˥ ʂwo", "syllable_count": 2, "sentences": [{"text": "老师让我们说说各自的爱好。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你随便说说就行，不用太长。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是说说，你别当真。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先说说你昨天做了什么吧。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想简单地说说自己的情况。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理想先说说今天的安排。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你简单说说这本书讲了什么。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你就说说看，试试怎么样。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请他说说学汉语的经验。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有什么事，你快说说吧。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说一说", "label": "重叠"}, {"form": "说了说", "label": "体标"}, {"form": "说说看", "label": "复合"}], "register": "口语", "sense_fingerprint": "简单地说一说，不用说很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说说", "is_correct": true, "explanation": "说说是简单说一说，老师请大家说说各自的爱好，符合句意。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪是剪断，不能“剪”爱好。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，不能“煮”爱好。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是物品，不能说“买爱好”。"}], "explanations": {"说说": "说说是简单说一说，老师请大家说说各自的爱好，符合句意。", "剪": "语义：剪是剪断，不能“剪”爱好。", "煮": "语义：煮是烹饪，不能“煮”爱好。", "买": "搭配：“买”的对象是物品，不能说“买爱好”。"}, "sentence_index": 0, "correct_answer": "说说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在礼堂说说一场长篇演讲。", "explanation": "这里应该用〈发表〉。“说说”只是简单说一说，不能用于长篇演讲。"}, {"text": "老师说说一个小时的课。", "explanation": "这里应该用〈讲〉。“说说”只是简单说一说，不能用于持续一个小时的课。"}, {"text": "律师在法庭上说说案情，足足用了一整天。", "explanation": "这里应该用〈陈述〉。“说说”只是简单说一说，不能用来描述一整天的法庭陈述，应用〈陈述〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说说", "is_correct": true, "explanation": "说说是说一说，简单说说这本书的内容，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭，不能“擦”书的内容。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不能“扔”书讲了什么。"}, {"text": "捐", "is_correct": false, "explanation": "搭配：“捐”的对象是钱物，不能说“捐书讲了什么”。"}], "explanations": {"说说": "说说是说一说，简单说说这本书的内容，符合句意。", "擦": "语义：擦是擦拭，不能“擦”书的内容。", "扔": "语义：扔是丢弃，不能“扔”书讲了什么。", "捐": "搭配：“捐”的对象是钱物，不能说“捐书讲了什么”。"}, "sentence_index": 6, "correct_answer": "说说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向朋友说说心里的委屈，一聊就是整整一个晚上。", "explanation": "这里应该用〈倾诉〉。“说说”只是简单说一说，不能用于一聊就是整整一个晚上的长谈，应用〈倾诉〉。"}, {"text": "作者在书中系统说说自己的观点。", "explanation": "这里应该用〈阐述〉。“说说”语气随便，不能用来修饰“系统”这样完整、深入的表达，应用〈阐述〉。"}, {"text": "教育局正式说说考试成绩，并发布了官方通告。", "explanation": "这里应该用〈通报〉。“说说”语气随便，不能与“正式”“官方通告”搭配，应用〈通报〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想简单说说了看法。", "corrected_sentence": "我想简单说说看法。", "error_description": "体标错误：“说说”是重叠形式，后面不能直接加“了”。这里应去掉“了”，正确句是“我想简单说说看法。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你就说说了这次的情况吧。", "corrected_sentence": "你就说说这次的情况吧。", "error_description": "体标错误：“说说”是重叠形式，后面不能直接加“了”；这是请求对方说，应去掉“了”，说“你就说说这次的情况吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
