INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说一说，谈一谈；动词“说”的重叠形式，表示时间短或轻松。", "primary_collocate": null, "pronunciation": "shuō shuo", "ipa": "ʂwo˥ ʂwo", "syllable_count": 2, "sentences": [{"text": "你给我们说说今天的事吧。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说自己的想法。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家坐下来，说说这个周末去哪儿玩。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说，我再决定。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能不能说说你家乡的变化？", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你说说我的新工作。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想跟朋友说说心里的话。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说这个词怎么用。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别着急，慢慢说说看。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，你也说说你的看法。", "target_word": "说说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说一说", "label": "重叠"}, {"form": "说了说", "label": "体标"}, {"form": "说说看", "label": "复合"}], "register": "口语", "sense_fingerprint": "“说”的重叠形式，说一说、谈一谈，语气轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说说", "is_correct": true, "explanation": "说说是说一说、谈一谈，“给我们说说今天的事”符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，不能用来“吃”事情。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是物品，不能说“买今天的事”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清洁动作，不能用于事情。"}], "explanations": {"说说": "说说是说一说、谈一谈，“给我们说说今天的事”符合句意。", "吃": "语义：吃是进食，不能用来“吃”事情。", "买": "搭配：“买”的对象是物品，不能说“买今天的事”。", "洗": "语义：洗是清洁动作，不能用于事情。"}, "sentence_index": 0, "correct_answer": "说说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作家在小说里说说童年的经历。", "explanation": "这里应该用〈叙述〉。“说说”是口语，语气随便，书面叙述经历要用〈叙述〉。"}, {"text": "院士在大会上说说这项科研成果的意义，足足讲了两个小时。", "explanation": "这里应该用〈阐述〉。“说说”只是简单说一说，不能用于长时间、系统地讲解重大成果，应用〈阐述〉。"}, {"text": "我昨天跟领导说说这份报告，足足说了三个小时。", "explanation": "这里应该用〈汇报〉。“说说”表示时间短、语气轻松，连续三个小时的正式工作汇报要用〈汇报〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说说", "is_correct": true, "explanation": "说说是说一说、谈一谈，跟朋友谈谈心里的话，符合句意。"}, {"text": "拆", "is_correct": false, "explanation": "语义：拆是拆开，不能“拆”话。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，不能“修”心里的话。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”的对象一般是物品或钱，不能说“借心里的话”。"}], "explanations": {"说说": "说说是说一说、谈一谈，跟朋友谈谈心里的话，符合句意。", "拆": "语义：拆是拆开，不能“拆”话。", "修": "语义：修是修理，不能“修”心里的话。", "借": "搭配：“借”的对象一般是物品或钱，不能说“借心里的话”。"}, "sentence_index": 6, "correct_answer": "说说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向朋友说说自己的委屈，一说就是一个晚上。", "explanation": "这里应该用〈诉说〉。“说说”只是轻松地说一说，不能用于一说就是整夜的委屈诉说，应用〈诉说〉。"}, {"text": "作者用了三年时间说说这座城市的变化。", "explanation": "这里应该用〈描写〉。“说说”表示时间短、语气轻松，花三年时间写城市变化要用〈描写〉。"}, {"text": "校长在典礼上说说名单。", "explanation": "这里应该用〈宣读〉。“说说”只是随便讲讲，正式宣读名单要用〈宣读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你先说说了你的计划吧。", "corrected_sentence": "你先说说你的计划吧。", "error_description": "体标错误：“说说”是重叠形式，后面不能直接加“了”；这是请对方先说，应去掉“了”，说“你先说说你的计划吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你说说过你的感受吧。", "corrected_sentence": "请你说说你的感受吧。", "error_description": "体标错误：“说说”是重叠形式，后面不能直接加“过”，应去掉“过”，正确句是“请你说说你的感受吧。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
