INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86673, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "即将是马上就要。", "primary_collocate": null, "pronunciation": "jí jiāng", "ipa": "tɕi˧˥ tɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "火车即将到站，请大家准备下车。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛即将开始，大家都坐好了。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我即将毕业，心里有点难过。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机即将起飞，请关上手机。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年即将到来，街上很热闹。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影即将结束，大家都不说话。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的机票已经订好，即将去国外工作。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天即将过去，花都开完了。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的生日即将到来，我想买蛋糕。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师即将回来，同学们赶快坐好。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "即将：放在动词前，表示某件事离现在很近，马上就会发生。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“请大家准备下车”所说的火车即将到站相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过的事，与“请大家准备下车”这种即将发生的语境不符。"}, {"text": "即将", "is_correct": true, "explanation": "“即将”表示马上就要发生，与“请大家准备下车”的语境相符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能修饰“到站”这种一次性的动作。"}], "explanations": {"从不": "语义：“从不”表示从来没有，与“请大家准备下车”所说的火车即将到站相矛盾。", "曾经": "语义：“曾经”指过去发生过的事，与“请大家准备下车”这种即将发生的语境不符。", "即将": "“即将”表示马上就要发生，与“请大家准备下车”的语境相符。", "一直": "搭配：“一直”表示持续，不能修饰“到站”这种一次性的动作。"}, "sentence_index": 0, "correct_answer": "即将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影去年即将上映。", "explanation": "这里应该用〈已经〉。即将指不久之后将要发生，不能与“去年”这样的过去时间搭配。"}, {"text": "请大家即将排好队。", "explanation": "这里应该用〈立即〉。即将只说事情快要发生，不用来催促别人马上行动，命令句要用〈立即〉。"}, {"text": "妈妈即将喜欢这个礼物。", "explanation": "这里应该用〈会〉。即将表示事情马上要发生，不能用来预告“喜欢”这种持续的心理状态；表示将来的心情，应说“会喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“机票已经订好”的事先安排不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去发生过的事，与“机票已经订好”、马上要出国的安排不符。"}, {"text": "即将", "is_correct": true, "explanation": "“即将”表示将要发生，与“机票已经订好、即将出国”的安排相符。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示一贯保持某种状态，不能修饰“去”这类一次性的动作。"}], "explanations": {"忽然": "语义：“忽然”表示突然发生，与“机票已经订好”的事先安排不合。", "曾经": "语义：“曾经”指过去发生过的事，与“机票已经订好”、马上要出国的安排不符。", "即将": "“即将”表示将要发生，与“机票已经订好、即将出国”的安排相符。", "始终": "搭配：“始终”表示一贯保持某种状态，不能修饰“去”这类一次性的动作。"}, "sentence_index": 6, "correct_answer": "即将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十年后，我即将当上医生。", "explanation": "这里应该用〈会〉。即将只表示马上就要发生，不能用于十年后这样很远的将来；泛指的将来应说“会”。"}, {"text": "我们每周末即将去公园散步。", "explanation": "这里应该用〈经常〉。即将只说一次马上就要发生的事，不能表示反复出现的习惯。"}, {"text": "这座桥即将在十年前建好。", "explanation": "这里应该用〈已经〉。即将指不久之后将要发生，不能用于十年前这样的过去时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机即将了降落，请系好安全带。", "corrected_sentence": "飞机即将降落，请系好安全带。", "error_description": "错误：“即将”与动词之间不能插入“了”，成了“即将了降落”。“即将”后直接接动词，正确形式是“即将降落”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节即将了来到，大家都很忙。", "corrected_sentence": "春节即将来到，大家都很忙。", "error_description": "错误：“即将”与动词之间不能插入“了”，成了“即将了来到”。“即将”后直接接动词，正确形式是“即将来到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
