INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86674, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，就要；将要。", "primary_collocate": null, "pronunciation": "jí jiāng", "ipa": "tɕi˧˥ tɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "考试即将开始，请不要说话。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新家即将完工。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期即将结束，学生都回到了学校。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳即将落山，天慢慢黑了。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出即将开始，观众都坐满了。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们即将结婚，朋友们都很高兴。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店合同到期，即将关门，东西都在打折。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议即将结束，大家鼓起掌来。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯即将到达十楼。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天即将到来，天气变凉了。", "target_word": "即将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "即将：副词，相当于“就要”“将要”，多用于书面语，后面接动词。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“请不要说话”所提醒的考试即将开始的语境相矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的事，与“请不要说话”这种针对眼前即将发生情况的提醒不符。"}, {"text": "即将", "is_correct": true, "explanation": "“即将”表示就要发生，与“考试开始”的语境相符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能修饰“开始”这种起始性的动作。"}], "explanations": {"从不": "语义：“从不”表示从来没有，与“请不要说话”所提醒的考试即将开始的语境相矛盾。", "曾经": "语义：“曾经”指过去的事，与“请不要说话”这种针对眼前即将发生情况的提醒不符。", "即将": "“即将”表示就要发生，与“考试开始”的语境相符。", "一直": "搭配：“一直”表示持续，不能修饰“开始”这种起始性的动作。"}, "sentence_index": 0, "correct_answer": "即将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的新家去年即将完工。", "explanation": "这里应该用〈已经〉。即将指不久之后将要发生，不能与“去年”这样的过去时间搭配。"}, {"text": "请同学们即将安静下来。", "explanation": "这里应该用〈立即〉。即将只说事情快要发生，不用于要求别人马上行动，命令语气要用〈立即〉。"}, {"text": "姐姐即将讨厌这个季节。", "explanation": "这里应该用〈会〉。即将表示事情马上要发生，不能用来预告“讨厌”这种持续的心理状态；表示将来的心情，应说“会讨厌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”多用于否定或表示一贯如此，不能修饰“合同到期后关门”这件将要发生的事。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示一贯保持，不能修饰“关门”这种一次性的动作。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续状态，与“合同到期”后才关门、正在打折的情况不符。"}, {"text": "即将", "is_correct": true, "explanation": "“即将”表示就要发生，与“合同到期、即将关门”的语境相符。"}], "explanations": {"从来": "语义：“从来”多用于否定或表示一贯如此，不能修饰“合同到期后关门”这件将要发生的事。", "始终": "搭配：“始终”表示一贯保持，不能修饰“关门”这种一次性的动作。", "一直": "语义：“一直”表示持续状态，与“合同到期”后才关门、正在打折的情况不符。", "即将": "“即将”表示就要发生，与“合同到期、即将关门”的语境相符。"}, "sentence_index": 6, "correct_answer": "即将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每个周末即将去钓鱼。", "explanation": "这里应该用〈经常〉。即将只说一次马上就要发生的事，不能表示每个周末反复出现的习惯。"}, {"text": "五年后，我即将当上律师。", "explanation": "这里应该用〈会〉。即将只表示马上就要发生，不能用于五年后这样较远的将来；泛指的将来应说“会”。"}, {"text": "我即将在二十年前出生。", "explanation": "这里应该用〈已经〉。即将指不久之后将要发生，不能用于二十年前这样的过去时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新学期即将了开始，同学们要早点来。", "corrected_sentence": "新学期即将开始，同学们要早点来。", "error_description": "错误：“即将”与动词之间不能插入“了”，成了“即将了开始”。“即将”后直接接动词，正确形式是“即将开始”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天即将了结束，花都要谢了。", "corrected_sentence": "春天即将结束，花都要谢了。", "error_description": "错误：“即将”与动词之间不能插入“了”，成了“即将了结束”。“即将”后直接接动词，正确形式是“即将结束”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
