INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物中最主要、最关键的部分；特别着重的地方。", "primary_collocate": null, "pronunciation": "zhòng diǎn", "ipa": "ʈʂʊŋ˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "学校今年的工作重点是安全。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把市场当作工作的重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一课的教学重点是汉字的写法。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的重点是帮助老人。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题是整个计划的重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的演讲重点是新产品的优点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天的讲课重点是语法。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的重点是介绍中国历史。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究重点是中文教育。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书的重点，要用大字写出来。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个重点", "label": "量词"}, {"form": "重点学校", "label": "复合"}, {"form": "重點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作、计划、研究中最主要、最关键、特别着重的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_v