INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86678, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，包括说话人和听话人在内的我们。", "primary_collocate": null, "pronunciation": "zán men", "ipa": "tsan˧˥ mən", "syllable_count": 2, "sentences": [{"text": "咱们俩住得很近。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，咱们听你的。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们快点儿，不然就迟到了。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王，咱们好久没见了。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们明天在学校门口见面，好吗？", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，咱们一定能赢。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们去超市买点儿水果吧。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨了，咱们别出去了。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来，咱们一起看看这张地图。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在咱们开始上课。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱", "label": "单数"}, {"form": "咱们俩", "label": "复合"}, {"form": "咱們", "label": "繁体"}], "register": "口语", "sense_fingerprint": "代词，包括说话人和听话人在内的我们", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大家", "is_correct": false, "explanation": "搭配：「大家」泛指全体，不能与数词「俩」组合，「大家俩」不成立。"}, {"text": "咱们", "is_correct": true, "explanation": "正确。「咱们俩」指说话人和听话人两人，「住得很近」与之相符。"}, {"text": "别人", "is_correct": false, "explanation": "语义：「别人」指说话人和听话人之外的他人，不能与指两人的「俩」配合来指说话人和听话人。"}, {"text": "自己", "is_correct": false, "explanation": "语法：「自己」是反身代词，不能直接和「俩」组合，「自己俩」不成立。"}], "explanations": {"大家": "搭配：「大家」泛指全体，不能与数词「俩」组合，「大家俩」不成立。", "咱们": "正确。「咱们俩」指说话人和听话人两人，「住得很近」与之相符。", "别人": "语义：「别人」指说话人和听话人之外的他人，不能与指两人的「俩」配合来指说话人和听话人。", "自己": "语法：「自己」是反身代词，不能直接和「俩」组合，「自己俩」不成立。"}, "sentence_index": 0, "correct_answer": "咱们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "咱们只有我一个人，很孤单。", "explanation": "「咱们」表示复数，句中只有说话人一人，应改用「我」。"}, {"text": "你别去，咱们俩去超市吧。", "explanation": "「咱们俩」包括听话人，却让听话人别去，前后矛盾，应改用「我们俩」。"}, {"text": "妈妈，咱们学生都很想您。", "explanation": "「咱们」包括听话人，妈妈不是学生，应改用「我们」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互相", "is_correct": false, "explanation": "语法：「互相」是副词，不能作主语，「互相去超市买点儿水果吧」不成立。"}, {"text": "咱们", "is_correct": true, "explanation": "正确。「咱们」包括说话人和听话人，「去超市买点儿水果吧」是对听话人的提议。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」是疑问代词，不能作提议句的主语，句中并不是提问。"}, {"text": "对方", "is_correct": false, "explanation": "语义：「对方」指交流双方中的另一方，不包括说话人，与提议的对象不符。"}], "explanations": {"互相": "语法：「互相」是副词，不能作主语，「互相去超市买点儿水果吧」不成立。", "咱们": "正确。「咱们」包括说话人和听话人，「去超市买点儿水果吧」是对听话人的提议。", "谁": "语义：「谁」是疑问代词，不能作提议句的主语，句中并不是提问。", "对方": "语义：「对方」指交流双方中的另一方，不包括说话人，与提议的对象不符。"}, "sentence_index": 6, "correct_answer": "咱们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老王，咱们俩没去开会，你去了吧？", "explanation": "「咱们俩」包括听话人老王，句中又说老王去了开会，与「咱们俩没去」矛盾，应改用「我们俩」。"}, {"text": "我和同事昨天去超市了，你没去，咱们买了很多水果。", "explanation": "「咱们」包括听话人，句中说听话人没去超市，应改用「我们」。"}, {"text": "李老师，咱们请您先坐。", "explanation": "「咱们」把听话人算在内，「请您先坐」又把听话人当作被邀请的对象，二者冲突，应改用「我们」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咱们们三个一起练习一下口语吧。", "corrected_sentence": "咱们三个一起练习一下口语吧。", "error_description": "重复：「咱们」本身已表示复数，后面不能再加「们」；应说「咱们三个一起练习一下口语吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咱们俩们都同意这个方案。", "corrected_sentence": "咱们俩都同意这个方案。", "error_description": "重复：「咱们俩」已表示两人，后面不能再加「们」；应说「咱们俩都同意这个方案」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
