INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "另外是除了说过的以外，还有别的。", "primary_collocate": null, "pronunciation": "lìng wài", "ipa": "lɪŋ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书我看完了，另外一本还没看。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有两个朋友，一个是老师，另外一个是医生。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不好，我们想想另外的办法。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天不在，请你另外一天再来吧。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太远，我们走另外一条吧。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢红色，她喜欢另外的颜色。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三杯水，两杯是我的，另外一杯是你的。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难，你问另外一位老师吧。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一部分学生去了公园，另外的学生留在教室。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一个房间，另外那个房间更大。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指示代词，指已说的人或事物之外的其他的，常放在名词或数量词前，如“另外一个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：指已说之外的另一本，与“一本”搭配，句意通顺。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“这个”与“一本”的量词不能同时出现，应说“这一本”。"}, {"text": "那个", "is_correct": false, "explanation": "搭配：“那个”的量词是“个”，不能直接接“一本”。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不能指书，与“一本”不合。"}], "explanations": {"另外": "另外：指已说之外的另一本，与“一本”搭配，句意通顺。", "这个": "搭配：“这个”与“一本”的量词不能同时出现，应说“这一本”。", "那个": "搭配：“那个”的量词是“个”，不能直接接“一本”。", "大家": "语义：“大家”指人，不能指书，与“一本”不合。"}, "sentence_index": 0, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天不在，请你另外这一天再来吧。", "explanation": "“另外”指已说之外的，不能再与“这”同指已说的那一天，应说“另外一天”。"}, {"text": "他今天不在，请你一天另外再来吧。", "explanation": "语序错误：指示代词“另外”要放在数量词前，应说“另外一天”。"}, {"text": "他今天不在，请你今天另外一天再来吧。", "explanation": "“另外一天”指今天之外的日子，与“今天”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：指已说之外的另一杯，与“两杯”形成对比，句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”表示疑问或不定指人，不能指“一杯水”。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指人，不能与数量词“一杯”直接组合。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”后不接“一杯”，应说“每一杯”。"}], "explanations": {"另外": "另外：指已说之外的另一杯，与“两杯”形成对比，句意通顺。", "谁": "语义：“谁”表示疑问或不定指人，不能指“一杯水”。", "自己": "搭配：“自己”指人，不能与数量词“一杯”直接组合。", "每个": "搭配：“每个”后不接“一杯”，应说“每一杯”。"}, "sentence_index": 6, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我只住这一个房间，另外那个房间更大。", "explanation": "这里的“另外”指已说范围之外还有别的，与“只住这一个房间”的限定矛盾，不能用此义。"}, {"text": "所有房间都很小，另外那个房间更大。", "explanation": "这里的“另外”表示范围之外还有别的，但“所有房间都很小”已把那个房间包括在内，二者矛盾。"}, {"text": "我没有别的房间，另外那个房间更大。", "explanation": "这里的“另外”表示范围之外还有别的，与“没有别的房间”自相矛盾，不能用此义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两本书，另外了一本是送给朋友的。", "corrected_sentence": "我买了两本书，另外一本是送给朋友的。", "error_description": "误加“了”：“另外”修饰“一本”时不能带“了”，应说“另外一本”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有三把伞，另外把是你的。", "corrected_sentence": "我有三把伞，另外一把是你的。", "error_description": "数量词缺失：“另外”后要接数量短语“一把”，应说“另外一把”，不能只说“另外把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在已说的范围之外，还有其他的。", "primary_collocate": null, "pronunciation": "lìng wài", "ipa": "lɪŋ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我买了苹果，另外还买了一些香蕉。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，另外也会说日语。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天要做作业，另外还要复习课文。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖衣服，另外也卖鞋子。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我一本书，另外还给了我一支笔。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我要上课，另外还要去医院。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步，另外还游泳。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议三点开始，另外请大家带上电脑。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去北京，另外也想去上海看看。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间不大，另外价格也有点儿高。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词前或句首，表示在前面所说的事之外再补充别的事，常与“还”“也”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c202a5e-a9ce-434e-8067-66e8bfcf13bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：表示在已说之外再补充，与“还”连用，句意通顺。"}, {"text": "很", "is_correct": false, "explanation": "搭配：程度副词“很”不能与“还买”组合，句意不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：程度副词“非常”不能修饰“还买”，句意不通。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限制，与“还买”的补充义矛盾。"}], "explanations": {"另外": "另外：表示在已说之外再补充，与“还”连用，句意通顺。", "很": "搭配：程度副词“很”不能与“还买”组合，句意不通。", "非常": "搭配：程度副词“非常”不能修饰“还买”，句意不通。", "只": "语义：“只”表示限制，与“还买”的补充义矛盾。"}, "sentence_index": 0, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店只卖衣服，另外也卖鞋子。", "explanation": "这里的“另外”指已说范围之外还有别的，与“只卖衣服”的限定矛盾，不能用此义。"}, {"text": "这家店从来不卖鞋子，另外也卖鞋子。", "explanation": "这里的“另外”表示范围之外还有别的，但“从来不卖鞋子”已否定了这一点，二者矛盾。"}, {"text": "这家店卖所有的商品，另外也卖鞋子。", "explanation": "这里的“另外”指已说范围之外还有别的，但“卖所有的商品”已把鞋子包括在内，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：表示在已说之外再补充，与“还”连用，句意通顺。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：程度副词“比较”不能与“还游泳”组合，句意不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：程度副词“十分”不能修饰“还游泳”，句意不通。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示出乎意料，与“每天跑步”的习惯性句意不合。"}], "explanations": {"另外": "另外：表示在已说之外再补充，与“还”连用，句意通顺。", "比较": "搭配：程度副词“比较”不能与“还游泳”组合，句意不通。", "十分": "搭配：程度副词“十分”不能修饰“还游泳”，句意不通。", "突然": "语义：“突然”表示出乎意料，与“每天跑步”的习惯性句意不合。"}, "sentence_index": 6, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房间唯一的床很大，另外还有两张床。", "explanation": "这里的“另外”指已说范围之外还有别的，与“唯一的床”的限定矛盾，不能用此义。"}, {"text": "房间不大，价格也低，另外也很高。", "explanation": "这里的“另外”表示补充，与前句“价格也低”形成矛盾，不能用来说明价格很高。"}, {"text": "房间不大，所有的费用都已经算清了，另外也有点儿高。", "explanation": "这里的“另外”表示范围之外还有别的，但“所有的费用都已经算清了”已把全部费用纳入，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他会打篮球，另外了也会游泳。", "corrected_sentence": "他会打篮球，另外也会游泳。", "error_description": "误加“了”：副词“另外”后不能加“了”，应说“另外也会游泳”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了北京，很另外也去了上海。", "corrected_sentence": "我们去了北京，另外也去了上海。", "error_description": "修饰误用：副词“另外”不能被“很”修饰，“很”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07347810-90e0-4782-b133-85a9486f945f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
