INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以某种态度或行为处理人或事。", "primary_collocate": null, "pronunciation": "duì dài", "ipa": "tweɪ˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们要认真对待这次考试。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不认真对待工作，经常迟到。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你严肃对待这个问题。", "target_word": "对待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对待错误，我们不能马虎。", "target_word": "对待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她用平常心对待成功和失败。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怎么对待这件事，我不太清楚。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司对待环境问题的态度变了。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要正确对待别人的批评。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一向冷静地对待各种困难。", "target_word": "对待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前我没认真对待过学习，现在后悔了。", "target_word": "对待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对待了", "label": "完成体（了）"}, {"form": "对待过", "label": "经历体（过）"}, {"form": "对待着", "label": "持续体（着）"}], "register": "中性", "sense_fingerprint": "对待：以某种态度或行为处理人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef6fb817-c5a5-47d1-a0ed-24e25267f898') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敷衍", "is_correct": false, "explanation": "语义：“敷衍”是马虎应付，与“认真”相反。"}, {"text": "对待", "is_correct": true, "explanation": "“对待”指用认真的态度处理事情，这里与“认真”相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不重视，与“认真”相矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”多用于人或作品，不说“赞美考试”。"}], "explanations": {"敷衍": "语义：“敷衍”是马虎应付，与“认真”相反。", "对待": "“对待”指用认真的态度处理事情，这里与“认真”相符。", "忽视": "语义：“忽视”是不重视，与“认真”相矛盾。", "赞美": "搭配：“赞美”多用于人或作品，不说“赞美考试”。"}, "sentence_index": 0, "correct_answer": "对待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对待了一块蛋糕，就吃了起来。", "explanation": "这里应该用〈切〉。“对待”表示用某种态度处理人或事，不能用来说用刀把蛋糕分开；切蛋糕应说〈切〉。"}, {"text": "这两道菜的味道正好对待。", "explanation": "这里应该用〈相配〉。“对待”没有“相配”的意思。"}, {"text": "他对待了一下门，就推开了它。", "explanation": "这里应该用〈敲〉。“对待”表示对人或事的态度，不能表示用手碰门；敲门应说〈敲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝味道，不能说“品尝环境问题的态度”，与句意不符。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪去枝叶，与“环境问题”搭配不通，句子说不通。"}, {"text": "对待", "is_correct": true, "explanation": "“对待”指对事情采取的态度，这里是公司对环境问题的态度。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“饲养环境问题的态度”。"}], "explanations": {"品尝": "语义：“品尝”指尝味道，不能说“品尝环境问题的态度”，与句意不符。", "修剪": "语义：“修剪”指剪去枝叶，与“环境问题”搭配不通，句子说不通。", "对待": "“对待”指对事情采取的态度，这里是公司对环境问题的态度。", "饲养": "搭配：“饲养”的对象是动物，不能说“饲养环境问题的态度”。"}, "sentence_index": 6, "correct_answer": "对待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在门口对待了很久才进去。", "explanation": "这里应该用〈等待〉。“对待”没有“等候”的意思。"}, {"text": "我们对待了一个小时的电影，觉得很精彩。", "explanation": "这里应该用〈看〉。“对待”表示对人或事的态度，不能指观看电影。"}, {"text": "她每天早上用水对待花园里的花。", "explanation": "这里应该用〈浇〉。“对待”表示用某种态度处理人或事，不能表示给花浇水；给花浇水应说〈浇〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板对待下属了很严厉。", "corrected_sentence": "老板对待下属很严厉。", "error_description": "“了”位置错误：“了”不能放在宾语“下属”和“很严厉”之间。这句描述的是一般态度，应去掉“了”，说“老板对待下属很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是热情地对待了朋友。", "corrected_sentence": "他总是热情地对待朋友。", "error_description": "“了”用法错误：“总是”表示经常性的习惯，“对待”后面不能加完成体“了”。应去掉“了”，说“他总是热情地对待朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a681fc-fe7f-4c14-8977-15c7203e90a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
