INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86686, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于较大或固定的物体。", "primary_collocate": null, "pronunciation": "zuò", "ipa": "tsuo˥˩", "syllable_count": 1, "sentences": [{"text": "河上有一座新桥。", "target_word": "座", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家旁边有一座高楼。", "target_word": "座", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座城市很大，也很干净。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一座白色的塔。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在江边建了一座大桥。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座楼有三十层，电梯常常很忙。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上有一座小庙，每天都有人去。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广场中间有一座雕像，很多人在那儿拍照。", "target_word": "座", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥已经用了五十年，现在还很结实。", "target_word": "座", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说城里新建了一座很大的图书馆。", "target_word": "座", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座座", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词：用于桥、楼、塔、城市等较大或固定的物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "座", "is_correct": true, "explanation": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。"}, {"text": "错", "is_correct": false, "explanation": "cuò 与 zuò 声母不同（c 与 z），声调相同，意思是错误。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是最。"}], "explanations": {"座": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。", "错": "cuò 与 zuò 声母不同（c 与 z），声调相同，意思是错误。", "左": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。", "最": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是最。"}, "sentence_index": null, "correct_answer": "座"}, "level_3": {"options": [{"text": "张", "is_correct": false, "explanation": "搭配：「张」用于桌子、纸等平面的东西，桥不用「张」计量。"}, {"text": "座", "is_correct": true, "explanation": "正确。「座」用于桥、楼、塔等较大或固定的物体。"}, {"text": "只", "is_correct": false, "explanation": "搭配：「只」用于动物等，桥不能用「只」计量。"}, {"text": "间", "is_correct": false, "explanation": "语义：「间」用于房屋，桥不是房间，「一间新桥」不成立。"}], "explanations": {"张": "搭配：「张」用于桌子、纸等平面的东西，桥不用「张」计量。", "座": "正确。「座」用于桥、楼、塔等较大或固定的物体。", "只": "搭配：「只」用于动物等，桥不能用「只」计量。", "间": "语义：「间」用于房屋，桥不是房间，「一间新桥」不成立。"}, "sentence_index": 0, "correct_answer": "座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上有一座小杯子。", "explanation": "「座」用于较大或固定的物体，小杯子应用「个」计量，这里不能用「座」。"}, {"text": "我买了一座新铅笔。", "explanation": "「座」用于较大或固定的物体，铅笔细小，应用「支」计量，这里不能用「座」。"}, {"text": "他穿了一座新鞋。", "explanation": "「座」不能计量鞋，鞋应用「双」计量，这里不能用「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "座", "is_correct": true, "explanation": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。"}, {"text": "昨", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。"}, {"text": "醉", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。"}], "explanations": {"座": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。", "昨": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。", "醉": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。", "左": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。"}, "sentence_index": null, "correct_answer": "座"}, "level_3": {"options": [{"text": "张", "is_correct": false, "explanation": "搭配：「张」用于桌子、纸等平面的东西，小庙不用「张」计量。"}, {"text": "座", "is_correct": true, "explanation": "正确。「座」用于庙、桥、楼、塔等较大或固定的物体。"}, {"text": "块", "is_correct": false, "explanation": "搭配：「块」用于块状或片状的东西，「小庙」不能用「块」计量。"}, {"text": "位", "is_correct": false, "explanation": "搭配：「位」用于人，小庙不能用「位」计量。"}], "explanations": {"张": "搭配：「张」用于桌子、纸等平面的东西，小庙不用「张」计量。", "座": "正确。「座」用于庙、桥、楼、塔等较大或固定的物体。", "块": "搭配：「块」用于块状或片状的东西，「小庙」不能用「块」计量。", "位": "搭配：「位」用于人，小庙不能用「位」计量。"}, "sentence_index": 6, "correct_answer": "座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一座小书包。", "explanation": "「座」用于较大或固定的物体，书包应用「个」计量，这里不能用「座」。"}, {"text": "桌上放着一座小手机。", "explanation": "「座」用于较大或固定的物体，手机应用「部」计量，这里不能用「座」。"}, {"text": "他送了我一座小花。", "explanation": "「座」不能计量花，花应用「朵」计量，这里不能用「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings