INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86687, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女儿是爸爸妈妈生的女孩子。", "primary_collocate": null, "pronunciation": "nǚ ér", "ipa": "ny˨˩˦ aɚ˧˥", "syllable_count": 2, "sentences": [{"text": "女儿正在房间里写作业。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给女儿讲了一个故事。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子是他们的大女儿。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们生了一个儿子和一个女儿。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿每天早上自己穿衣服。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了女儿最爱吃的鱼。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿从小就喜欢画画。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷抱着小女儿坐在门口。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿长大后想当医生。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿笑着对爸爸说：“生日快乐！”", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女兒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "爸爸妈妈生的女孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女儿", "is_correct": true, "explanation": "正确。“女儿”指爸爸妈妈生的女孩，可以在房间里写作业。"}, {"text": "女装", "is_correct": false, "explanation": "语义：“女装”是衣服，不会写作业。"}, {"text": "女鞋", "is_correct": false, "explanation": "语义：“女鞋”是鞋子，不会写作业。"}, {"text": "女婴", "is_correct": false, "explanation": "语义：“女婴”指刚出生不久的女婴，不能在房间里写作业。"}], "explanations": {"女儿": "正确。“女儿”指爸爸妈妈生的女孩，可以在房间里写作业。", "女装": "语义：“女装”是衣服，不会写作业。", "女鞋": "语义：“女鞋”是鞋子，不会写作业。", "女婴": "语义：“女婴”指刚出生不久的女婴，不能在房间里写作业。"}, "sentence_index": 0, "correct_answer": "女儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的女儿都很聪明。", "explanation": "这里应该用〈女生〉。“女儿”指父母的子女，不能泛指班里的女学生。"}, {"text": "这块石头的女儿很圆。", "explanation": "“女儿”只指人的子女，不能用来指石头，这里应说〈鹅卵石〉。"}, {"text": "车站里一个女儿在等车。", "explanation": "“女儿”指父母的子女，不能用来指路上遇到的陌生女子，这里应说〈女子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女儿", "is_correct": true, "explanation": "正确。“女儿”指从小长大的女性子女，与“从小就喜欢画画”相符。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：“裙子”是衣服，不会喜欢画画。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”是看时间的东西，不会喜欢画画。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书的包，不会喜欢画画。"}], "explanations": {"女儿": "正确。“女儿”指从小长大的女性子女，与“从小就喜欢画画”相符。", "裙子": "语义：“裙子”是衣服，不会喜欢画画。", "手表": "语义：“手表”是看时间的东西，不会喜欢画画。", "书包": "语义：“书包”是装书的包，不会喜欢画画。"}, "sentence_index": 6, "correct_answer": "女儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的女儿，今年十岁。", "explanation": "“女儿”指女性子女，指男孩应该说“儿子”，这里性别对不上。"}, {"text": "这堵女儿很高。", "explanation": "“女儿墙”是一个词，指建筑物顶部边缘的矮墙。这里不能把“女儿”单独拿来指墙。"}, {"text": "我的同桌叫女儿，她很活泼。", "explanation": "“女儿”是父母对子女的称呼，不是人名，这里用作名字不符合它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一条女儿，很聪明。", "corrected_sentence": "我家有一个女儿，很聪明。", "error_description": "错误形式是“一条女儿”，量词“条”多用于细长的物品，不能用来数人。“女儿”应用量词“个”或“位”。这里只错了量词这一处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家有两个女儿们，都很懂事。", "corrected_sentence": "我们家有两个女儿，都很懂事。", "error_description": "错误形式是“两个女儿们”，在数量词后加了“们”。正确形式是“两个女儿”。“们”不能与数量词连用，数量词后的名词不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
