INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自己或他人生的女孩，是父母对女性子女的称呼。", "primary_collocate": null, "pronunciation": "nǚ ér", "ipa": "ny˨˩˦ aɚ˧˥", "syllable_count": 2, "sentences": [{"text": "我女儿今年五岁了。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个很聪明的女儿。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的女儿也在这所学校学习。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常说，女儿是她的小棉袄。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给女儿买一条红裙子。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您的女儿真漂亮！", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我带女儿去公园玩。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张把女儿送到了机场。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的女儿已经上大学了。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的女儿会弹钢琴。", "target_word": "女儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女兒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己或别人的女性子女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ace52f-4b54-4415-b4c7-8a6cdf3cb696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女儿", "is_correct": true, "explanation": "正确。“女儿”指自己的女性子女，与“我……今年五岁了”相符。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：“妻子”是配偶，不可能是五岁的孩子。"}, {"text": "千金", "is_correct": false, "explanation": "语域：“千金”是敬称别人女儿的词，用来说自己的女儿不合适。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：“妈妈”是母亲，“我妈妈今年五岁”在辈分和年龄上都说不通。"}], "explanations": {"女儿": "正确。“女儿”指自己的女性子女，与“我……今年五岁了”相符。", "妻子": "语义：“妻子”是配偶，不可能是五岁的孩子。", "千金": "语域：“千金”是敬称别人女儿的词，用来说自己的女儿不合适。", "妈妈": "语义：“妈妈”是母亲，“我妈妈今年五岁”在辈分和年龄上都说不通。"}, "sentence_index": 0, "correct_answer": "女儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的女儿都很聪明。", "explanation": "这里应该用〈女孩〉。“女儿”指父母的子女，不能用来泛指班里的女孩子。"}, {"text": "这辆汽车的女儿很快。", "explanation": "“女儿”只指人的子女，不能用来指车辆，这里应直接说“这辆汽车很快”。"}, {"text": "我最爱喝的女儿是绍兴名酒。", "explanation": "“女儿”不能单独指酒，应整体说〈女儿红〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女儿", "is_correct": true, "explanation": "正确。“女儿”指自己的女性子女，可以被带去公园。"}, {"text": "女鞋", "is_correct": false, "explanation": "语义：“女鞋”是鞋子，不能被带去公园“玩”。"}, {"text": "女厕", "is_correct": false, "explanation": "语义：“女厕”是厕所，不能被人带去公园。"}, {"text": "女王", "is_correct": false, "explanation": "语义：“女王”是君主，与“我周末带她去公园玩”的家庭场景不符。"}], "explanations": {"女儿": "正确。“女儿”指自己的女性子女，可以被带去公园。", "女鞋": "语义：“女鞋”是鞋子，不能被带去公园“玩”。", "女厕": "语义：“女厕”是厕所，不能被人带去公园。", "女王": "语义：“女王”是君主，与“我周末带她去公园玩”的家庭场景不符。"}, "sentence_index": 6, "correct_answer": "女儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的女儿，今年十岁。", "explanation": "“女儿”指女性子女，指男孩应该说“儿子”，这里性别对不上。"}, {"text": "这堵女儿很高。", "explanation": "“女儿墙”是一个词，指建筑物顶部边缘的矮墙。这里应整体说“女儿墙”，不能把“女儿”单独拿来指墙。"}, {"text": "我的同桌叫女儿，她很活泼。", "explanation": "“女儿”是父母对子女的称呼，不是人名，这里用作名字不符合它的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有两个女儿们，都很聪明。", "corrected_sentence": "我有两个女儿，都很聪明。", "error_description": "错误形式是“两个女儿们”，在数量词后加了“们”。正确形式是“两个女儿”。“们”不能与数量词连用，数量词后的名词不加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一个的女儿，在北京工作。", "corrected_sentence": "他有一个女儿，在北京工作。", "error_description": "错误形式是“一个的女儿”，在数量词和名词之间多加了“的”。正确形式是“一个女儿”。“的”不能插在数量词和名词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084398b5-329a-4428-a5d1-c5d68c71cc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
