INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86689, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示事情已经如此，并以此为前提进行推论或作出结论。", "primary_collocate": null, "pronunciation": "jì rán", "ipa": "tɕi˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "既然是你的决定，我不说什么了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情既然这样了，难过也没用。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他既然来了，就让他坐下吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你既然知道了，就别告诉别人。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然如此，我们就不用再等了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然你已经决定了，我就支持你。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然是朋友，帮忙是应该的。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然钱已经花了，后悔也没用。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她既然答应了，就一定会来。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然大家都同意，这件事就这样定了。", "target_word": "既然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "既然如此", "label": "固定短语"}], "register": "中性", "sense_fingerprint": "既然|说明事情已经如此，据此下结论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既然", "is_correct": true, "explanation": "既然说明事情已经定下，据此得出结论，与“我不说什么了”相合。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”需要前文转折，句首不能单独引出这个前提。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示并列或递进，不能说明事情已经如此。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示结果，前面要有原因，这里不能开头使用。"}], "explanations": {"既然": "既然说明事情已经定下，据此得出结论，与“我不说什么了”相合。", "但是": "搭配：“但是”需要前文转折，句首不能单独引出这个前提。", "而且": "语义：“而且”表示并列或递进，不能说明事情已经如此。", "所以": "搭配：“所以”表示结果，前面要有原因，这里不能开头使用。"}, "sentence_index": 0, "correct_answer": "既然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提前出门，既然赶上火车。", "explanation": "这里应该用〈为了〉。“既然”只说明已成事实，表示目的要用“为了”。"}, {"text": "既然我是你，我就不去了。", "explanation": "这里应该用〈如果〉。“我是你”不是事实，是假设，要用“如果”。"}, {"text": "既然他很累，他还是去跑步了。", "explanation": "这里应该用〈尽管〉。后句是让步转折，“既然”只引出据以推论的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既然", "is_correct": true, "explanation": "既然说明双方是朋友这一事实，据此得出“帮忙是应该的”，符合句意。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，不能用来引出“是朋友”这一前提。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”表示转折，前文没有内容可以转折，句首不能单独使用。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”承接前文的原因，句首没有原因，不能这样用。"}], "explanations": {"既然": "既然说明双方是朋友这一事实，据此得出“帮忙是应该的”，符合句意。", "或者": "语义：“或者”表示选择，不能用来引出“是朋友”这一前提。", "然而": "搭配：“然而”表示转折，前文没有内容可以转折，句首不能单独使用。", "因此": "搭配：“因此”承接前文的原因，句首没有原因，不能这样用。"}, "sentence_index": 6, "correct_answer": "既然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "既然大家都反对，但是我们还是做了。", "explanation": "这里应该用〈虽然〉。让步转折要用“虽然……但是……”，“既然”表示已成事实的前提。"}, {"text": "既然大家怎么说，这件事都不能改。", "explanation": "这里应该用〈无论〉。“既然”只引出已成事实，任意情况要用“无论”。"}, {"text": "既然大家同不同意，这件事都要做。", "explanation": "这里应该用〈不管〉。“既然”只引出已成事实，任意情况要用“不管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "既然因为你已经答应了，这件事就这样定了。", "corrected_sentence": "既然你已经答应了，这件事就这样定了。", "error_description": "“既然”与“因为”同时使用，语义重复：只用“既然”即可，去掉“因为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "既然既然大家都同意了，我们就这样办吧。", "corrected_sentence": "既然大家都同意了，我们就这样办吧。", "error_description": "“既然”重复：同一分句只用一个“既然”，多余的一个应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
