INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86690, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，用于前半句，提出已成事实的前提。", "primary_collocate": null, "pronunciation": "jì rán", "ipa": "tɕi˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "既然你累了，就早点休息吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然下雨了，我们就不出去了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然大家都来了，我们开始吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然你喜欢这本书，就送给你吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然已经买了票，就别想那么多了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然你不舒服，今天就别上班了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然天气这么好，我们去公园走走吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然她不想去，你就别叫她了。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既然你会说中文，就帮我们翻译一下吧。", "target_word": "既然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "既然时间不早了，我们回家吧。", "target_word": "既然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "既然如此", "label": "固定短语"}], "register": "中性", "sense_fingerprint": "既然|前半句提出已成事实的前提，后半句常接就", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既然", "is_correct": true, "explanation": "既然提出已成事实的前提，与后句的“就”呼应，符合句意。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”引出结果，“你累了”是原因，二者颠倒，不能用在提出前提的位置。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”引出结果，前面要有原因，不能放在句首引出前提。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”表示转折，前文没有转折内容，句首不能单独使用。"}], "explanations": {"既然": "既然提出已成事实的前提，与后句的“就”呼应，符合句意。", "因而": "语义：“因而”引出结果，“你累了”是原因，二者颠倒，不能用在提出前提的位置。", "所以": "搭配：“所以”引出结果，前面要有原因，不能放在句首引出前提。", "但是": "搭配：“但是”表示转折，前文没有转折内容，句首不能单独使用。"}, "sentence_index": 0, "correct_answer": "既然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早点出门，既然赶上火车。", "explanation": "这里应该用〈为了〉。“既然”引出已成事实的前提，表示目的要用“为了”。"}, {"text": "既然他很忙，但是还是来了。", "explanation": "这里应该用〈虽然〉。让步要用“虽然……但是……”，“既然”只引出已成事实的前提，不能与“但是”搭配。"}, {"text": "既然天气很冷，我还是去跑步了。", "explanation": "这里应该用〈尽管〉。后句是让步转折，“既然”只引出据以推论的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既然", "is_correct": true, "explanation": "既然提出已成事实的前提，天气好是事实，符合句意。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”表示转折，前文没有可转折的内容，不能直接开头使用。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：“不过”表示转折，需要承接前文，不能单独引出前提。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”引出结果，天气好是理由而不是结果，不能这样开头。"}], "explanations": {"既然": "既然提出已成事实的前提，天气好是事实，符合句意。", "然而": "搭配：“然而”表示转折，前文没有可转折的内容，不能直接开头使用。", "不过": "搭配：“不过”表示转折，需要承接前文，不能单独引出前提。", "因而": "语义：“因而”引出结果，天气好是理由而不是结果，不能这样开头。"}, "sentence_index": 6, "correct_answer": "既然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "既然天气不好，但是我们还是要去。", "explanation": "这里应该用〈虽然〉。让步转折要用“虽然……但是……”，“既然”表示已成事实的前提。"}, {"text": "既然谁来，我都欢迎。", "explanation": "这里应该用〈无论〉。“既然”只引出已成事实，任意情况要用“无论”。"}, {"text": "既然天气怎样，我们都去公园吧。", "explanation": "这里应该用〈不管〉。“既然”只引出已成事实，任意情况要用“不管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "既然因为下雨了，我们就改天去吧。", "corrected_sentence": "既然下雨了，我们就改天去吧。", "error_description": "“既然”与“因为”同时使用，语义重复：只用“既然”即可，去掉“因为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "既然既然天气这么好，我们就去郊游吧。", "corrected_sentence": "既然天气这么好，我们就去郊游吧。", "error_description": "“既然”重复：同一分句只用一个“既然”，多余的一个应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
