INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妈妈是生下我们、照顾我们的人。", "primary_collocate": null, "pronunciation": "mā ma", "ipa": "ma˥ ma", "syllable_count": 2, "sentences": [{"text": "妈妈每天早上都给我做早饭。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病的时候，妈妈一直在床边照顾我。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈洗了衣服，又打扫了房间。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的妈妈是医院的护士。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我的书包放在了桌子上。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，妈妈常常给我讲故事。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈很爱我，我也很爱她。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位妈妈抱着孩子在等公共汽车。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈今天下班很晚，我先做了饭。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，我已经长大了，要自己起床。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "媽媽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "生养并照顾孩子的女性亲人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妈妈", "is_correct": true, "explanation": "正确：“妈妈”指生养并照顾我的女性亲人，与“每天早上给我做早饭”的情境吻合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师一般不会每天早上为学生做早饭，与这里的家庭情境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“做早饭”需要有生命的施事，“厨房”是场所，不能充当主语。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有行动能力，不可能每天早上为我做早饭。"}], "explanations": {"妈妈": "正确：“妈妈”指生养并照顾我的女性亲人，与“每天早上给我做早饭”的情境吻合。", "老师": "语义：老师一般不会每天早上为学生做早饭，与这里的家庭情境不符。", "厨房": "配价：“做早饭”需要有生命的施事，“厨房”是场所，不能充当主语。", "石头": "语义：石头没有行动能力，不可能每天早上为我做早饭。"}, "sentence_index": 0, "correct_answer": "妈妈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家请了一位妈妈，每天来做饭。", "explanation": "这里应该用〈阿姨〉。“妈妈”指生养自己的母亲，不指受雇来照顾家庭的人，不能说“请一位妈妈”。"}, {"text": "我的妈妈是我爸爸的母亲。", "explanation": "这里应该用〈奶奶〉。“妈妈”指生养我的人，父亲的母亲与我是祖孙关系，不能用“妈妈”来称呼。"}, {"text": "我的妈妈是我爸爸的妹妹。", "explanation": "这里应该用〈姑姑〉。“妈妈”指生养我的人，爸爸的妹妹是我的姑姑，不能用“妈妈”来称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妈妈", "is_correct": true, "explanation": "正确：空格处作主语的应是“妈妈”，与后句“我也很爱她”中的“她”相呼应，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“爱”要求有感情的施事，“石头”不能充当“很爱我”的主语。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌没有感情，不可能“很爱我”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“很爱我”的主语须是能付出感情的人或动物，“天气”与“爱”搭配不当。"}], "explanations": {"妈妈": "正确：空格处作主语的应是“妈妈”，与后句“我也很爱她”中的“她”相呼应，句意通顺。", "石头": "配价：“爱”要求有感情的施事，“石头”不能充当“很爱我”的主语。", "书桌": "语义：书桌没有感情，不可能“很爱我”。", "天气": "搭配：“很爱我”的主语须是能付出感情的人或动物，“天气”与“爱”搭配不当。"}, "sentence_index": 6, "correct_answer": "妈妈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的妈妈比我大三岁，是我的哥哥。", "explanation": "这里把〈妈妈〉与〈兄长〉的身份混淆了。“妈妈”是生养“我”的长辈，不能是比“我”大的同辈兄长。"}, {"text": "我的妈妈和我同岁，是同班同学。", "explanation": "这里把〈妈妈〉说成了同龄的伙伴。“妈妈”是生养我的长辈，不能与我同岁、同班，这种关系应说〈同学〉。"}, {"text": "我的妈妈是我的女儿，今年五岁。", "explanation": "这里把〈妈妈〉与〈孩子〉的辈分弄反了。“妈妈”是生养“我”的长辈，不能是比“我”年幼的晚辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只很爱我的妈妈。", "corrected_sentence": "我有一个很爱我的妈妈。", "error_description": "错误形式用量词“只”修饰人物名词“妈妈”，“只”多用于动物；指人应用量词“个”，正确形式为“一个很爱我的妈妈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只妈妈在厨房里忙着做饭。", "corrected_sentence": "那位妈妈在厨房里忙着做饭。", "error_description": "错误形式用量词“只”修饰人物名词“妈妈”，“只”多用于动物或小件物品，指人应用量词“位”；正确形式为“那位妈妈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
