INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对母亲的称呼。", "primary_collocate": null, "pronunciation": "mā ma", "ipa": "ma˥ ma", "syllable_count": 2, "sentences": [{"text": "妈妈，我回来了！", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，你看，我画了一幅画。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“妈妈，今天晚饭吃什么？”小明问。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，明天是你的生日，我送你花。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，我饿了，什么时候吃饭？", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩大声叫着：“妈妈，等等我！”", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，别担心，我很好。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着说：“妈妈，我要回家。”", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，这个周末我们去公园好吗？", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，谢谢你给我买的新书包。", "target_word": "妈妈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "媽媽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "孩子当面称呼母亲的叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妈妈", "is_correct": true, "explanation": "正确：孩子回家时对母亲说话用“妈妈”作称呼，与“我回来了”的情境吻合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能被呼唤，也不会回应“我回来了”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“回来了”指人回到家中，与“桌子”这类物品搭配不当。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能作为被称呼的对象。"}], "explanations": {"妈妈": "正确：孩子回家时对母亲说话用“妈妈”作称呼，与“我回来了”的情境吻合。", "窗户": "语义：窗户不能被呼唤，也不会回应“我回来了”。", "桌子": "搭配：“回来了”指人回到家中，与“桌子”这类物品搭配不当。", "书包": "语义：书包是物品，不能作为被称呼的对象。"}, "sentence_index": 0, "correct_answer": "妈妈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对路边的女人说：“妈妈，请问厕所在哪里？”", "explanation": "这里应该用〈阿姨〉。对不认识的成年女性应称“阿姨”，不能用“妈妈”称呼陌生人。"}, {"text": "我对同桌说：“妈妈，请借我一支笔。”", "explanation": "这里应该用〈同学〉。同学之间不用“妈妈”相称，应直呼名字或称“同学”。"}, {"text": "老师站在讲台上说：“妈妈，请大家安静。”", "explanation": "这里应该用〈同学们〉。“妈妈”只用于孩子称呼自己的母亲，老师面对全班应说“同学们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妈妈", "is_correct": true, "explanation": "正确：对担心自己的家人说“妈妈，别担心”，称呼与语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“担心”要求有感情的主体，“石头”不能充当会担心的人。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，没有感情，不会“担心”，也不能被这样称呼。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是物品，不能被呼唤，也不会因我而担心。"}], "explanations": {"妈妈": "正确：对担心自己的家人说“妈妈，别担心”，称呼与语境相符。", "石头": "配价：“担心”要求有感情的主体，“石头”不能充当会担心的人。", "雨伞": "语义：雨伞是物品，没有感情，不会“担心”，也不能被这样称呼。", "台灯": "语义：台灯是物品，不能被呼唤，也不会因我而担心。"}, "sentence_index": 6, "correct_answer": "妈妈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对奶奶说：“妈妈，我们吃饭吧。”", "explanation": "这里把〈妈妈〉用于祖母。“妈妈”只指孩子的生母，对祖母不能这样称呼，应用〈奶奶〉或〈外婆〉的称谓。"}, {"text": "我对爸爸说：“妈妈，你今天很累吧。”", "explanation": "这里把〈妈妈〉用于父亲。“妈妈”只用来称呼母亲，称呼父亲应用〈爸爸〉。"}, {"text": "我对护士说：“妈妈，请帮我量一下血压。”", "explanation": "这里把〈妈妈〉用于陌生的年轻女性。“妈妈”只用于孩子称呼自己的母亲，对年轻女性应称〈姐姐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你妈妈，我今天在学校得了第一名。", "corrected_sentence": "妈妈，我今天在学校得了第一名。", "error_description": "错误形式在称呼“妈妈”前加了“你”，孩子直接称呼自己的母亲不能说“你妈妈”；正确形式直接说“妈妈，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的，你看，我今天得了第一名。", "corrected_sentence": "妈妈，你看，我今天得了第一名。", "error_description": "错误形式在称呼“妈妈”后多出结构助词“的”；正确形式直接称呼“妈妈，……”，呼语后不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
