INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86693, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "没问题是说可以，不用担心。", "primary_collocate": null, "pronunciation": "méi wèn tí", "ipa": "mei˧˥ wən˥˩ tʰi˧˥", "syllable_count": 3, "sentences": [{"text": "“你能帮我拿一下吗？”“没问题！”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“明天八点见面，可以吗？”“没问题。”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“请帮我买两杯咖啡。”“没问题，马上去。”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“我们周末一起吃饭吧。”“没问题，我有空。”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“能借我你的笔吗？”“没问题，给你。”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“今天你来做饭，好吗？”“没问题！”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问：“你们能按时交作业吗？”大家说：“没问题！”", "target_word": "没问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请你明天早点来。”“没问题，我七点到。”", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“把门关上，好吗？”“没问题。”", "target_word": "没问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“没问题，交给我吧。”", "target_word": "没问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有问题", "label": "完整形式"}, {"form": "沒問題", "label": "繁体"}], "register": "口语", "sense_fingerprint": "没问题|答应别人的请求，表示可以", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没问题", "is_correct": true, "explanation": "“没问题”表示答应，与前一句的请求“你能帮我拿一下吗”相符。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”表示惊讶或懊恼，不能用来答应别人的请求。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”是笑声，不能用来答应别人的请求。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示赞叹或惊奇，与“你能帮我拿一下吗”的答应不符。"}], "explanations": {"没问题": "“没问题”表示答应，与前一句的请求“你能帮我拿一下吗”相符。", "哎呀": "语义：“哎呀”表示惊讶或懊恼，不能用来答应别人的请求。", "哈哈": "语义：“哈哈”是笑声，不能用来答应别人的请求。", "哇": "语义：“哇”表示赞叹或惊奇，与“你能帮我拿一下吗”的答应不符。"}, "sentence_index": 0, "correct_answer": "没问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“我昨天忘了还你书，对不起。”“没问题。”", "explanation": "这里应该用〈没关系〉。没问题表示答应或确认可以，别人道歉后表示不介意要说〈没关系〉。"}, {"text": "“我想请你帮忙，你能同意吗？”“没问题，我不同意。”", "explanation": "这里应该用〈不行〉。没问题表示答应，后面不能接拒绝的话。"}, {"text": "“2加2等于几？”“没问题。”", "explanation": "这里应该直接回答〈四〉。没问题表示答应或确认可以，不能用来回答计算题的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没问题", "is_correct": true, "explanation": "“没问题”表示答应，与老师的提问“你们能按时交作业吗”相符。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或突然惊讶，不能用来回答老师的提问。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是表示轻蔑的粗俗口语，用在对老师的回答中极不得体。"}, {"text": "天哪", "is_correct": false, "explanation": "语义：“天哪”表示惊叹，与“能按时交作业”的答应不符。"}], "explanations": {"没问题": "“没问题”表示答应，与老师的提问“你们能按时交作业吗”相符。", "哎哟": "语义：“哎哟”表示疼痛或突然惊讶，不能用来回答老师的提问。", "呸": "语域：“呸”是表示轻蔑的粗俗口语，用在对老师的回答中极不得体。", "天哪": "语义：“天哪”表示惊叹，与“能按时交作业”的答应不符。"}, "sentence_index": 6, "correct_answer": "没问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“这件事我做不到，没问题。”", "explanation": "这里应该用〈不行〉。没问题表示答应，不能用来拒绝对方的请求。"}, {"text": "你中了大奖！没问题！", "explanation": "这里表示惊喜，应该用〈哇〉这类感叹词。没问题只用于答应或确认。"}, {"text": "你看，外面下雪了！没问题！", "explanation": "这里表示惊叹，应该用〈哇〉。没问题表示答应或不用担心，不能用来表达惊奇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“明天下午能来开会吗？”“不没问题，我会准时到。”", "corrected_sentence": "“明天下午能来开会吗？”“没问题，我会准时到。”", "error_description": "双重否定错误：“没问题”前面不能再加“不”，应直接说“没问题”，不能说“不没问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“我想借用一下你的相机，可以吗？”“很没问题，你拿去用吧。”", "corrected_sentence": "“我想借用一下你的相机，可以吗？”“没问题，你拿去用吧。”", "error_description": "“没问题”作答应语时前面不能加“很”。这里的“很”多余，应删去，写作“没问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
