INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "事物或事情没有毛病、没有困难。", "primary_collocate": null, "pronunciation": "méi wèn tí", "ipa": "mei˧˥ wən˥˩ tʰi˧˥", "syllable_count": 3, "sentences": [{"text": "医生说你的身体没问题。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑没问题，可以放心用。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别担心，这次考试对你来说没问题。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我检查过了，这辆车没问题。", "target_word": "没问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要认真学，你的汉语一定没问题。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法完全没问题，不用改。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同我看了，没问题，可以签字。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子一个人坐火车去外婆家，没问题吗？", "target_word": "没问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上时间够用，赶飞机没问题。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说这个办法没问题，大家照做吧。", "target_word": "没问题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有问题", "label": "完整形式"}, {"form": "沒問題", "label": "繁体"}], "register": "口语", "sense_fingerprint": "没问题|事物或事情没有毛病、没有困难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没问题", "is_correct": true, "explanation": "“没问题”表示没有毛病，与医生检查后的结论相符。"}, {"text": "输了", "is_correct": false, "explanation": "语义：“输了”说的是比赛或竞争失败，不能用来描述身体的检查结果。"}, {"text": "赚了", "is_correct": false, "explanation": "搭配：身体不能“赚”，与“医生说你的身体”搭配不当。"}, {"text": "迷路", "is_correct": false, "explanation": "配价：“迷路”要求人作主语，不能说身体迷路。"}], "explanations": {"没问题": "“没问题”表示没有毛病，与医生检查后的结论相符。", "输了": "语义：“输了”说的是比赛或竞争失败，不能用来描述身体的检查结果。", "赚了": "搭配：身体不能“赚”，与“医生说你的身体”搭配不当。", "迷路": "配价：“迷路”要求人作主语，不能说身体迷路。"}, "sentence_index": 0, "correct_answer": "没问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他考了零分，他的成绩没问题。", "explanation": "这里应该用〈不好〉或〈有问题〉。没问题表示没有毛病，考了零分的成绩不能说没问题。"}, {"text": "他的作业写得乱七八糟，字迹也看不清，没问题。", "explanation": "这里应该用〈有问题〉。没问题表示没有毛病，作业乱七八糟时不能说没问题。"}, {"text": "这台洗衣机一直漏水，没问题。", "explanation": "这里应该用〈有问题〉。没问题表示没有毛病，有明显故障时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没问题", "is_correct": true, "explanation": "“没问题”表示没有毛病，与“我看了”“可以签字”相符。"}, {"text": "不通过", "is_correct": false, "explanation": "语义：“不通过”表示不合格，与“可以签字”矛盾。"}, {"text": "作废", "is_correct": false, "explanation": "语义：“作废”表示合同失效，与“可以签字”矛盾。"}, {"text": "撕掉", "is_correct": false, "explanation": "配价：“撕掉”需要带宾语，这里缺少宾语，而且与“可以签字”矛盾。"}], "explanations": {"没问题": "“没问题”表示没有毛病，与“我看了”“可以签字”相符。", "不通过": "语义：“不通过”表示不合格，与“可以签字”矛盾。", "作废": "语义：“作废”表示合同失效，与“可以签字”矛盾。", "撕掉": "配价：“撕掉”需要带宾语，这里缺少宾语，而且与“可以签字”矛盾。"}, "sentence_index": 6, "correct_answer": "没问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我只得了二十分，我却说：“没问题。”", "explanation": "这里应该用〈糟糕〉。没问题表示没有毛病，不能用来说自己考砸的成绩。"}, {"text": "“我把你的伞弄坏了，对不起。”“没问题。”", "explanation": "这里应该用〈没关系〉。没问题表示事物没有毛病或答应，道歉后应说〈没关系〉。"}, {"text": "他看到摔坏的手机，笑着说：“没问题。”", "explanation": "这里应该用〈糟糕〉或〈坏了〉。没问题表示没有毛病，摔坏的手机不能说没问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告我看过了，数据不没问题。", "corrected_sentence": "这份报告我看过了，数据没问题。", "error_description": "“没问题”已用“没”表示否定，前面再加“不”构成双重否定，不符合汉语习惯。应删去“不”，写作“数据没问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器我检查过了，运行很没问题。", "corrected_sentence": "这台机器我检查过了，运行没问题。", "error_description": "“没问题”作谓语表示没有毛病，前面不能加“很”。应删去“很”，写作“运行没问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
