INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "病毒是一种特别小的东西，能让人生病。", "primary_collocate": null, "pronunciation": "bìng dú", "ipa": "piŋ˥˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "这种病毒会让人发烧咳嗽。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我感染了一种病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧是因为病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒很小，眼睛看不见。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒让很多人生病了。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天人多的地方，病毒很容易传播。", "target_word": "病毒", "complexity_tier": "T3", "furigana": "dōng tiān rén duō de dì fāng bìng dú hěn róng yì chuán bō", "sentence_source": "generated"}, {"text": "勤洗手可以挡住病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕把病毒带回家。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒从哪儿来的？医生也不清楚。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们戴着口罩，不让病毒进来。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种病毒", "label": "量词"}, {"form": "流感病毒", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常说法：看不见的很小的东西，会让人生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病毒", "is_correct": true, "explanation": "“病毒”是会让人发烧咳嗽的很小的东西，与句意相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会让人发烧咳嗽，与句意矛盾。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”是抽象概念，不能作为致病的主语，与“让人发烧咳嗽”不搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会让人发烧咳嗽，与句意矛盾。"}], "explanations": {"病毒": "“病毒”是会让人发烧咳嗽的很小的东西，与句意相符。", "电脑": "语义：电脑不会让人发烧咳嗽，与句意矛盾。", "感情": "搭配：“感情”是抽象概念，不能作为致病的主语，与“让人发烧咳嗽”不搭配。", "桌子": "语义：桌子不会让人发烧咳嗽，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "病毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病毒昨天吃了一碗饭。", "explanation": "这里不能用〈病毒〉，应该用〈病人〉。“吃饭”的主语应是人或动物，病毒不能吃饭。"}, {"text": "我口渴了，想喝一杯病毒。", "explanation": "这里不能用〈病毒〉，应该用〈水〉。病毒是让人生病的很小的东西，不能拿来喝。"}, {"text": "我在显微镜下看见一只病毒。", "explanation": "这里不能用〈只〉。〈只〉多用于动物，病毒应该用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病毒", "is_correct": true, "explanation": "“挡住”的对象应是病毒这类能让人生病的很小的东西，与句意相符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：勤洗手不能挡住雨水，句意不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：勤洗手不能挡住阳光，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“挡住”一般用于有形的东西或侵害，不能挡住“时间”。"}], "explanations": {"病毒": "“挡住”的对象应是病毒这类能让人生病的很小的东西，与句意相符。", "雨水": "语义：勤洗手不能挡住雨水，句意不通。", "阳光": "语义：勤洗手不能挡住阳光，句意不通。", "时间": "搭配：“挡住”一般用于有形的东西或侵害，不能挡住“时间”。"}, "sentence_index": 6, "correct_answer": "病毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士每天都会照顾那个病毒。", "explanation": "这里应该用〈病人〉。“照顾”的对象通常是人或有生命的动物、植物；病毒不能被照顾。"}, {"text": "医生说这里有一条病毒。", "explanation": "这里不能用〈条〉。〈条〉多用于细长的东西，病毒应该用〈种〉或〈个〉。"}, {"text": "他手里拿着一支病毒。", "explanation": "这里不能用〈支〉。〈支〉多用于杆状物等，病毒应该用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹昨天感染了一只病毒。", "corrected_sentence": "妹妹昨天感染了一种病毒。", "error_description": "“病毒”前的量词用错：“只”用于动物，不能用于病毒。应改为“种”（或“个”）：“妹妹昨天感染了一种病毒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些病毒们都很小，眼睛看不见。", "corrected_sentence": "这些病毒都很小，眼睛看不见。", "error_description": "“们”用错了：“们”一般用于指人，不能加在“病毒”后面。应删去“们”：“这些病毒都很小，眼睛看不见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
