INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比细菌更小的微生物，能引起疾病。", "primary_collocate": null, "pronunciation": "bìng dú", "ipa": "piŋ˥˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "病毒比细菌还要小很多。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒要在活细胞里才能生长。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用电子显微镜看病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗生素能杀死细菌，杀不死病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病毒的结构很简单。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究新的病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒会不断变化，所以疫苗要更新。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒不是细菌，是更小的微生物。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫苗可以帮身体对付病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里保存着一种危险的病毒。", "target_word": "病毒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种病毒", "label": "量词"}, {"form": "流感病毒", "label": "复合"}], "register": "中性", "sense_fingerprint": "科学说法：比细菌更小、要寄生在活细胞里的微生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7673fbc5-6e78-4bef-848b-ae27656be33f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病毒", "is_correct": true, "explanation": "“病毒”比细菌还要小，符合科学常识。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象比细菌大得多，不可能比细菌还要小。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”没有大小，不能用“小”来比较体积。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子远比细菌大，与句意相反。"}], "explanations": {"病毒": "“病毒”比细菌还要小，符合科学常识。", "大象": "语义：大象比细菌大得多，不可能比细菌还要小。", "颜色": "搭配：“颜色”没有大小，不能用“小”来比较体积。", "房子": "语义：房子远比细菌大，与句意相反。"}, "sentence_index": 0, "correct_answer": "病毒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病毒在培养皿里能自己分裂，很快就变多了。", "explanation": "这里应该用〈细菌〉。细菌能在培养基里自己分裂繁殖；病毒必须寄生在活细胞里才能增殖，不能自己分裂。"}, {"text": "病毒能识别并结合入侵的病原体。", "explanation": "这里应该用〈抗体〉。抗体由免疫系统产生，专门识别并结合入侵的病原体；病毒不具备这种免疫功能。"}, {"text": "科学家在培养皿里发现了一只病毒。", "explanation": "这里不能用〈只〉。〈只〉多用于动物，病毒应该用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病毒", "is_correct": true, "explanation": "“病毒”会不断变化，所以疫苗要更新，符合事实。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气变化与疫苗要更新之间没有因果关系，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格变化与疫苗更新无关，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”一般不会“不断变化”，这样搭配不当。"}], "explanations": {"病毒": "“病毒”会不断变化，所以疫苗要更新，符合事实。", "天气": "语义：天气变化与疫苗要更新之间没有因果关系，句意不通。", "价格": "语义：价格变化与疫苗更新无关，句意不通。", "桌子": "搭配：“桌子”一般不会“不断变化”，这样搭配不当。"}, "sentence_index": 6, "correct_answer": "病毒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说他的病毒比昨天好转了很多。", "explanation": "这里不能用〈病毒〉，应该用〈病情〉。“好转”说的是病人的病情，不能用来说病毒本身。"}, {"text": "实验室里保存着一条危险的病毒。", "explanation": "这里不能用〈条〉。〈条〉多用于细长的东西，病毒应该用〈种〉或〈个〉。"}, {"text": "实验室里保存着一支危险的病毒。", "explanation": "这里不能用〈支〉。〈支〉多用于杆状物等，病毒应该用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些病毒们都在活细胞里繁殖。", "corrected_sentence": "这些病毒都在活细胞里繁殖。", "error_description": "“们”用错了：“们”只用于指人，不能加在“病毒”后面。应删去“们”，说“这些病毒都在活细胞里繁殖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条致命的病毒很难被杀死。", "corrected_sentence": "这种致命的病毒很难被杀死。", "error_description": "量词用错：“条”多用于细长的东西，不用于病毒。应改为“种”：“这种致命的病毒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf7ce71-ddfc-406e-88fa-d631d3cd9ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
