INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要是心里希望得到一样东西。", "primary_collocate": null, "pronunciation": "xiǎng yào", "ipa": "ɕjɑŋ˨˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我想要一杯热茶。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想要一个新玩具。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要什么生日礼物？", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要一辆红色的自行车。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹想要一只小狗。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想要太多钱。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要哪个颜色的衣服？", "target_word": "想要", "complexity_tier": "T3", "furigana": "nǐ xiǎng yào nǎ ge yán sè de yī fu", "sentence_source": "generated"}, {"text": "小明过生日，想要一个大蛋糕。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要一本中文词典。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人想要一张大桌子。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不想要", "label": "否定"}], "register": "中性", "sense_fingerprint": "心里希望得到某样东西，后接名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认识", "is_correct": false, "explanation": "语义：“认识”的宾语应是人或事情，不能说“认识一杯热茶”。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受者和物品两个成分，“我送给一杯热茶”缺少接受者。"}, {"text": "想要", "is_correct": true, "explanation": "“想要”表示心里希望得到某样东西，与“一杯热茶”搭配。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”的对象应是人，“一杯热茶”不能被拥抱。"}], "explanations": {"认识": "语义：“认识”的宾语应是人或事情，不能说“认识一杯热茶”。", "送给": "配价：“送给”需要接受者和物品两个成分，“我送给一杯热茶”缺少接受者。", "想要": "“想要”表示心里希望得到某样东西，与“一杯热茶”搭配。", "拥抱": "语义：“拥抱”的对象应是人，“一杯热茶”不能被拥抱。"}, "sentence_index": 0, "correct_answer": "想要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很想要家，常常给妈妈打电话。", "explanation": "这里应该用〈思念〉。“想要”表示希望得到某样东西，不能用来表示惦记家人；惦记亲人要用“思念”。"}, {"text": "我想要奶奶，所以常常去看她。", "explanation": "这里应该用〈思念〉。“想要”表示希望得到某样东西，不能用来表示惦记亲人；惦记亲人要用“思念”。"}, {"text": "我想要一个小时，就能把作业做完。", "explanation": "这里应该用〈需要〉。“想要”后接想得到的东西或想做的事，表示所花的时间要用“需要”，不能说“想要一个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲", "is_correct": false, "explanation": "语义：“讲”的宾语应是话语，不能说“讲哪个颜色的衣服”。"}, {"text": "认为", "is_correct": false, "explanation": "配价：“认为”后接的是小句或“是”字结构，不能直接带名词短语“哪个颜色的衣服”。"}, {"text": "想要", "is_correct": true, "explanation": "“想要”表示希望得到某样东西，与“哪个颜色的衣服”搭配，构成询问。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成意见，不能用来选取衣服。"}], "explanations": {"讲": "语义：“讲”的宾语应是话语，不能说“讲哪个颜色的衣服”。", "认为": "配价：“认为”后接的是小句或“是”字结构，不能直接带名词短语“哪个颜色的衣服”。", "想要": "“想要”表示希望得到某样东西，与“哪个颜色的衣服”搭配，构成询问。", "同意": "语义：“同意”表示赞成意见，不能用来选取衣服。"}, "sentence_index": 6, "correct_answer": "想要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想要一个小时，就能把饭做好。", "explanation": "这里应该用〈需要〉。“想要”后接想得到的东西，时间不能作为想得到的对象；说需要的时间要用“需要”。"}, {"text": "我想要这个想法很好。", "explanation": "这里应该用〈觉得〉。“想要”表示希望得到某样东西，不能用来对事情作评价；应说“我觉得这个想法很好”。"}, {"text": "这个问题我想要了很久，还是不明白。", "explanation": "这里应该用〈想〉。“想要”表示希望得到某样东西，不表示思考；思考问题要说“想了很久”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹想要着一只小猫，可是妈妈不同意。", "corrected_sentence": "妹妹想要一只小猫，可是妈妈不同意。", "error_description": "错误：“想要”后面多加了“着”。“想要”表示希望得到某样东西，不能带“着”；应说“妹妹想要一只小猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的弟弟想要了一个玩具。", "corrected_sentence": "我的弟弟想要一个玩具。", "error_description": "错误：“想要”后面多加了“了”。“想要”表示希望得到某样东西，句中不需要完成标记“了”；应说“我的弟弟想要一个玩具。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
