INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "希望得到或希望做到；打算。", "primary_collocate": null, "pronunciation": "xiǎng yào", "ipa": "ɕjɑŋ˨˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我想要学好中文。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想要去北京工作。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要买一个新手机，可是钱不够。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想要早点儿到家。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要做什么工作？", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想要自己做作业。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想要明年去中国旅游。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要把这本书看完。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想要我们多说中文。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想要当医生，所以认真学习。", "target_word": "想要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不想要", "label": "否定"}], "register": "中性", "sense_fingerprint": "希望做成某事、打算做某事，后接动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7ebaaf2-ff86-4acd-81d5-d33d40a45ed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生病", "is_correct": false, "explanation": "配价：“生病”是不及物动词，不能带“学好中文”作宾语。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”的宾语应是具体的事物，不能说“拥有学好中文”。"}, {"text": "想要", "is_correct": true, "explanation": "“想要”表示希望或打算做某事，后接动词短语“学好中文”。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”一般接任务、工作，不说“完成学好中文”。"}], "explanations": {"生病": "配价：“生病”是不及物动词，不能带“学好中文”作宾语。", "拥有": "语义：“拥有”的宾语应是具体的事物，不能说“拥有学好中文”。", "想要": "“想要”表示希望或打算做某事，后接动词短语“学好中文”。", "完成": "搭配：“完成”一般接任务、工作，不说“完成学好中文”。"}, "sentence_index": 0, "correct_answer": "想要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想要一个小时，就能把作业做完。", "explanation": "这里应该用〈需要〉。“想要”后接想做的事或想得到的东西，表示所花的时间要用“需要”，不能说“想要一个小时”。"}, {"text": "我想要奶奶，所以常常去看她。", "explanation": "这里应该用〈思念〉。“想要”表示打算或希望做某事，不能用来表示惦记亲人；惦记亲人要用“思念”。"}, {"text": "这道题我想要了半天，还是不会做。", "explanation": "这里应该用〈想〉。“想要”表示打算或希望做某事，不表示思考；思考题目要说“想了半天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挂", "is_correct": false, "explanation": "语义：“挂”不能带“明年去中国旅游”这样的动词短语作宾语，句子不通。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”表示用手取物，不能与“明年去中国旅游”搭配。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语，“我哭明年去中国旅游”不成立。"}, {"text": "想要", "is_correct": true, "explanation": "“想要”表示打算做某事，与“明年去中国旅游”搭配。"}], "explanations": {"挂": "语义：“挂”不能带“明年去中国旅游”这样的动词短语作宾语，句子不通。", "拿": "语义：“拿”表示用手取物，不能与“明年去中国旅游”搭配。", "哭": "配价：“哭”是不及物动词，不能带宾语，“我哭明年去中国旅游”不成立。", "想要": "“想要”表示打算做某事，与“明年去中国旅游”搭配。"}, "sentence_index": 6, "correct_answer": "想要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想要半个小时，就能把菜做好。", "explanation": "这里应该用〈需要〉。“想要”后接想得到的东西，时间不能作为想得到的对象；说需要的时间要用“需要”。"}, {"text": "我想要奶奶，所以常常给她打电话。", "explanation": "这里应该用〈思念〉。“想要”表示打算或希望做某事，不能用来表示惦记亲人；惦记亲人要用“思念”。"}, {"text": "我想要这个想法很好，所以赞成它。", "explanation": "这里应该用〈觉得〉。“想要”表示打算或希望做某事，不能用来对事情作评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想要着早点儿回国。", "corrected_sentence": "他们想要早点儿回国。", "error_description": "错误：“想要”后面多加了“着”。“想要”表示打算做某事，不能带“着”；应说“他们想要早点儿回国。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈想要了把房子卖掉。", "corrected_sentence": "妈妈想要把房子卖掉。", "error_description": "错误：“想要”后面多加了“了”。“想要”表示打算做某事，句中不需要“了”；应说“妈妈想要把房子卖掉。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b98cb1a-b764-4cf7-8b0f-bea141ae3341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
