INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86702, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或指头压住；往下压。", "primary_collocate": null, "pronunciation": "àn", "ipa": "an˥˩", "syllable_count": 1, "sentences": [{"text": "他用手指按住伤口，血很快停了。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你按住这张纸，别让风吹走。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明按了一下琴键，发出一个声音。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻地按着太阳穴，想休息一下。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把他按在地上，他动不了。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用力按下去，盖子就关好了。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按了几次，电视还是打不开。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按住这个键，三秒以后再放开。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指按住嘴唇，示意大家别出声。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按着帽子，在大风里走得很慢。", "target_word": "按", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "按了", "label": "完成体"}, {"form": "按着", "label": "持续体"}, {"form": "按过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "用手或指头压住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0727280a-acea-49ed-8e15-f9af5e9803df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86702, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "按", "is_correct": true, "explanation": "正确：按，用手或指头压住。"}, {"text": "安", "is_correct": false, "explanation": "ān 与 àn 声调不同（一声与四声），安的意思是平安。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 àn 相比多了声母 f，饭的意思是米饭。"}, {"text": "难", "is_correct": false, "explanation": "nàn 与 àn 相比多了声母 n，难的意思是灾难或困难。"}, {"text": "炭", "is_correct": false, "explanation": "tàn 与 àn 相比多了声母 t，炭的意思是木炭。"}], "explanations": {"按": "正确：按，用手或指头压住。", "安": "ān 与 àn 声调不同（一声与四声），安的意思是平安。", "饭": "fàn 与 àn 相比多了声母 f，饭的意思是米饭。", "难": "nàn 与 àn 相比多了声母 n，难的意思是灾难或困难。", "炭": "tàn 与 àn 相比多了声母 t，炭的意思是木炭。"}, "sentence_index": null, "correct_answer": "按"}, "level_3": {"options": [{"text": "按", "is_correct": true, "explanation": "正确：按住，用手指压住伤口，符合“血很快停了”的语境。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是割开，与止血的意思相反。"}, {"text": "吹", "is_correct": false, "explanation": "语义：吹是对着伤口吹气，吹气不能让血很快停下，与“血很快停了”不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱不能用于伤口，搭配不当。"}], "explanations": {"按": "正确：按住，用手指压住伤口，符合“血很快停了”的语境。", "切": "语义：切是割开，与止血的意思相反。", "吹": "语义：吹是对着伤口吹气，吹气不能让血很快停下，与“血很快停了”不符。", "唱": "搭配：唱不能用于伤口，搭配不当。"}, "sentence_index": 0, "correct_answer": "按"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给客人按了一杯茶。", "explanation": "这里应该用〈倒〉。按是往下压，给客人倒茶要用“倒”。"}, {"text": "他按了一把米，放进锅里。", "explanation": "这里应该用〈抓〉。按是压，抓一把米要用“抓”。"}, {"text": "她给花按了一些水。", "explanation": "这里应该用〈浇〉。按是压，给花浇水要用“浇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86702, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "按", "is_correct": true, "explanation": "正确：按，用手或指头压住。"}, {"text": "办", "is_correct": false, "explanation": "bàn 与 àn 相比多了声母 b，办的意思是办理。"}, {"text": "汗", "is_correct": false, "explanation": "hàn 与 àn 相比多了声母 h，汗的意思是汗水。"}, {"text": "烂", "is_correct": false, "explanation": "làn 与 àn 相比多了声母 l，烂的意思是腐烂或破碎。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn 与 àn 相比多了声母 d，蛋的意思是鸡蛋。"}], "explanations": {"按": "正确：按，用手或指头压住。", "办": "bàn 与 àn 相比多了声母 b，办的意思是办理。", "汗": "hàn 与 àn 相比多了声母 h，汗的意思是汗水。", "烂": "làn 与 àn 相比多了声母 l，烂的意思是腐烂或破碎。", "蛋": "dàn 与 àn 相比多了声母 d，蛋的意思是鸡蛋。"}, "sentence_index": null, "correct_answer": "按"}, "level_3": {"options": [{"text": "按", "is_correct": true, "explanation": "正确：按，用手或指头压住，符合“电视还是打不开”的语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱用于歌曲，不能与电视的操作搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是进食，与电视无关。"}, {"text": "读", "is_correct": false, "explanation": "配价：读的对象是文字，电视不能作为读的对象。"}], "explanations": {"按": "正确：按，用手或指头压住，符合“电视还是打不开”的语境。", "唱": "搭配：唱用于歌曲，不能与电视的操作搭配。", "吃": "语义：吃是进食，与电视无关。", "读": "配价：读的对象是文字，电视不能作为读的对象。"}, "sentence_index": 6, "correct_answer": "按"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按着一口气，跑了很远都没停下。", "explanation": "这里应该用〈憋〉。按是用手压，屏住一口气要用“憋”。"}, {"text": "他在商店按了一件新衣服，准备明天穿。", "explanation": "这里应该用〈买〉。按是用手往下压，买东西要用“买”。"}, {"text": "他按了一片叶子，夹进书里。", "explanation": "这里应该用〈摘〉。按是压，摘叶子要用“摘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈按了住我的手，不让我动。", "corrected_sentence": "妈妈按住了我的手，不让我动。", "error_description": "补语位置错误：“按住”是结果补语，“了”应放在“住”之后，应说“按住了”，不能说“按了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她按了着孩子的头，不让他乱动。", "corrected_sentence": "她按着孩子的头，不让他乱动。", "error_description": "体标错误：“按着”表示持续，不能与“了”同时用在同一动词上，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7826ac8e-eb2c-4f1d-9120-80ce4bc6347b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
