INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "象是又高又大的动物，有长长的鼻子。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "动物园里有狮子、老虎和象。", "target_word": "象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "象属于哺乳动物，耳朵很大。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "非洲草原上生活着斑马、长颈鹿和象。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "象的鼻子很长，可以用来喝水。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "动物学家研究了象的生活习性。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "象的体形又高又大，性格却很温和。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "这本书的插图里画着象和长颈鹿。", "target_word": "象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "象每天要吃很多草和水果。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "象走得慢，但是力气很大。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}, {"text": "象很聪明，会用鼻子喝水。", "target_word": "象", "complexity_tier": "T3", "furigana": "xiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "头", "label": "量词"}, {"form": "大象", "label": "复合"}], "register": "中性", "sense_fingerprint": "动物园里常见的高大长鼻子动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "象", "is_correct": true, "explanation": "正确：象 xiàng（第四声）指大象，是动物园里常见的高大哺乳动物。"}, {"text": "香", "is_correct": false, "explanation": "香 xiāng（第一声）与 xiàng 声调不同，意思是香味。"}, {"text": "想", "is_correct": false, "explanation": "想 xiǎng（第三声）与 xiàng 声调不同，意思是想念。"}, {"text": "响", "is_correct": false, "explanation": "响 xiǎng（第三声）与 xiàng 声调不同，意思是声音大。"}, {"text": "乡", "is_correct": false, "explanation": "乡 xiāng（第一声）与 xiàng 声调不同，意思是乡村。"}], "explanations": {"象": "正确：象 xiàng（第四声）指大象，是动物园里常见的高大哺乳动物。", "香": "香 xiāng（第一声）与 xiàng 声调不同，意思是香味。", "想": "想 xiǎng（第三声）与 xiàng 声调不同，意思是想念。", "响": "响 xiǎng（第三声）与 xiàng 声调不同，意思是声音大。", "乡": "乡 xiāng（第一声）与 xiàng 声调不同，意思是乡村。"}, "sentence_index": null, "correct_answer": "象"}, "level_3": {"options": [{"text": "象", "is_correct": true, "explanation": "正确：“狮子、老虎”并列指动物，空格处应是同类的动物“象”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是动物，不能与狮子、老虎一起作为动物园里的动物。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“狮子、老虎和……”要求并列同类，“桌子”不能与动物并列。"}, {"text": "花", "is_correct": false, "explanation": "语义：花是植物，不属于动物园里的动物。"}], "explanations": {"象": "正确：“狮子、老虎”并列指动物，空格处应是同类的动物“象”。", "汽车": "语义：汽车不是动物，不能与狮子、老虎一起作为动物园里的动物。", "桌子": "搭配：“狮子、老虎和……”要求并列同类，“桌子”不能与动物并列。", "花": "语义：花是植物，不属于动物园里的动物。"}, "sentence_index": 0, "correct_answer": "象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这座城市的象很好。", "explanation": "这里应该用〈印象〉。“象”指动物，表示对事物的感受要用“印象”，单用“象”说不通。"}, {"text": "这个道理太象了，我听不懂。", "explanation": "这里应该用〈抽象〉。“象”单用指动物，表示不具体、难理解要用“抽象”。"}, {"text": "今天的象很好，适合去郊游。", "explanation": "这里应该用〈气象〉。“象”单用指动物，说天气状况要用“气象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86703, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "象", "is_correct": true, "explanation": "正确：象 xiàng（第四声）指大象，是体形高大的哺乳动物。"}, {"text": "详", "is_correct": false, "explanation": "详 xiáng（第二声）与 xiàng 声调不同，意思是详细。"}, {"text": "祥", "is_correct": false, "explanation": "祥 xiáng（第二声）与 xiàng 声调不同，意思是吉祥。"}, {"text": "厢", "is_correct": false, "explanation": "厢 xiāng（第一声）与 xiàng 声调不同，意思是车厢。"}], "explanations": {"象": "正确：象 xiàng（第四声）指大象，是体形高大的哺乳动物。", "详": "详 xiáng（第二声）与 xiàng 声调不同，意思是详细。", "祥": "祥 xiáng（第二声）与 xiàng 声调不同，意思是吉祥。", "厢": "厢 xiāng（第一声）与 xiàng 声调不同，意思是车厢。"}, "sentence_index": null, "correct_answer": "象"}, "level_3": {"options": [{"text": "象", "is_correct": true, "explanation": "正确：“画着”的对象是可以入画的具体动物，“象”与“长颈鹿”并列，符合插图的语境。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，不能被画在插图里。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画着”与具体可见的事物搭配，“味道”是抽象感受，不能画出来。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间词，不是可以画在插图里的具体事物。"}], "explanations": {"象": "正确：“画着”的对象是可以入画的具体动物，“象”与“长颈鹿”并列，符合插图的语境。", "声音": "语义：声音看不见，不能被画在插图里。", "味道": "搭配：“画着”与具体可见的事物搭配，“味道”是抽象感受，不能画出来。", "星期": "语义：星期是时间词，不是可以画在插图里的具体事物。"}, "sentence_index": 6, "correct_answer": "象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在观众心中的象很好。", "explanation": "这里应该用〈形象〉。“象”单用不指人的形象，表示形象要用“形象”。"}, {"text": "我和爸爸下了一盘象。", "explanation": "这里应该用〈象棋〉。“象”单用指动物，下棋要说“象棋”。"}, {"text": "草原上出现了一种奇怪的象。", "explanation": "这里应该用〈现象〉。“象”指动物，指可以观察到的事物表现要用“现象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位象的耳朵很大。", "corrected_sentence": "那头象的耳朵很大。", "error_description": "错误形式用量词“位”修饰大象，“位”专用于人（敬称）；指大象应用量词“头”，正确形式为“那头象的耳朵很大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那头象把草吃光着。", "corrected_sentence": "那头象把草吃光了。", "error_description": "错误形式用“着”表示“吃光”，“着”表示持续的状态，与表示动作完成的结果不符；动作完成应用“了”，正确形式为“那头象把草吃光了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
