INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86705, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "相当是说差不多到了很高的样子。", "primary_collocate": null, "pronunciation": "xiāng dāng", "ipa": "ɕi̯ɑŋ˥ tɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这家饭馆的菜相当好吃。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气相当冷。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得相当不错。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书相当有意思。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事相当满意。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子相当聪明。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试相当难。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑得相当快。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方相当安静。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这里相当熟悉。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，表示程度相当高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曾", "is_correct": false, "explanation": "体貌：“曾”表示过去经历，与“好吃”描述的现状不合。"}, {"text": "相当", "is_correct": true, "explanation": "正确：“相当好吃”表示程度较高，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“好吃”。"}, {"text": "将", "is_correct": false, "explanation": "语法：“将”表示将来，用在动词前，不能作程度副词修饰“好吃”。"}], "explanations": {"曾": "体貌：“曾”表示过去经历，与“好吃”描述的现状不合。", "相当": "正确：“相当好吃”表示程度较高，符合句意。", "被": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“好吃”。", "将": "语法：“将”表示将来，用在动词前，不能作程度副词修饰“好吃”。"}, "sentence_index": 0, "correct_answer": "相当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔钱相当一个月的工资。", "explanation": "这里应该用〈相当于〉。表示“等于、抵得上”时要说“相当于”，“相当”不能直接带数量名词作宾语。"}, {"text": "这个班相当三十人。", "explanation": "这里应该用〈共有〉。这里说的是人数，不是“相当”的程度义，应说“这个班共有三十人”。"}, {"text": "这本书相当很有意思。", "explanation": "语法：“相当”与“很”都是程度副词，不能叠用修饰“有意思”，应只保留“相当”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“难”这种性质不合。"}, {"text": "相当", "is_correct": true, "explanation": "正确：“相当难”表示程度较高，符合句意。"}, {"text": "正", "is_correct": false, "explanation": "体貌：“正”表示正在进行，“难”是性质，不能用进行态。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“难”。"}], "explanations": {"刚": "语义：“刚”表示刚刚发生，与“难”这种性质不合。", "相当": "正确：“相当难”表示程度较高，符合句意。", "正": "体貌：“正”表示正在进行，“难”是性质，不能用进行态。", "被": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“难”。"}, "sentence_index": 6, "correct_answer": "相当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这里相当于熟悉。", "explanation": "这里应该用〈非常〉。“相当于”表示等同，不能修饰形容词“熟悉”。"}, {"text": "我把这里相当成了家。", "explanation": "这里应该用〈当成〉。“相当”不表示把一处地方视作另一物，应说“当成”。"}, {"text": "我对这里相当得熟悉。", "explanation": "语法：“相当”是副词，直接修饰“熟悉”，中间不能加“得”，应说“相当熟悉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间相当于干净。", "corrected_sentence": "这个房间相当干净。", "error_description": "错误在于“相当于”：“相当于”表示等同、抵得上，不能修饰形容词。此处应去掉“于”，改为“相当干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的作业相当相当多。", "corrected_sentence": "今天的作业相当多。", "error_description": "错误在于“相当”重复出现。“相当”是程度副词，一个句子中只用一次，应删去多余的“相当”，改为“相当多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
