INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86706, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度较高，但不到“很”的程度；颇。", "primary_collocate": null, "pronunciation": "xiāng dāng", "ipa": "ɕi̯ɑŋ˥ tɑŋ˥", "syllable_count": 2, "sentences": [{"text": "路上的车相当多。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相当喜欢这份工作。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的价钱相当高。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的会开得相当长。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师相当受学生欢迎。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌唱得相当好听。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法相当有用。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的人相当少。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病相当重。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了相当远的路。", "target_word": "相当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，较高但不及“很”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曾", "is_correct": false, "explanation": "体貌：“曾”表示过去经历，与“车多”描述的现状不合。"}, {"text": "相当", "is_correct": true, "explanation": "正确：“相当多”表示程度较高，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“多”。"}, {"text": "将", "is_correct": false, "explanation": "语法：“将”表示将来，用在动词前，不能作程度副词修饰“多”。"}], "explanations": {"曾": "体貌：“曾”表示过去经历，与“车多”描述的现状不合。", "相当": "正确：“相当多”表示程度较高，符合句意。", "被": "语法：“被”用于被动句，后面需接动词，不能直接接形容词“多”。", "将": "语法：“将”表示将来，用在动词前，不能作程度副词修饰“多”。"}, "sentence_index": 0, "correct_answer": "相当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个会议的时长相当一天。", "explanation": "这里应该用〈相当于〉。表示等同、抵得上时要说“相当于”，“相当”不能直接带数量词。"}, {"text": "这件礼物相当一份心意。", "explanation": "这里应该用〈等于〉。此处表示等同，“相当”的程度义不适用于“一份心意”。"}, {"text": "昨天的会相当开得长。", "explanation": "语序：“相当”应放在“长”前，说“开得相当长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正", "is_correct": false, "explanation": "体貌：“正”表示正在进行，“有用”是性质，不能用进行态。"}, {"text": "相当", "is_correct": true, "explanation": "正确：“相当有用”表示程度较高，符合句意。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“有用”的稳定性质不合。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”表示否定，与“相当有用”的肯定意思相反。"}], "explanations": {"正": "体貌：“正”表示正在进行，“有用”是性质，不能用进行态。", "相当": "正确：“相当有用”表示程度较高，符合句意。", "刚": "语义：“刚”表示刚刚发生，与“有用”的稳定性质不合。", "不": "语义：“不”表示否定，与“相当有用”的肯定意思相反。"}, "sentence_index": 6, "correct_answer": "相当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们走了相当于远的路。", "explanation": "这里应该用〈很〉。“相当于”表示等同，不能修饰形容词“远”。"}, {"text": "我们走了相当得远的路。", "explanation": "语法：“相当”是副词，直接修饰“远”，中间不能加“得”。"}, {"text": "我们相当走了远的路。", "explanation": "语序：“相当”修饰的是“远”，应说“走了相当远的路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题相当于难。", "corrected_sentence": "这道题相当难。", "error_description": "错误在于“相当于”：“相当于”表示等同、抵得上，不能修饰形容词“难”。此处应去掉“于”，改为“相当难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书相当相当有意思。", "corrected_sentence": "这本书相当有意思。", "error_description": "错误在于“相当”重复出现。“相当”是程度副词，一个句子中只用一次，应删去多余的“相当”，改为“相当有意思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断", "is_correct": true, "explanation": "“断”指断开、不再相连，与“通到”相对。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”与“通到”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“通到”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“通到”没有反义关系。"}], "correct_answer": "断", "explanations": {"断": "“断”指断开、不再相连，与“通到”相对。", "跳": "“跳”与“通到”没有反义关系。", "睡": "“睡”与“通到”没有反义关系。", "写": "“写”与“通到”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
