INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通是一头到另一头，没有被堵住。", "primary_collocate": null, "pronunciation": "tōng", "ipa": "tʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这条路通到海边。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河通到大海。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条小路一直通到山上。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地铁已经通到我家附近了。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个隧道从山的这边通到那边。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那条铁路通到北方的一个小城。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥修好以后，我们村和城里就通了。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路下面有个地道，可以通到对面的商场。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的小路很多，但是只有一条通到村子。", "target_word": "通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条走廊很长，一直通到房子后面的小院。", "target_word": "通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通了", "label": "体标"}, {"form": "畅通", "label": "复合"}, {"form": "打通", "label": "复合"}], "register": "中性", "sense_fingerprint": "从一头到另一头相连、没有被堵住，常说通到某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：通（tōng，第一声），意思是从一头到另一头相连。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是相同。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 tōng（第一声）声调不同，意思是疼。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 tōng 韵母不同（a 与 o），意思是汤。"}, {"text": "听", "is_correct": false, "explanation": "tīng 与 tōng 韵母不同（i 与 o），意思是听见。"}, {"text": "偷", "is_correct": false, "explanation": "tōu 与 tōng 韵母不同（ou 与 ong），意思是偷东西。"}], "explanations": {"通": "正确：通（tōng，第一声），意思是从一头到另一头相连。", "同": "tóng（第二声）与 tōng（第一声）声调不同，意思是相同。", "痛": "tòng（第四声）与 tōng（第一声）声调不同，意思是疼。", "汤": "tāng 与 tōng 韵母不同（a 与 o），意思是汤。", "听": "tīng 与 tōng 韵母不同（i 与 o），意思是听见。", "偷": "tōu 与 tōng 韵母不同（ou 与 ong），意思是偷东西。"}, "sentence_index": null, "correct_answer": "通"}, "level_3": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：“通到海边”表示道路从这里一直延伸到海边。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”的主语应是人或车，不能说“这条路跑到海边”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”与道路无关，“这条路唱到海边”搭配不当。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与“这条路到海边”的走向无关，句子意思不通。"}], "explanations": {"通": "正确：“通到海边”表示道路从这里一直延伸到海边。", "跑": "搭配：“跑”的主语应是人或车，不能说“这条路跑到海边”。", "唱": "搭配：“唱”与道路无关，“这条路唱到海边”搭配不当。", "写": "语义：“写”与“这条路到海边”的走向无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次通了面试，心里很高兴。", "explanation": "这里应该用〈通过〉。“通”没有面试合格的意思，通过面试要用“通过”。"}, {"text": "工人们在山上通了一个大坑。", "explanation": "这里应该用〈挖〉。“通”指没有阻塞，不能用来挖坑，挖坑要用“挖”。"}, {"text": "这扇门一直通着，大家都能进来。", "explanation": "这里应该用〈开〉。门打开要用“开”，“通”用于道路、管道等没有阻塞的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：通（tōng，第一声），意思是从一头到另一头相连。"}, {"text": "铜", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tōng（第一声）声调不同，意思是桶。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 tōng 声母不同（d 与 t），意思是东方。"}], "explanations": {"通": "正确：通（tōng，第一声），意思是从一头到另一头相连。", "铜": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜。", "桶": "tǒng（第三声）与 tōng（第一声）声调不同，意思是桶。", "东": "dōng 与 tōng 声母不同（d 与 t），意思是东方。"}, "sentence_index": null, "correct_answer": "通"}, "level_3": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：“这座桥修好以后，我们村和城里就通了”，表示道路连通。"}, {"text": "停", "is_correct": false, "explanation": "语义：“就停了”与前句“修好”矛盾，句子意思不对。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不用于两地之间的连通，“就烧了”搭配不当。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能表示两地连通，“我们村和城里就洗了”意思不通。"}], "explanations": {"通": "正确：“这座桥修好以后，我们村和城里就通了”，表示道路连通。", "停": "语义：“就停了”与前句“修好”矛盾，句子意思不对。", "烧": "搭配：“烧”不用于两地之间的连通，“就烧了”搭配不当。", "洗": "搭配：“洗”不能表示两地连通，“我们村和城里就洗了”意思不通。"}, "sentence_index": 6, "correct_answer": "通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们把那座旧房子通了。", "explanation": "这里应该用〈拆〉。“通”没有拆除的意思，拆掉旧房子要用“拆”。"}, {"text": "这家公司通了一批新员工。", "explanation": "这里应该用〈招〉。“通”没有招收的意思，招收员工要用“招”。"}, {"text": "我把文件通给了经理。", "explanation": "这里应该用〈交〉。“通”没有交付的意思，把东西交给别人要用“交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条新路到通村子东边了。", "corrected_sentence": "这条新路通到村子东边了。", "error_description": "“到”是补语，要放在“通”的后面，应说“通到村子东边”，不能说“到通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
