INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86708, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "没有阻塞，可以穿过。", "primary_collocate": null, "pronunciation": "tōng", "ipa": "tʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "前面在修路，这条路不通。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水管不通，水出不来。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的鼻子不通，很难受。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话一直不通，我很担心。", "target_word": "通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "修好以后，这条路就通了。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络不通，我不能在家开会。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后，山路不通，车都停在路边。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河以前不通船，现在可以走大船了。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话通了，可是对面没有人说话。", "target_word": "通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下的隧道通了，开车去城里只要半个小时。", "target_word": "通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通了", "label": "体标"}, {"form": "畅通", "label": "复合"}, {"form": "打通", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有阻塞，路、管道、线路等可以穿过、畅通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3100c7d4-8539-4c18-af4c-52368be70353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：通（tōng，第一声），意思是没有阻塞、可以穿过。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是相同。"}, {"text": "痛", "is_correct": false, "explanation": "tòng（第四声）与 tōng（第一声）声调不同，意思是疼。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 tōng 韵母不同（a 与 o），意思是汤。"}, {"text": "听", "is_correct": false, "explanation": "tīng 与 tōng 韵母不同（i 与 o），意思是听见。"}, {"text": "偷", "is_correct": false, "explanation": "tōu 与 tōng 韵母不同（ou 与 ong），意思是偷东西。"}], "explanations": {"通": "正确：通（tōng，第一声），意思是没有阻塞、可以穿过。", "同": "tóng（第二声）与 tōng（第一声）声调不同，意思是相同。", "痛": "tòng（第四声）与 tōng（第一声）声调不同，意思是疼。", "汤": "tāng 与 tōng 韵母不同（a 与 o），意思是汤。", "听": "tīng 与 tōng 韵母不同（i 与 o），意思是听见。", "偷": "tōu 与 tōng 韵母不同（ou 与 ong），意思是偷东西。"}, "sentence_index": null, "correct_answer": "通"}, "level_3": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：“不通”指道路被阻塞，与“前面在修路”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：路不能“吃”，“这条路不吃”搭配不当。"}, {"text": "停", "is_correct": false, "explanation": "搭配：路不会“停”，“这条路不停”搭配不当。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”的主语应是人或车，不能说“这条路不跑”。"}], "explanations": {"通": "正确：“不通”指道路被阻塞，与“前面在修路”相符。", "吃": "搭配：路不能“吃”，“这条路不吃”搭配不当。", "停": "搭配：路不会“停”，“这条路不停”搭配不当。", "跑": "搭配：“跑”的主语应是人或车，不能说“这条路不跑”。"}, "sentence_index": 0, "correct_answer": "通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次通了考试，心里很高兴。", "explanation": "这里应该用〈通过〉。“通”没有考试及格的意思，通过考试要用“通过”。"}, {"text": "工人们在院子里通了一个大坑。", "explanation": "这里应该用〈挖〉。“通”指没有阻塞，不能用来挖坑，挖坑要用“挖”。"}, {"text": "这次考试他的成绩通了很多。", "explanation": "这里应该用〈提高〉。“通”没有提高的意思，成绩进步要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：通（tōng，第一声），意思是没有阻塞、可以穿过。"}, {"text": "铜", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜。"}, {"text": "桶", "is_correct": false, "explanation": "tǒng（第三声）与 tōng（第一声）声调不同，意思是桶。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 tōng 声母不同（d 与 t），意思是东方。"}], "explanations": {"通": "正确：通（tōng，第一声），意思是没有阻塞、可以穿过。", "铜": "tóng（第二声）与 tōng（第一声）声调不同，意思是铜。", "桶": "tǒng（第三声）与 tōng（第一声）声调不同，意思是桶。", "东": "dōng 与 tōng 声母不同（d 与 t），意思是东方。"}, "sentence_index": null, "correct_answer": "通"}, "level_3": {"options": [{"text": "通", "is_correct": true, "explanation": "正确：“山路不通”指道路被大雪堵住，车只能停在路边。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”与“山路”无关，“山路不写”意思不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：路不能“吃”，“山路不吃”搭配不当。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于道路，“山路不唱”搭配不当。"}], "explanations": {"通": "正确：“山路不通”指道路被大雪堵住，车只能停在路边。", "写": "语义：“写”与“山路”无关，“山路不写”意思不通。", "吃": "搭配：路不能“吃”，“山路不吃”搭配不当。", "唱": "搭配：“唱”不能用于道路，“山路不唱”搭配不当。"}, "sentence_index": 6, "correct_answer": "通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的成绩通了一个大进步。", "explanation": "这里应该用〈取得〉。“通”没有取得的意思，要说“取得大进步”。"}, {"text": "我已经通了大家明天开会。", "explanation": "这里应该用〈通知〉。“通”单用没有告知的意思，告诉大家要用“通知”。"}, {"text": "货车通了一批水果到城里。", "explanation": "这里应该用〈运〉。“通”没有运送的意思，运送货物要用“运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路还不没通，车还不能开过去。", "corrected_sentence": "这条路还没通，车还不能开过去。", "error_description": "“还没通”表示尚未通，“没”不能再加“不”。“不没”是双重否定，错在多加了“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雪过后，山路终于通过了，车又能开了。", "corrected_sentence": "大雪过后，山路终于通了，车又能开了。", "error_description": "“通过”表示经过、经审批，不表示道路没有阻塞；这里应说“通了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa6461e6-920a-4182-a42e-c248a1792d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
