INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86709, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "终于是等了很久，事情最后发生了。", "primary_collocate": null, "pronunciation": "zhōng yú", "ipa": "ʈʂʊŋ˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "等了一个小时，车终于来了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天终于到了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于回家了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了三天，终于停了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于见面了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书我终于找到了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子终于睡着了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于打来了电话。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期终于来了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于说出了真话。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "等了很久，事情最后发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终于", "is_correct": true, "explanation": "正确答案。“等了一个小时”说明车是经过长时间等待后才到，“终于”正合语境。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定期地发生，与“等了一个小时”这一次性的等待相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与“车来了”这一次性的事件不符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去有过的经历，说车“曾经来了”与等待后车到达的情境不合。"}], "explanations": {"终于": "正确答案。“等了一个小时”说明车是经过长时间等待后才到，“终于”正合语境。", "偶尔": "语义：“偶尔”表示不定期地发生，与“等了一个小时”这一次性的等待相矛盾。", "总是": "语义：“总是”表示每次都如此，与“车来了”这一次性的事件不符。", "曾经": "体貌：“曾经”指过去有过的经历，说车“曾经来了”与等待后车到达的情境不合。"}, "sentence_index": 0, "correct_answer": "终于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚坐下，电话终于响了。", "explanation": "这里应该用〈就〉。终于表示等了很久之后才出现的结果，不能用于刚坐下、时间很短就出现的情况；表示紧接着发生时要用〈就〉。"}, {"text": "你终于想怎么样？", "explanation": "这里应该用〈到底〉。终于强调等待后已经出现的结果，不用于追问尚未明确的意图；追问时要用〈到底〉。"}, {"text": "这班车终于每天七点到站。", "explanation": "这里应该用〈总是〉。终于表示等待之后一次性出现的结果，不能用来描述每天重复的常规情况；说明反复出现时要用〈总是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终于", "is_correct": true, "explanation": "正确答案。“终于”表示经过一段时间后，孩子最终睡着了，与语境相合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：睡着是不自主的状态，不能“故意睡着”，与“睡着了”的结果相冲突。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”指白费力气或时间，句中并没有这样的含义。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰的是自主的动作，不能与“睡着”这种不自主的结果搭配。"}], "explanations": {"终于": "正确答案。“终于”表示经过一段时间后，孩子最终睡着了，与语境相合。", "故意": "语义：睡着是不自主的状态，不能“故意睡着”，与“睡着了”的结果相冲突。", "白白": "语义：“白白”指白费力气或时间，句中并没有这样的含义。", "亲自": "搭配：“亲自”修饰的是自主的动作，不能与“睡着”这种不自主的结果搭配。"}, "sentence_index": 6, "correct_answer": "终于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚一开口，他终于就答应了。", "explanation": "这里应该用〈立刻〉。终于表示经过较长等待后才出现的结果，不能用于刚开口就得到答复的情况；即时发生时要用〈立刻〉。"}, {"text": "他终于还年轻，你别太责怪他。", "explanation": "这里应该用〈毕竟〉。终于不用来说明原因；陈述理由、为对方开脱时要用〈毕竟〉。"}, {"text": "这件事我终于不知道。", "explanation": "这里应该用〈根本〉。终于表示经过等待后出现的结果，不能用来加强否定；强调完全不知道时要用〈根本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们走了很久，终于到山顶。", "corrected_sentence": "他们走了很久，终于到了山顶。", "error_description": "错误在于缺少“了”。“终于”表示事情最后已经发生，后面的动词通常要带“了”表示完成，应改为“终于到了山顶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们等了两个小时，他很终于回来了。", "corrected_sentence": "我们等了两个小时，他终于回来了。", "error_description": "错误在于“很”修饰了“终于”。“终于”不能被“很”修饰，应去掉“很”，改为“终于回来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
