INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示经过长时间或种种努力，最后出现某种结果。", "primary_collocate": null, "pronunciation": "zhōng yú", "ipa": "ʈʂʊŋ˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "经过努力，他终于考上了大学。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了三年，我终于会说汉语了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试了很多次，她终于成功了。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力工作，终于买了房子。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想了很多办法，终于解决了问题。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练了一年，他终于跑完了全程。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找了好几天，我终于找到了工作。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，终于完成了任务。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改了很多次，终于写好了这封信。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生想尽办法，终于治好了他的病。", "target_word": "终于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "经过努力，最后出现结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cbda021-f83f-46c6-a624-91478e347744') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终于", "is_correct": true, "explanation": "正确答案。“经过努力”之后出现结果，“终于”正表示这一过程的完成。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不定期地发生，与“经过努力”后考上大学这一结果不合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与一次努力后的结果相矛盾。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示侥幸或幸运，与前文强调的“努力”这一因果关系相冲突。"}], "explanations": {"终于": "正确答案。“经过努力”之后出现结果，“终于”正表示这一过程的完成。", "偶尔": "语义：“偶尔”表示不定期地发生，与“经过努力”后考上大学这一结果不合。", "总是": "语义：“总是”表示每次都如此，与一次努力后的结果相矛盾。", "幸好": "语义：“幸好”表示侥幸或幸运，与前文强调的“努力”这一因果关系相冲突。"}, "sentence_index": 0, "correct_answer": "终于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚开始工作，终于就买了房子。", "explanation": "这里应该用〈不久〉。终于强调经过长时间努力后的结果，不能用于刚开始工作就买房这种没有积累过程的情况；表示不久之后发生时要用〈不久〉。"}, {"text": "他终于每个月都买一套房子。", "explanation": "这里应该用〈总是〉。终于强调经过努力后一次性出现的结果，不能用来描述反复出现的常规行为；说明经常发生时要用〈总是〉。"}, {"text": "他躺在床上什么也没做，终于买了房子。", "explanation": "这里应该用〈轻易〉。终于强调经过努力后才出现的结果，不能用于完全没有付出努力的情况；表示不费力就得到时要用〈轻易〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终于", "is_correct": true, "explanation": "正确答案。“找了好几天”后找到工作，是经过长时间寻找的结果，“终于”正合语境。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”指白费力气，句中找到了工作，并不是白费。"}, {"text": "早就", "is_correct": false, "explanation": "体貌：“早就”表示很久以前已经发生，与“找了好几天”的过程相矛盾。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与这里经过寻找后得到的结果不符。"}], "explanations": {"终于": "正确答案。“找了好几天”后找到工作，是经过长时间寻找的结果，“终于”正合语境。", "白白": "语义：“白白”指白费力气，句中找到了工作，并不是白费。", "早就": "体貌：“早就”表示很久以前已经发生，与“找了好几天”的过程相矛盾。", "故意": "语义：“故意”表示有意为之，与这里经过寻找后得到的结果不符。"}, "sentence_index": 6, "correct_answer": "终于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚挂号，医生终于就叫到我了。", "explanation": "这里应该用〈很快〉。终于表示经过较长等待后才出现的结果，不能用于刚挂号就被叫到的情况；时间很短就发生时要用〈很快〉。"}, {"text": "他终于是医生，比我们懂得多。", "explanation": "这里应该用〈毕竟〉。终于不用来说明理由；要说明“他是医生所以懂得多”这类原因时要用〈毕竟〉。"}, {"text": "他的病我终于不清楚。", "explanation": "这里应该用〈根本〉。终于表示经过努力后出现的结果，不能用来加强否定；强调完全不清楚时要用〈根本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他练了很久，终于学会游泳。", "corrected_sentence": "他练了很久，终于学会了游泳。", "error_description": "错误在于缺少“了”。“终于”表示经过努力后结果已经出现，后面的动词通常要带“了”表示完成，应改为“终于学会了游泳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "找了好几天，我们很终于找回了那只猫。", "corrected_sentence": "找了好几天，我们终于找回了那只猫。", "error_description": "错误在于“很”修饰了“终于”。“终于”不能被“很”修饰，应去掉“很”，改为“终于找回了那只猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8b88368-13cb-44f4-a818-4a15d1157e32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分开", "is_correct": true, "explanation": "正确：分开与连结的意思相反，指把接在一起的东西拆开。"}, {"text": "修理", "is_correct": false, "explanation": "修理指把坏的东西修好，与使两物接合或断开无关。"}, {"text": "观看", "is_correct": false, "explanation": "观看指看，与把东西接合或分开的意思无关。"}, {"text": "储存", "is_correct": false, "explanation": "储存指保存物品，与接合或断开无关。"}], "correct_answer": "分开", "explanations": {"分开": "正确：分开与连结的意思相反，指把接在一起的东西拆开。", "修理": "修理指把坏的东西修好，与使两物接合或断开无关。", "观看": "观看指看，与把东西接合或分开的意思无关。", "储存": "储存指保存物品，与接合或断开无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆开", "is_correct": true, "explanation": "正确：拆开与连结成一体相反，指把整体分成几部分。"}, {"text": "种植", "is_correct": false, "explanation": "种植指栽种植物，与绳子的接合无关。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子考虑问题，与连结无关。"}, {"text": "购买", "is_correct": false, "explanation": "购买指花钱买东西，与连结无关。"}], "correct_answer": "拆开", "explanations": {"拆开": "正确：拆开与连结成一体相反，指把整体分成几部分。", "种植": "种植指栽种植物，与绳子的接合无关。", "思考": "思考指用脑子考虑问题，与连结无关。", "购买": "购买指花钱买东西，与连结无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连结是把两个东西接在一起。", "primary_collocate": null, "pronunciation": "lián jié", "ipa": "ljɛn˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "工人用绳子把两根铁管连结在一起。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用螺丝把两块钢板连结起来了。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电脑和电视连结好。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用胶水把两张纸连结了起来。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根电线连结着两个开关。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两节车厢连结得很紧。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把这根线和那根线连结一下。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用木板把两张桌子连结在一起。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根管子没有连结好，水漏出来了。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两条绳子连结成了一条长绳。", "target_word": "连结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连结了", "label": "体标"}, {"form": "连结着", "label": "体标"}, {"form": "连结过", "label": "体标"}, {"form": "連結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动手把两个具体物体接合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b140c7-e308-4628-aaa0-d46ef4cd89fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连结", "is_correct": true, "explanation": "正确：连结表示把两样东西接合在一起，符合句意。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：挑选是从多者中选取，与把铁管接在一起的意思不符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：讨论的对象是问题或意见，不能说“讨论铁管”。"}, {"text": "说", "is_correct": false, "explanation": "配价：说需要说的内容作宾语，“把铁管说在一起”不成立。"}], "explanations": {"连结": "正确：连结表示把两样东西接合在一起，符合句意。", "挑选": "语义：挑选是从多者中选取，与把铁管接在一起的意思不符。", "讨论": "搭配：讨论的对象是问题或意见，不能说“讨论铁管”。", "说": "配价：说需要说的内容作宾语，“把铁管说在一起”不成立。"}, "sentence_index": 0, "correct_answer": "连结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天连结了老师，问了一下作业的事。", "explanation": "这里应该用〈联系〉。联系指与人取得联络，连结指把具体物体接在一起，不用于跟人联络。"}, {"text": "他把衬衫的扣子连结好了。", "explanation": "这里应该用〈扣〉。扣子要扣上才能固定，连结指把物体接合，不说“连结扣子”。"}, {"text": "他把鞋带连结好了。", "explanation": "这里应该用〈系〉。鞋带要系或打结，连结不用于鞋带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连结", "is_correct": true, "explanation": "正确：连结表示把两样东西接在一起，句中是“把这根线和那根线连结一下”，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不能用来指线。"}, {"text": "逃", "is_correct": false, "explanation": "配价：逃是不及物动词，不能带“把”字宾语。"}, {"text": "敲", "is_correct": false, "explanation": "语义：敲是击打，与把两根线接在一起的意思不符。"}], "explanations": {"连结": "正确：连结表示把两样东西接在一起，句中是“把这根线和那根线连结一下”，符合句意。", "唱": "搭配：唱的对象是歌曲，不能用来指线。", "逃": "配价：逃是不及物动词，不能带“把”字宾语。", "敲": "语义：敲是击打，与把两根线接在一起的意思不符。"}, "sentence_index": 6, "correct_answer": "连结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月他连结了一笔奖金。", "explanation": "这里应该用〈领取〉。领取指拿到应得的钱或物，连结指使具体物体接合，不用于奖金。"}, {"text": "他把画连结在墙上。", "explanation": "这里应该用〈挂〉。挂画是悬挂，连结指物体接合，不用于把画挂在墙上。"}, {"text": "我连结了全班同学，告诉大家明天考试。", "explanation": "这里应该用〈通知〉。通知是告诉别人消息，连结不用于告知人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "师傅把两根管子连结一起。", "corrected_sentence": "师傅把两根管子连结在一起。", "error_description": "错误：“连结”后漏掉介词“在”。“在一起”是处所补语，表示结合为一体，应说“连结在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几根木棍连结下来了。", "corrected_sentence": "几根木棍连结起来了。", "error_description": "错误：补语应为“起来”，不能用“下来”。“连结起来”表示使分散的物体接合为一体，“下来”表示由上往下，不符合句意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隔绝", "is_correct": true, "explanation": "正确：隔绝指使彼此不能相通，与连结使地点相通的意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与地点之间是否相通无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏指赏析美好的事物，与相通或隔断无关。"}, {"text": "介绍", "is_correct": false, "explanation": "介绍指使人或事物为人所知，与相通关系无关。"}], "correct_answer": "隔绝", "explanations": {"隔绝": "正确：隔绝指使彼此不能相通，与连结使地点相通的意思相反。", "观察": "观察指仔细看，与地点之间是否相通无关。", "欣赏": "欣赏指赏析美好的事物，与相通或隔断无关。", "介绍": "介绍指使人或事物为人所知，与相通关系无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86712, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "割断", "is_correct": true, "explanation": "正确：割断指把连着的东西切开，与连结成网的意思相反。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美指称赞好的方面，与连结或割断无关。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意走动，与小路是否相连无关。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰指美化外观，与连结或割断无关。"}], "correct_answer": "割断", "explanations": {"割断": "正确：割断指把连着的东西切开，与连结成网的意思相反。", "赞美": "赞美指称赞好的方面，与连结或割断无关。", "散步": "散步指随意走动，与小路是否相连无关。", "装饰": "装饰指美化外观，与连结或割断无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63a6e138-c20d-4a52-81ce-9599688f9dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
